# Orari di notifiche ed eventi: la VM di solito è in UTC, gli orari vanno mostrati in ora italiana
try:
    from zoneinfo import ZoneInfo
    LOCAL_TZ = ZoneInfo(os.getenv("TIMEZONE", "Europe/Rome"))
    SERVER_TZ_NAME = os.getenv("TIMEZONE", "Europe/Rome")
except Exception:  # noqa: BLE001 — senza tzdata uso l'ora di sistema
    LOCAL_TZ = None
    SERVER_TZ_NAME = ""


# Fuso orario di chi guarda: ognuno (utente o amministratore) può sceglierne uno nel suo account.
# Le API lo impostano per la richiesta (ui_user, admin_user), gli avvisi per il destinatario
# (viewer_tz); altrimenti vale quello del server (TIMEZONE nel .env).
VIEW_TZ = contextvars.ContextVar("view_tz", default=None)
_tz_cache = {}


def tz_named(name):
    """ZoneInfo di un nome IANA valido («Europe/Rome»), altrimenti None."""
    name = str(name or "").strip()
    if not name or len(name) > 64 or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_+\-]*(/[A-Za-z0-9_+\-]+)*", name):
        return None
    if name not in _tz_cache:
        try:
            from zoneinfo import ZoneInfo
            _tz_cache[name] = ZoneInfo(name)
        except Exception:  # noqa: BLE001 — nome sconosciuto o tzdata mancante
            _tz_cache[name] = None
    return _tz_cache[name]


class viewer_tz:
    """with viewer_tz("America/New_York"): gli orari composti qui dentro sono in quel fuso."""
    def __init__(self, name):
        self.tz = tz_named(name)

    def __enter__(self):
        self.token = VIEW_TZ.set(self.tz)

    def __exit__(self, *exc):
        VIEW_TZ.reset(self.token)


def local_time(ts, fmt="%d/%m %H:%M"):
    return datetime.fromtimestamp(ts, VIEW_TZ.get() or LOCAL_TZ).strftime(fmt)
DATA_DIR.mkdir(parents=True, exist_ok=True)

# Ripristino di un backup completo (pannello, Server › Backup e ripristino): il pannello prepara i
# file in data/ripristino/ e riavvia il servizio; qui, prima di aprire qualunque database, i dati di
# adesso vanno da parte in data/prima-del-ripristino-<data>/ (resta solo l'ultima) e quelli del backup
# prendono il loro posto.
RESTORE_DIR = DATA_DIR / "ripristino"
BACKUP_FILES = ("auth.db", "events.db", "state.json", "speedtests.json", "scans.json", "inactive.json",
                "privacy.html")


def restore_apply():
    if not (RESTORE_DIR / "PRONTO").is_file():
        return
    for old in DATA_DIR.glob("prima-del-ripristino-*"):
        shutil.rmtree(old, ignore_errors=True)
    old = DATA_DIR / ("prima-del-ripristino-" + time.strftime("%Y%m%d-%H%M%S"))
    old.mkdir(mode=0o700)
    for name in BACKUP_FILES:
        for f in (DATA_DIR / name, DATA_DIR / (name + "-wal"), DATA_DIR / (name + "-shm")):
            if f.exists():
                os.replace(f, old / f.name)
    for name in BACKUP_FILES:
        if (RESTORE_DIR / name).is_file():
            os.replace(RESTORE_DIR / name, DATA_DIR / name)
    shutil.rmtree(RESTORE_DIR, ignore_errors=True)
    logging.getLogger("netmon").warning("Backup completo ripristinato; i dati di prima sono in %s", old)


restore_apply()
