class DeviceInfo(BaseModel):
    ok: bool
    host: Optional[str] = Field(default=None, max_length=253)
    # con i limiti NaN e infinito sono rifiutati: non sono JSON valido e farebbero fallire le risposte
    rtt: Optional[float] = Field(default=None, ge=0, le=3_600_000)
    # ping fallito, ma una delle porte trovate aperte dall'ultimo controllo di sicurezza risponde
    port: Optional[int] = Field(default=None, ge=1, le=65535)


# \Z e non $: $ accetta anche un a capo finale («router\n»)
NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9 _.\-]{0,39}\Z")
HOST_RE = re.compile(r"^(?=.{1,253}\Z)[A-Za-z0-9](?:[A-Za-z0-9\-]{0,61}[A-Za-z0-9])?"
                     r"(?:\.[A-Za-z0-9](?:[A-Za-z0-9\-]{0,61}[A-Za-z0-9])?)*\Z")


def valid_ip(host):
    """Indirizzo IP vero, come lo controlla la sonda (valid_host in probe.py). Con la vecchia regola
    sui soli caratteri il server salvava anche «0:» o «..», che la sonda poi rifiutava: e con un
    dispositivo non valido la sonda scarta TUTTA la configurazione arrivata dal server."""
    try:
        ipaddress.ip_address(host)
    except ValueError:
        return False
    return "%" not in host               # niente zona IPv6 (fe80::1%eth0)


class ProbeConfig(BaseModel):
    """Configurazione della sonda gestibile anche dal server."""
    devices: dict[str, str] = Field(min_length=1, max_length=200)
    interval: int = Field(ge=10, le=3600)
    ping_count: int = Field(ge=1, le=10)
    ping_timeout: int = Field(ge=1, le=10)
    fail_threshold: int = Field(ge=1, le=20)
    alert_mode: Literal["proporzionale", "fisso"]
    stale_factor: float = Field(ge=1, le=20)
    offline_factor: float = Field(ge=1, le=20)
    stale_seconds: int = Field(ge=10, le=86400)
    offline_seconds: int = Field(ge=10, le=86400)
    traffic_interval: int = Field(default=30, ge=0, le=300)   # 0 = campionamento spento
    probe_name: Optional[str] = Field(default=None, max_length=40)   # nome mostrato (Rinomina)
    ping_parallel: int = Field(default=2, ge=1, le=16)        # ping contemporanei

    @field_validator("traffic_interval")
    @classmethod
    def check_traffic(cls, v):
        if v != 0 and v < 2:
            raise ValueError("il campionamento del traffico deve essere 0 o almeno 2 secondi")
        return v

    @field_validator("devices")
    @classmethod
    def check_devices(cls, v):
        for name, host in v.items():
            if not NAME_RE.match(name):
                raise ValueError(f"nome dispositivo non valido: {name}")
            if not HOST_RE.match(host) and not valid_ip(host):
                raise ValueError(f"indirizzo non valido: {host}")
        return v


