def check_device_names(v):
    """Nomi dei dispositivi inviati dalla sonda: brevi e senza caratteri di controllo."""
    for name in v:
        if not name or len(name) > 64 or any(ord(ch) < 32 or ord(ch) == 127 for ch in name):
            raise ValueError("nome dispositivo non valido")
    return v


# Altri FRITZ!Box di una sonda (oltre al primo): id scelto dalla pagina locale della sonda
FRITZ_MAX = 4
FRITZ_ID_RE = re.compile(r"^[a-z0-9]{1,16}$")


def check_traffic_more(v):
    """Traffico degli altri FRITZ: al massimo FRITZ_MAX, id validi, 5000 campioni ciascuno."""
    if v is None:
        return v
    if len(v) > FRITZ_MAX or any(not FRITZ_ID_RE.match(k) or k == "main" for k in v):
        raise ValueError("traffico degli altri FRITZ!Box non valido")
    if any(len(x) > 5000 for x in v.values()):
        raise ValueError("troppi campioni di traffico")
    return v


class Report(BaseModel):
    probe: str = Field(min_length=1, max_length=64)
    interval: Optional[float] = Field(default=None, ge=5, le=3600)
