def finite(v):
    """Il numero, se è un numero finito; altrimenti None. NaN e infinito (che una sonda può inviare
    nei campi liberi) non sono JSON valido: una risposta che li contiene fallisce per intero, e lo
    stato delle sonde finisce anche nelle pagine degli amministratori."""
    try:
        return v if isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v) else None
    except OverflowError:             # intero troppo grande per essere un numero utile
        return None


CONTROL_CHARS = re.compile(r"[\x00-\x1f\x7f\u2028\u2029]")


def scrub(v):
    """Copia di un valore JSON con i numeri non finiti sostituiti da None e senza caratteri di
    controllo nei testi (nomi scelti da chi è sulla rete ospiti finiscono in email e Telegram)."""
    if isinstance(v, str):
        return CONTROL_CHARS.sub("", v)
    if isinstance(v, float):
        return v if math.isfinite(v) else None
    if isinstance(v, dict):
        return {k: scrub(x) for k, x in v.items()}
    if isinstance(v, list):
        return [scrub(x) for x in v]
    return v


def load_state():
    try:
        # scrub: ripulisce anche ciò che una versione precedente avesse già salvato
        state = scrub(json.loads(STATE_FILE.read_text()))
        return state if isinstance(state, dict) else {}
    except (FileNotFoundError, json.JSONDecodeError):
        return {}


_state_dirty = [False]


def save_state():
    """Segna lo stato da salvare: il file viene scritto al più ogni CHECK_INTERVAL secondi
    (e alla chiusura del server), non a ogni report di ogni sonda."""
    _state_dirty[0] = True


def flush_state():
    if not _state_dirty[0]:
        return
    _state_dirty[0] = False
    tmp = STATE_FILE.with_suffix(".tmp")
    tmp.write_text(json.dumps(monitor.state, separators=(",", ":")))
    tmp.replace(STATE_FILE)


# Per quanto si conservano misure ed eventi. Si sceglie nel pannello (scheda Server →
# Conservazione dei dati); RETENTION_DAYS nel .env vale solo finche' nessuno ha scelto.
RETENTION_DAYS = int(os.getenv("RETENTION_DAYS", "30"))
RETENTION_UNITS = {"giorni": 1, "settimane": 7, "mesi": 30}        # un mese = 30 giorni
RETENTION_MAX = {"giorni": 3650, "settimane": 520, "mesi": 120}      # tetto: dieci anni
OLDEST_ACCEPTED_DAYS = 3650        # con «conserva tutto»: misure piu' vecchie sono timestamp assurdi
_retention = {}                    # (valore, unita') letti una volta: la scelta cambia solo da qui


def retention():
    """(valore, unita') scelti: (None, "sempre") = conserva tutto."""
    if not _retention:
        unita = auth.get_setting("retention_unit")
        valore = auth.get_setting("retention_value") or ""
        if unita == "sempre":
            _retention["v"] = (None, "sempre")
        elif unita in RETENTION_UNITS and valore.isdigit() and 1 <= int(valore) <= RETENTION_MAX[unita]:
            _retention["v"] = (int(valore), unita)
        else:
            _retention["v"] = (RETENTION_DAYS, "giorni")
    return _retention["v"]


def retention_days():
    """Giorni di storico da conservare, oppure None per conservare tutto."""
    valore, unita = retention()
    return None if unita == "sempre" else valore * RETENTION_UNITS[unita]


# Ogni utente puo' scegliere la sua conservazione (scheda Backup → Conservazione dei dati); chi non
# sceglie segue quella del server. Le scelte si leggono una volta e si rileggono quando cambiano
# (e ogni ora, per gli account arrivati da un'altra VM).
_user_retention = {}


def user_retention(uid):
    """(valore, unita') scelti dall'utente, oppure (None, None) se segue quella del server."""
    if "all" not in _user_retention:
        _user_retention["all"] = auth.retentions()
    return _user_retention["all"].get(uid, (None, None)) if uid else (None, None)


def user_retention_days(uid):
    """Giorni di storico da conservare per le sonde di questo utente, oppure None per tutto."""
    valore, unita = user_retention(uid)
    if unita is None:
        return retention_days()
    return None if unita == "sempre" else valore * RETENTION_UNITS[unita]


def oldest_accepted(now, probe=None):
    """Prima di quando una misura in arrivo e' da scartare: fuori dallo storico conservato."""
    giorni = user_retention_days(registry.owner_of(probe)) if probe else retention_days()
    return now - (giorni or OLDEST_ACCEPTED_DAYS) * 86400

# Finestre dello storico: durata mostrata -> ampiezza di ogni punto del grafico
RANGES = {"1h": (3600, 120), "6h": (6 * 3600, 300), "24h": (24 * 3600, 900),
          "7d": (7 * 86400, 3600), "30d": (30 * 86400, 6 * 3600)}


# Il traffico ha campioni più fitti: punti più fini nelle finestre brevi
TRAFFIC_RANGES = {"1h": (3600, 30), "6h": (6 * 3600, 120), "24h": (24 * 3600, 600),
                  "7d": (7 * 86400, 3600), "30d": (30 * 86400, 6 * 3600)}
# Un campione delle metriche FRITZ!Box al massimo ogni tanti secondi per sonda e box
FRITZ_HIST_MIN = 30


# Ampiezze "tonde" dei punti del grafico, scelte in base alla durata del periodo personalizzato
NICE_BUCKETS = [10, 30, 60, 120, 300, 600, 900, 1800, 3600, 7200, 10800, 21600, 43200, 86400]
SYSTEM_RANGES = {k: (span, max(bucket, 120)) for k, (span, bucket) in RANGES.items()}


def time_window(range_: str, start, end, presets: dict, minimum: int):
    """(inizio, fine, ampiezza dei punti). Con range_='custom' usa start/end (secondi epoch)."""
    now = time.time()
    if range_ != "custom":
        span, bucket = presets.get(range_, presets["6h"])
        return now - span, now, bucket
    if start is None or end is None:
        raise HTTPException(status_code=422, detail="Indica inizio e fine del periodo.")
    # «nan» e «inf» sono numeri validi per la query string ma superano tutti i confronti qui sotto,
    # e la risposta (since/now non finiti) non si poteva più scrivere in JSON: errore 500
    if not (math.isfinite(start) and math.isfinite(end)):
        raise HTTPException(status_code=422, detail="Inizio e fine del periodo non validi.")
    end = min(float(end), now)
    start = float(start)
    if end - start < 60:
        raise HTTPException(status_code=422, detail="Il periodo deve durare almeno un minuto (e la fine venire dopo l'inizio).")
    if end - start > 400 * 86400:
        raise HTTPException(status_code=422, detail="Il periodo può durare al massimo 400 giorni.")
    target = max((end - start) / 150, minimum)          # circa 150 punti per grafico
    bucket = next((b for b in NICE_BUCKETS if b >= target), NICE_BUCKETS[-1])
    return start, end, bucket


def db():
    """Connessione al database (lo schema si prepara una volta sola, all'avvio)."""
    conn = sqlite3.connect(DB_FILE, timeout=10, factory=ClosingConnection)   # il «with» la chiude
    conn.execute("PRAGMA synchronous=NORMAL")        # con WAL: sicuro e con molte meno scritture su disco
    return conn


def init_db():
    conn = sqlite3.connect(DB_FILE, timeout=10)
    conn.execute("PRAGMA journal_mode=WAL")          # letture e scritture non si bloccano a vicenda
    conn.execute("CREATE TABLE IF NOT EXISTS events "
                 "(ts REAL, title TEXT, body TEXT, critical INTEGER, recovery INTEGER)")
    conn.execute("CREATE TABLE IF NOT EXISTS samples "
                 "(ts REAL, probe TEXT, device TEXT, ok INTEGER, rtt REAL)")
    conn.execute("CREATE TABLE IF NOT EXISTS system_samples (ts REAL, probe TEXT, temp REAL, load1 REAL)")
    conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS system_uniq ON system_samples (probe, ts)")
    # carico della CPU, memoria e disco usati, in percentuale (prima c'erano solo temperatura e carico)
    scols = {r[1] for r in conn.execute("PRAGMA table_info(system_samples)")}
    for col in ("cpu", "mem", "disk"):
        if col not in scols:
            conn.execute(f"ALTER TABLE system_samples ADD COLUMN {col} REAL")
    if "probe" not in {r[1] for r in conn.execute("PRAGMA table_info(events)")}:
        conn.execute("ALTER TABLE events ADD COLUMN probe TEXT")      # eventi della versione precedente
    conn.execute("CREATE TABLE IF NOT EXISTS traffic "
                 "(ts REAL, probe TEXT, up REAL, down REAL, dt REAL, box TEXT NOT NULL DEFAULT '')")
    # box: quale FRITZ!Box della sonda ('' = il primo, come nelle versioni precedenti). L'indice
    # unico comprende il FRITZ: due FRITZ principali della stessa sonda possono avere campioni allo
    # stesso istante.
    if "box" not in {r[1] for r in conn.execute("PRAGMA table_info(traffic)")}:
        conn.execute("ALTER TABLE traffic ADD COLUMN box TEXT NOT NULL DEFAULT ''")
    conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS traffic_box_uniq ON traffic (probe, box, ts)")
    conn.execute("DROP INDEX IF EXISTS traffic_uniq")
    try:
        # Un campione per dispositivo e istante: i reinvii dal buffer non creano doppioni.
        # Serve anche alle ricerche dello storico, quindi il vecchio indice uguale è superfluo.
        conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS samples_uniq ON samples (probe, device, ts)")
        conn.execute("DROP INDEX IF EXISTS samples_idx")
    except sqlite3.IntegrityError:
        conn.execute("CREATE INDEX IF NOT EXISTS samples_idx ON samples (probe, device, ts)")
    conn.execute("CREATE INDEX IF NOT EXISTS events_probe_ts ON events (probe, ts)")
    conn.execute("CREATE TABLE IF NOT EXISTS speedtests "
                 "(ts REAL, probe TEXT, down REAL, up REAL, ping REAL, jitter REAL, server TEXT)")
    conn.execute("CREATE INDEX IF NOT EXISTS speedtests_probe_ts ON speedtests (probe, ts)")
    if "auto" not in {r[1] for r in conn.execute("PRAGMA table_info(speedtests)")}:
        conn.execute("ALTER TABLE speedtests ADD COLUMN auto INTEGER NOT NULL DEFAULT 0")   # 1 = test periodico
    if "link" not in {r[1] for r in conn.execute("PRAGMA table_info(speedtests)")}:
        conn.execute("ALTER TABLE speedtests ADD COLUMN link TEXT")      # wifi o lan; vuoto nei test di prima
    conn.execute("CREATE TABLE IF NOT EXISTS fritz_hist "
                 "(ts REAL, probe TEXT, box TEXT NOT NULL DEFAULT '', down REAL, up REAL, "
                 "max_down REAL, max_up REAL, lan REAL, wifi TEXT)")
    conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS fritz_hist_uniq ON fritz_hist (probe, box, ts)")
    conn.commit()
    conn.close()


init_db()


monitor = Monitor(
    fail_threshold=int(os.getenv("FAIL_THRESHOLD", "3")),
    heartbeat_factor=float(os.getenv("HEARTBEAT_FACTOR", "3")),
    stale_factor=float(os.getenv("STALE_FACTOR", "1.5")),
    default_interval=int(os.getenv("DEFAULT_INTERVAL", "60")),
    remind_minutes=int(os.getenv("REMIND_MINUTES", "60")),
    # priorità bassa: quante volte la soglia normale (×2 = il doppio dei controlli); si può
    # cambiare per singola sonda
    low_factor=int(os.getenv("LOW_FACTOR", "2")),
    state=load_state(),
)
lock = asyncio.Lock()


def owner_tz(key):
    """Fuso orario scelto dal proprietario della sonda ("" = quello del server)."""
    owner = registry.owner_of(key) if key else None
    user = auth.get_user(owner) if owner else None
    return (user or {}).get("tz") or ""


def recipients(key):
    """Canali di notifica del proprietario della sonda: la sua email (se l'ha confermata e non
    l'ha disattivata) e, se indicati, il suo chat ID Telegram e il suo topic ntfy. Il file .env
    contiene solo da dove partono i messaggi (account email e bot Telegram), mai i destinatari.
    Sonda senza proprietario o utente bloccato: nessuna notifica.
    Email non confermata: nessun avviso via email, perché l'indirizzo potrebbe essere di un altro."""
    owner = registry.owner_of(key) if key else None
    user = auth.get_user(owner) if owner else None
    if user is None or user["blocked"]:            # utente bloccato: le sonde misurano, niente avvisi
        return False, None
    email_ok = user["notify_email"] and user["email_verified"] and "@" in user["email"]
    # interruttore spento: il canale tace, chat ID e topic restano salvati per quando si riaccende
    return True, {"email": user["email"] if email_ok else "",
                  "telegram_chat": user["telegram_chat"] if user["telegram_on"] else "",
                  "ntfy_url": user["ntfy_url"] if user["ntfy_on"] else "", "owner": owner,
                  "routes": user["routes"], "lang": user["lang"], "tz": user["tz"]}


# Tetto alle notifiche per utente. Email e Telegram partono da account condivisi da tutti (SMTP_*
# e il bot): senza un tetto, una sola sonda che genera avvisi a raffica esaurirebbe la quota di
# invio di tutti e terrebbe occupato il server. Oltre il tetto gli avvisi restano negli Ultimi
# eventi della pagina, ma non vengono più inviati finché il ritmo non rientra.
NOTIFY_PER_HOUR = int(os.getenv("NOTIFY_PER_HOUR", "60"))
_notify_sent = {}                 # proprietario -> orari delle ultime notifiche inviate
_notify_paused = set()            # proprietari già avvisati della sospensione
_notify_lock = threading.Lock()


def notify_allowed(owner, now):
    """(invia, prima_volta_oltre_il_tetto) per una notifica al proprietario indicato."""
    with _notify_lock:                # le notifiche partono da più thread
        sent = _notify_sent.setdefault(owner, deque())
        while sent and now - sent[0] > 3600:
            sent.popleft()
        if len(sent) < NOTIFY_PER_HOUR:
            sent.append(now)
            _notify_paused.discard(owner)
            return True, False
        first = owner not in _notify_paused
        _notify_paused.add(owner)
        return False, first


def _dispatch_sync(alerts):
    """Unico punto da cui escono gli avvisi: registro eventi e canali del proprietario.

    Le sonde in pausa non producono niente, nemmeno una riga negli eventi: «in pausa» vuol dire
    silenzio, altrimenti la pagina si riempirebbe comunque di righe rosse per una sonda che si sa
    gia' essere spenta. I dati continuano ad arrivare e a essere salvati: e' solo il rumore a
    fermarsi.
    """
    in_pausa = registry.paused_keys()
    alerts = [a for a in alerts if not (a.key and a.key in in_pausa)]
    if not alerts:
        return
    with db() as conn:
        conn.executemany("INSERT INTO events (ts, title, body, critical, recovery, probe) VALUES (?,?,?,?,?,?)",
                         [(time.time(), a.title, a.body, a.critical, a.recovery, a.key or None) for a in alerts])
    for a in alerts:
        log.warning("ALERT: %s", a.title)
        send, to = recipients(a.key)
        if not send:
            log.info("Avviso «%s» non inviato: sonda senza proprietario o utente bloccato", a.title[:80])
            continue
        ok, first = notify_allowed(to["owner"], time.time())
        if ok:
            notify(a.title, a.body, a.critical, a.recovery, a.subject, to, a.kind)
        elif first:
            log.warning("Notifiche sospese per l'utente %s: più di %d in un'ora", to["owner"], NOTIFY_PER_HOUR)
            notify("[ATTENZIONE] Troppi avvisi: notifiche sospese",
                   f"Le tue sonde hanno generato più di {NOTIFY_PER_HOUR} avvisi in un'ora. Per non "
                   "esaurire gli invii del server, i prossimi non ti vengono inviati finché il ritmo non "
                   "rientra: li trovi comunque negli Ultimi eventi della pagina di stato.\n\n"
                   "Di solito è un dispositivo che va e viene: puoi alzare i controlli falliti prima "
                   "dell'alert in Impostazioni → Controlli, oppure toglierlo dall'elenco.", True, False, "", to)


ALERT_DEFAULTS = {"guest": False, "guest_grace": 30, "mesh": False}


MESH_NODES, MESH_CLIENTS = 10, 60
MESH_BANDS = ("cavo", "2,4 GHz", "5 GHz", "6 GHz", "Wi-Fi")
FIBER_KEY_RE = re.compile(r"^[A-Za-z0-9_\-]{1,40}$")


def _kbit(v):
    """Velocità in kbit/s della mappa mesh: intero tra 0 e 100 Gbit/s, altrimenti None."""
    v = finite(v)
    return int(v) if v is not None and 0 <= v <= 1e8 else None


def _dbm(v):
    v = finite(v)
    return int(v) if v is not None and -120 <= v <= 0 else None


def clean_mesh(raw):
    """Riassunto della mappa mesh inviato dalla sonda (vedi parse_mesh in probe.py): ricostruito
    campo per campo, con nomi brevi e numeri plausibili."""
    if not isinstance(raw, dict) or not isinstance(raw.get("nodes"), list):
        return None
    nodes = []
    for n in raw["nodes"][:MESH_NODES]:
        if not isinstance(n, dict):
            continue
        up = n.get("up") if isinstance(n.get("up"), dict) else None
        clients = []
        for c in (n.get("clients") or [])[:MESH_CLIENTS] if isinstance(n.get("clients"), list) else []:
            if isinstance(c, dict):
                clients.append({"name": str(c.get("name") or "?")[:40],
                                "band": c.get("band") if c.get("band") in MESH_BANDS else "Wi-Fi",
                                "rate": _kbit(c.get("rate")), "signal": _dbm(c.get("signal")),
                                "weak": bool(c.get("weak"))})
        nodes.append({"name": str(n.get("name") or "FRITZ!")[:40], "model": str(n.get("model") or "")[:40],
                      "master": bool(n.get("master")), "parent": str(n.get("parent") or "")[:40],
                      "up": None if up is None else {
                          "type": up.get("type") if up.get("type") in MESH_BANDS else "Wi-Fi",
                          "rate": _kbit(up.get("rate")), "max": _kbit(up.get("max")), "signal": _dbm(up.get("signal"))},
                      "clients": clients, "more": int(finite(n.get("more")) or 0)})
    if not nodes:
        return None
    return scrub({"nodes": nodes, "clients": sum(len(n["clients"]) + n["more"] for n in nodes)})


def clean_fiber(raw):
    """Stato della fibra: i valori semplici così come li dà il FRITZ!OS (al massimo 30)."""
    if not isinstance(raw, dict):
        return None
    out = {}
    for k, v in list(raw.items())[:30]:
        if not isinstance(k, str) or not FIBER_KEY_RE.match(k):
            continue
        if isinstance(v, bool) or (isinstance(v, str) and len(v) <= 100):
            out[k] = v
        elif finite(v) is not None:
            out[k] = v
    return out or None


# Mappa mesh e fibra arrivano ogni 5 minuti, non a ogni report: fra un invio e l'altro resta
# quella ricevuta, finché ha meno di MESH_KEEP secondi.
MESH_KEEP = 900


def carry_mesh(old, new, now):
    for k in ("mesh", "fiber", "netdev"):
        if k in new:
            new[k + "_ts"] = now
        elif (old or {}).get(k) and now - float(old.get(k + "_ts") or 0) < MESH_KEEP:
            new[k], new[k + "_ts"] = old[k], old[k + "_ts"]
    return new


def mesh_node_for(box, mesh):
    """Nodo della mappa mesh che corrisponde a un FRITZ «solo Wi-Fi» della sonda: stesso nome,
    oppure l'unico repeater di quel modello. None se non si trova."""
    reps = [n for n in (mesh or {}).get("nodes") or [] if not n.get("master")]
    name = str(box.get("name") or "").strip().lower()
    hit = next((n for n in reps if name and n["name"].lower() == name), None)
    if hit is None and box.get("model"):
        same = [n for n in reps if n.get("model") == box["model"]]
        hit = same[0] if len(same) == 1 else None
    return hit


def repeater_from_mesh(box, mesh):
    """Per un repeater: collegamento alla mesh, dispositivi via cavo e banda in uso.
    La banda viene dai contatori della sua porta LAN: con il collegamento alla mesh via cavo è
    tutto il suo traffico (download = ricevuto dalla rete); con il collegamento Wi-Fi è solo quello
    dei dispositivi via cavo (download = inviato a loro)."""
    # solo numeri finiti e non negativi: finiscono in float() nello storico del traffico (report)
    rx, tx = (v if (v := finite(box.pop(k, None))) is not None and v >= 0 else None
              for k in ("lan_rx_rate", "lan_tx_rate"))
    dt = finite(box.pop("lan_dt", None))
    n = mesh_node_for(box, mesh)
    if n is None:
        return box
    up = n.get("up")
    box["uplink"] = up
    box["lan_clients"] = sum(1 for c in n.get("clients") or [] if c.get("band") == "cavo")
    if rx is not None and tx is not None:
        if up and up.get("type") == "cavo":
            box["rate_down"], box["rate_up"] = rx, tx
            box["rate_dt"] = dt if dt and 0 < dt <= 3600 else None
        else:
            box["lan_down"], box["lan_up"] = tx, rx
    return box


NETDEV_MAX = 200
NETDEV_IP = re.compile(r"[0-9A-Fa-f:.]{0,45}")


def clean_netdev(raw):
    """Dispositivi in rete dal FRITZ!Box: solo i campi previsti, con tipi e lunghezze controllati
    (nomi e modelli li sceglie chi è sulla rete)."""
    if not isinstance(raw, list):
        return None
    out = []
    for d in raw[:NETDEV_MAX]:
        if not isinstance(d, dict):
            continue
        txt = lambda k, n: CONTROL_CHARS.sub("", d[k])[:n] if isinstance(d.get(k), str) else ""   # noqa: E731
        num = lambda k, lo, hi: (int(v) if (v := finite(d.get(k))) is not None and lo <= v <= hi else None)  # noqa: E731
        ip = d.get("ip") if isinstance(d.get("ip"), str) and NETDEV_IP.fullmatch(d["ip"]) else ""
        out.append({"name": txt("name", 60), "ip": ip, "on": d.get("on") is True,
                    "via": d.get("via") if d.get("via") in ("wifi", "lan") else "",
                    "port": num("port", 1, 64), "node": txt("node", 40) or None,
                    "band": txt("band", 16) or None, "signal": num("signal", -120, 0),
                    "rate": num("rate", 0, 100_000), "model": txt("model", 60), "guest": d.get("guest") is True})
    return out


def netdev_seen(p, devs, now):
    """Ultima volta che il server ha visto collegato ogni dispositivo (per «visto 2 ore fa» di quelli
    spenti): il FRITZ!Box non lo dice. Chiave: nome, o IP per i dispositivi senza nome."""
    seen = p.setdefault("netdev_seen", {})
    for d in devs:
        k = d["name"] or d["ip"]
        if not k:
            continue
        if d["on"]:
            seen[k] = now
        elif k in seen:
            d["seen"] = seen[k]
    if len(seen) > 500:                                   # i più vecchi se ne vanno
        for k in sorted(seen, key=seen.get)[:len(seen) - 500]:
            seen.pop(k)
    return devs


def clean_fritz(raw):
    """Tiene solo valori semplici e l'elenco ospiti, con dimensioni limitate e numeri finiti."""
    out = {}
    for k, v in list(raw.items())[:40]:
        if len(k) > MAX_FIELD_NAME:
            continue
        if k == "mesh":
            m = clean_mesh(v)
            if m:
                out[k] = m
        elif k == "fiber":
            f = clean_fiber(v)
            if f:
                out[k] = f
        elif k == "netdev":
            nd = clean_netdev(v)
            if nd is not None:
                out[k] = nd
        elif k == "wlans" and isinstance(v, list):
            out[k] = [{"ssid": str(w.get("ssid", ""))[:64], "band": str(w.get("band", ""))[:16],
                       "clients": int(finite(w.get("clients")) or 0), "guest": bool(w.get("guest"))}
                      for w in v[:8] if isinstance(w, dict)]
        elif k == "guests" and isinstance(v, list):
            out[k] = [{kk: scrub(vv) for kk, vv in g.items()
                       if kk in ("mac", "ip", "name", "signal")
                       and isinstance(vv, (str, int, float, type(None)))
                       and (not isinstance(vv, str) or len(vv) <= 100)}
                      for g in v[:50] if isinstance(g, dict) and isinstance(g.get("mac"), str) and g["mac"]]
        elif k in ("wlans", "guests"):
            continue              # non è un elenco: guest_alerts e fritz_row li scorrerebbero (errore 500)
        elif isinstance(v, (str, int, float, bool, type(None))) and (not isinstance(v, str) or len(v) <= 200):
            out[k] = scrub(v)
    return out


def clean_fritz_boxes(raw, old=None):
    """Altri FRITZ!Box della sonda: id, nome e ruolo più lo stesso riepilogo del primo.
    Gli avvisi sugli ospiti restano legati al primo FRITZ!Box."""
    prev = {b.get("id"): b for b in old or [] if isinstance(b, dict)}
    out, seen = [], set()
    for b in raw[:FRITZ_MAX]:
        bid = str(b.get("id") or "")
        if not FRITZ_ID_RE.match(bid) or bid in seen:
            continue
        seen.add(bid)
        f = clean_fritz({k: v for k, v in b.items() if k not in ("id", "name", "role")})
        f.update(id=bid, name=str(b.get("name") or "")[:40], role="wifi" if b.get("role") == "wifi" else "main",
                 ts=time.time())
        out.append(carry_mesh(prev.get(bid), f, time.time()))
    return out


COMMAND_NAMES = {"reboot": "Riavvio", "upgrade": "Aggiornamento del sistema", "update": "Aggiornamento di netmon",
                 "wifi": "Rete Wi-Fi"}
# Password delle reti Wi-Fi in attesa di consegna alla sonda: solo in memoria (mai in state.json),
# tolte appena la sonda prende in carico il comando. Se il server si riavvia prima, la richiesta
# va ripetuta.
_wifi_secrets = {}                 # id del comando -> password della rete


def limits_of_user(user_id):
    """Limiti dell'account, in totale su tutte le sue sonde: quelli del piano, quelli scelti
    dall'amministratore, o i default. Un account sconosciuto (sonda orfana) ha i default."""
    r = auth.limits_of(user_id) if user_id else {}
    max_probes = r.get("max_probes")
    max_fritz = r.get("max_fritz")
    max_devices = r.get("max_devices")
    plan = r.get("plan")
    if plan in PLANS:
        max_probes, max_fritz, max_devices = PLANS[plan]
    return {"max_probes": MAX_PROBES_PER_USER if max_probes is None else int(max_probes),
            "max_fritz": FRITZ_TOTAL_DEFAULT if max_fritz is None else int(max_fritz),
            "max_devices": DEVICES_TOTAL_DEFAULT if max_devices is None else int(max_devices),
            "plan": plan}


def account_allowance(owner):
    """Quota di ogni sonda dell'account: quanti FRITZ!Box (il primo compreso) e quanti dispositivi
    può avere, dato che i limiti valgono per tutto l'account. Le sonde si servono in ordine di
    creazione: la prima prende quello che le serve, le altre quello che resta. Così un limite
    superato toglie qualcosa alle sonde più recenti, mai a quelle che c'erano prima."""
    lim = limits_of_user(owner)
    f_left, d_left = lim["max_fritz"], lim["max_devices"]
    out = {}
    for k in (registry.keys_of(owner) if owner else []):
        p = monitor.state.get(k) or {}
        out[k] = {"fritz": f_left, "devices": d_left}
        f_used = (1 if p.get("fritz") else 0) + len(p.get("fritz_boxes") or [])
        ferme = registry.device_pauses(k)
        d_used = len([n for n in ((p.get("config") or {}).get("devices") or {}) if n not in ferme])
        f_left -= min(f_used, f_left)
        d_left -= min(d_used, d_left)
    return out


def allowance_of(key):
    """Quota della sonda (vedi account_allowance). Una sonda senza account: i limiti di una volta."""
    owner = registry.owner_of(key)
    if not owner:
        return {"fritz": 1 + FRITZ_MAX, "devices": DEVICES_PER_PROBE}
    return account_allowance(owner).get(key) or {"fritz": 0, "devices": 0}


def probe_caps(al):
    """Quanto dire alla sonda: FRITZ!Box oltre al primo e dispositivi che può avere (pagina locale)."""
    return max(0, min(FRITZ_MAX, al["fritz"] - 1)), max(1, min(MAX_DEVICES, al["devices"]))


def limits_to_totals():
    """Una volta sola: i limiti scelti a mano prima che diventassero totali (FRITZ!Box aggiuntivi e
    dispositivi PER SONDA) diventano totali per l'account, moltiplicati per le sonde che ha, così
    chi li aveva non perde niente."""
    if auth.get_setting("limits_totals"):
        return
    with auth._conn() as c:
        rows = c.execute("SELECT id, max_fritz, max_devices FROM users "
                         "WHERE (max_fritz IS NOT NULL OR max_devices IS NOT NULL) "
                         "AND (plan IS NULL OR plan = 'personalizzato')").fetchall()
    for uid, mf, md in rows:
        n = max(1, len(registry.keys_of(uid)))
        with auth._conn() as c:
            c.execute("UPDATE users SET max_fritz = ?, max_devices = ? WHERE id = ?",
                      (None if mf is None else (1 + int(mf)) * n, None if md is None else int(md) * n, uid))
    auth.set_setting("limits_totals", "1")
    if rows:
        log.warning("Limiti di %d account convertiti in totali per account", len(rows))


def devices_left_out(key, cfg, in_pausa=None, lim=None):
    """Dispositivi della configurazione che la sonda NON deve controllare: quelli in pausa e quelli
    oltre il limite dell'account. Si conta nell'ordine della lista che l'utente vede (quello scelto
    con «Ordine», poi i nuovi in fondo), esclusi i fermi: restano fuori gli ultimi della lista.
    Restano salvati sul server: se il limite si alza o la pausa finisce, tornano da soli."""
    if in_pausa is None:
        in_pausa = registry.device_pauses(key)
    fuori = set(in_pausa or ())
    if lim is None:
        lim = allowance_of(key)["devices"]          # la parte del totale dell'account che spetta a questa sonda
    nomi = list(((cfg or {}).get("devices") or {}))
    if len(nomi) - len(fuori & set(nomi)) <= lim:
        return fuori
    scelto = [n for n in ((monitor.state.get(key) or {}).get("order") or []) if n in nomi]
    ordine = scelto + [n for n in nomi if n not in scelto]
    attivi = [n for n in ordine if n not in fuori]
    fuori.update(attivi[lim:])
    return fuori


def config_for_probe(key, cfg):
    """La configurazione da mandare alla sonda: senza i dispositivi in pausa.

    Il modo piu' diretto per non pingare un dispositivo e' non dirlo alla sonda. Cosi' non serve
    aggiornare le sonde per avere questa funzione, e il ping si ferma davvero invece di limitarsi
    a non avvisare. L'elenco salvato sul server resta completo: a sparire e' solo la copia che
    viaggia, e quando la pausa finisce il dispositivo torna da solo.
    """
    if not cfg:
        return cfg
    # Quante FRITZ!Box oltre al primo e quanti dispositivi può avere questa sonda: la sua parte dei
    # limiti dell'account (li decide l'amministratore), quindi si aggiunge qui al momento della
    # consegna e non sta mai nella configurazione salvata. La pagina locale non lascia andare oltre.
    al = allowance_of(key)
    fritz_max, devices_max = probe_caps(al)
    cfg = {**cfg, "fritz_max": fritz_max, "devices_max": devices_max}
    fuori = devices_left_out(key, cfg, lim=al["devices"])
    if not fuori:
        return cfg
    rimasti = {k: v for k, v in (cfg.get("devices") or {}).items() if k not in fuori}
    if not rimasti:
        return cfg              # l'ultimo non si toglie: una sonda senza dispositivi e' invalida
    return {**cfg, "devices": rimasti}


def add_event(title, body="", ok=True, probe=None):
    """Evento solo nel registro, senza notifiche (esiti delle operazioni di manutenzione)."""
    with db() as conn:
        conn.execute("INSERT INTO events (ts, title, body, critical, recovery, probe) VALUES (?,?,?,?,?,?)",
                     (time.time(), title, body, 0, 1 if ok else 0, probe))


def events_filter(user):
    """Condizione SQL sugli eventi visibili all'utente."""
    keys = registry.keys_of(user["id"])
    marks = ",".join("?" * len(keys)) or "NULL"
    return f"probe IN ({marks})", keys          # gli eventi della VM (probe NULL) sono solo per gli amministratori


EVENT_TAG_RE = re.compile(r"^[A-Z0-9_]{1,24}$")


def events_search(where, args, q="", tags=()):
    """Aggiunge alla condizione il filtro della pagina: testo libero (nel titolo, senza maiuscole)
    e tag tra parentesi quadre all'inizio del titolo, come [CRITICO] o [MANUTENZIONE] (uno qualsiasi
    di quelli scelti)."""
    q = (q or "").strip()
    if q:
        esc = q.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
        where += " AND title LIKE ? ESCAPE '\\'"
        args = [*args, f"%{esc}%"]
    tags = [t for t in dict.fromkeys(tags or ()) if EVENT_TAG_RE.match(t)]
    if tags:
        where += " AND (" + " OR ".join("title LIKE ? ESCAPE '\\'" for _ in tags) + ")"
        args = [*args, *("[" + t.replace("_", "\\_") + "]%" for t in tags)]
    return where, args


def split_tags(raw):
    return [t.strip().upper() for t in (raw or "").split(",") if t.strip()][:20]


def pending_command(p):
    """Comando da consegnare alla sonda, se ancora in attesa."""
    c = p.get("command")
    if c and c.get("state") == "pending":
        if c["cmd"] == "wifi":
            psk = _wifi_secrets.get(c["id"], "")
            if c.get("has_psk") and not psk:
                c.update(state="error", finished=time.time(), logged=True,
                         output="Richiesta scaduta (il server si è riavviato): ripetila.")
                return None
            return {"id": c["id"], "cmd": "wifi", "wifi": {"action": c.get("action"), "ssid": c.get("ssid"),
                                                           "hidden": bool(c.get("hidden")), "psk": psk}}
        return {"id": c["id"], "cmd": c["cmd"]}
    return None


def apply_command_status(probe, p, st):
    """Aggiorna lo stato del comando con l'esito inviato dalla sonda. Restituisce (ack, evento)."""
    c = p.get("command")
    if not c or not isinstance(st, dict) or st.get("id") != c.get("id"):
        return None, None
    state = st.get("state")
    if state not in ("running", "done", "error"):
        return None, None
    if (state == "error" and c.get("cmd") == "update"
            and "ha già la versione" in str(st.get("output") or "")):
        state = "done"                              # sonde di prima: «già aggiornata» non è un guasto
    c["state"] = state
    _wifi_secrets.pop(c["id"], None)               # presa in carico: la password non serve piu'
    c["output"] = str(st.get("output") or "")[:4000]
    c["finished"] = finite(st.get("finished"))      # solo un orario: finisce anche nel pannello /admin
    c["reboot_required"] = bool(st.get("reboot_required"))
    if state == "done" and not c.get("done_at"):
        c["done_at"] = time.time()                  # ora del server: da qui i minuti di tolleranza
    event = None
    if state in ("done", "error") and not c.get("logged"):
        c["logged"] = True
        name = COMMAND_NAMES.get(c["cmd"], c["cmd"])
        if c["cmd"] == "wifi":
            what = {"add": "aggiunta", "switch": "attivata", "remove": "tolta"}.get(c.get("action"), "")
            event = ((f"[OK] Rete Wi-Fi '{c.get('ssid')}' {what} sulla sonda '{label_of(probe, p)}'", True)
                     if state == "done" else
                     (f"[ALERT] Rete Wi-Fi '{c.get('ssid')}' sulla sonda '{label_of(probe, p)}': "
                      + (c["output"].split("\n")[0][:200] or "operazione non riuscita"), False))
        elif state == "done":
            event = (f"[OK] {name} della sonda '{label_of(probe, p)}' "
                     + ("avviato" if c["cmd"] == "reboot" else "completato")
                     + (f" (versione {str(st.get('version'))[:40]})"
                        if c["cmd"] == "update" and st.get("version") else ""), True)
        else:
            event = (f"[ALERT] {name} della sonda '{label_of(probe, p)}' non riuscito", False)
        # aggiornamento del sistema programmato: riavvio solo se serve (per esempio un nuovo kernel).
        # Il riavvio è un nuovo comando, consegnato con la stessa risposta che conferma l'esito.
        if state == "done" and c["cmd"] == "upgrade" and c.get("auto_reboot") and c["reboot_required"]:
            ack = c["id"]
            p["command"] = {"id": secrets.token_hex(8), "cmd": "reboot", "state": "pending",
                            "requested": time.time(), "by": "riavvio dopo l'aggiornamento programmato"}
            if event:
                event = (event[0] + " · riavvio automatico richiesto", event[1])
            return ack, event
    return (c["id"] if state in ("done", "error") else None), event


# ---- speedtest chiesto dalla pagina: la sonda lo esegue alla fine del ciclo dei ping
SPEEDTEST_TIMEOUT = 900       # secondi: oltre, la richiesta non consegnata scade
SPEEDTEST_GAP = 60            # secondi minimi tra la fine di uno speedtest e la richiesta del successivo


def pending_speedtest(p):
    st = p.get("speedtest") or {}
    if st.get("state") != "pending":
        return None
    if time.time() - (st.get("requested") or 0) > SPEEDTEST_TIMEOUT:
        st.update(state="error", finished=time.time(), error="la sonda non l'ha eseguito in tempo")
        return None
    return {"id": st["id"]}


def apply_speedtest(key, p, res):
    """Risultato inviato dalla sonda. Restituisce (id da confermare, evento)."""
    st = p.get("speedtest") or {}
    if not isinstance(res, dict) or not st.get("id") or res.get("id") != st["id"] or st.get("state") != "pending":
        return (res.get("id") if isinstance(res, dict) else None), None
    num = lambda k: finite(res.get(k))              # noqa: E731
    if res.get("ok") and num("down_mbps") is not None:
        st.update(state="done", finished=time.time(), down=num("down_mbps"), up=num("up_mbps"),
                  ping=num("ping_ms"), jitter=num("jitter_ms"), server=str(res.get("server") or "")[:60])
        f = lambda v: "—" if v is None else f"{v:.1f}".replace(".", ",")   # noqa: E731
        return st["id"], (f"[SPEEDTEST] {label_of(key, p)}: ↓ {f(st['down'])} Mbit/s · ↑ {f(st['up'])} Mbit/s"
                          f" · ping {f(st['ping'])} ms", True)
    st.update(state="error", finished=time.time(), error=str(res.get("error") or "non riuscito")[:200])
    return st["id"], (f"[SPEEDTEST] {label_of(key, p)}: non riuscito ({st['error']})", False)


def speedtest_public(p):
    pending_speedtest(p)                           # una richiesta scaduta diventa "non riuscito"
    st = p.get("speedtest")
    return {k: st.get(k) for k in ("state", "requested", "finished", "down", "up", "ping", "jitter", "server", "error")} if st else None


def speedtest_notify(key, p, event):
    """Esito dello speedtest al proprietario, sui canali scelti per il tipo «speedtest»."""
    send, to = recipients(key)
    if not send:
        log.info("Avviso «%s» non inviato: sonda senza proprietario o utente bloccato", event[0][:80])
        return
    if not notify_allowed(to["owner"], time.time())[0]:
        log.info("Avviso «%s» non inviato: troppi avvisi nell'ultima ora", event[0][:80])
        return
    st = p.get("speedtest") or {}
    body = event[0].split("] ", 1)[-1]
    if event[1]:
        body += (f"\nJitter {st.get('jitter')} ms" if st.get("jitter") is not None else "") \
                + (f"\nServer: {st['server']}" if st.get("server") else "")
    notify(event[0], body, False, event[1], label_of(key, p), to, "speedtest")


def store_speedtest(key, st, link=None):
    """Salva il risultato con il collegamento della sonda in quel momento (Wi-Fi o cavo): in Wi-Fi la
    velocità dipende anche dal Wi-Fi, e nello storico si deve vedere."""
    with db() as conn:
        conn.execute("INSERT INTO speedtests (ts, probe, down, up, ping, jitter, server, auto, link) VALUES (?,?,?,?,?,?,?,?,?)",
                     (st["finished"], key, st.get("down"), st.get("up"), st.get("ping"), st.get("jitter"),
                      st.get("server"), 1 if st.get("auto") else 0, link if link in ("wifi", "lan") else None))


# ---- speedtest periodici ------------------------------------------------------------------------
# L'utente sceglie per ogni sonda se e ogni quanto fare lo speedtest (Impostazioni → Controlli). Li
# programma il server: all'ora giusta chiede lo speedtest come il pulsante della pagina, quindi va
# bene per tutte le sonde che lo sanno fare, senza aggiornarle. Le scelte stanno in un file a parte
# (come i controlli di sicurezza): lo stato delle sonde si azzera alla fine di una pausa, queste no.
SPEED_FILE = DATA_DIR / "speedtests.json"
SPEED_FREQS = {"1h": 60, "3h": 180, "6h": 360, "12h": 720, "24h": 1440, "168h": 10080}   # minuti
SPEED_UNITS = {"m": 1, "h": 60, "d": 1440}
# Al massimo un test ogni quanti minuti, secondo il piano dell'account (nessun piano: ogni ora)
SPEED_PLAN_MIN = {"basso": 1440, "medio": 360, "alto": 60}
SPEED_MIN = 60
SPEED_OFFSETS = (0, 5, 15, 30, 60, 120)          # sfalsamento tra le sonde dell'account, in minuti
SPEED_WINDOW = 15 * 60          # una scadenza persa da più di 15 minuti (server spento) si salta
SPEED_LOW_RUN = 2               # avviso sulla velocità dopo 2 test bassi di fila
SPEED_ALERT_DEFAULTS = {"down_on": False, "down": 100, "up_on": False, "up": 20, "pct_on": False, "pct": 50}
_speed = {}                     # sonda -> {on, freq, n, unit, at, since, last_slot, low, alerted}


def speed_load():
    try:
        data = json.loads(SPEED_FILE.read_text())
        _speed.update(data if isinstance(data, dict) else {})
    except (OSError, ValueError):
        pass


speed_load()


def speed_save():
    tmp = SPEED_FILE.with_suffix(".tmp")
    tmp.write_text(json.dumps(_speed, separators=(",", ":")))
    tmp.replace(SPEED_FILE)


def speed_every(s):
    """Minuti tra due test della scelta (frequenza fissa o personalizzata)."""
    if s.get("freq") in SPEED_FREQS:
        return SPEED_FREQS[s["freq"]]
    return max(1, int(s.get("n") or 1)) * SPEED_UNITS.get(s.get("unit"), 60)


def speed_min_every(owner):
    return SPEED_PLAN_MIN.get(limits_of_user(owner)["plan"], SPEED_MIN)


def speed_prefs(owner):
    """Sfalsamento e avvisi dell'account, con i valori predefiniti."""
    raw = auth.get_st_prefs(owner) if owner else {}
    off = raw.get("offset") if raw.get("offset") in SPEED_OFFSETS else 30
    al = {**SPEED_ALERT_DEFAULTS, **{k: v for k, v in (raw.get("alerts") or {}).items() if k in SPEED_ALERT_DEFAULTS}}
    return {"offset": off, "alerts": al}


def _wall(t, tz):
    """Istante -> secondi «dell'orologio di casa» (ora locale letta come se fosse UTC)."""
    return t + datetime.fromtimestamp(t, tz).utcoffset().total_seconds()


def _unwall(w, tz):
    """Inverso di _wall. Nell'ora ripetuta (fine dell'ora legale) vale la prima delle due; un'ora
    che non esiste (inizio dell'ora legale) slitta di un'ora in avanti."""
    return datetime.fromtimestamp(w, timezone.utc).replace(tzinfo=tz).timestamp()


def speed_plan(owner, now=None):
    """Prossimo e ultimo turno di ogni sonda dell'account con i test periodici attivi: {sonda: (ultimo, prossimo)}.
    Ogni sonda parte dall'ora scelta, più lo sfalsamento per la sua posizione tra quelle attive
    (in ordine di creazione); il passo è la frequenza, mai più fitta di quella che il piano consente.
    Con passi di ore intere i turni seguono l'orologio di casa: il test delle 3:00 resta alle 3:00
    anche dopo il cambio dell'ora legale (contando in secondi passava alle 2:00, o alle 4:00)."""
    now = now or time.time()
    keys = [k for k in registry.keys_of(owner) if (_speed.get(k) or {}).get("on")] if owner else []
    if not keys:
        return {}
    off, step_min = speed_prefs(owner)["offset"], speed_min_every(owner)
    tz = user_tz(auth.get_user(owner))
    out = {}
    for idx, k in enumerate(keys):
        s = _speed[k]
        step = max(speed_every(s), step_min) * 60
        anchor = float(s.get("since") or now) + idx * off * 60
        if step % 3600:                            # ogni N minuti: in secondi, il cambio d'ora non conta
            n = math.floor((now - anchor) / step)
            last = anchor + n * step
            out[k] = (last, last + step)
            continue
        aw = _wall(anchor, tz)
        n = math.floor((_wall(now, tz) - aw) / step)
        out[k] = (_unwall(aw + n * step, tz), _unwall(aw + (n + 1) * step, tz))
    return out


def speed_since(at, tz):
    """Istante di partenza di una programmazione: oggi all'ora scelta, nel fuso dell'utente."""
    hh, mm = (int(x) for x in at.split(":"))
    day = datetime.now(tz)
    return day.replace(hour=hh, minute=mm, second=0, microsecond=0).timestamp()


def speed_request(key, p, auto, by=""):
    """Chiede lo speedtest alla sonda (stato pending): lo esegue alla fine del prossimo ciclo dei ping."""
    st = p.get("speedtest") or {}
    p["speedtest"] = {**{k: v for k, v in st.items() if k in ("down", "up", "ping", "jitter", "server", "finished")},
                      "last_state": st.get("state"), "id": secrets.token_hex(8), "state": "pending",
                      "requested": time.time(), "by": by, "auto": bool(auto)}


def speed_run():
    """Dal controllo periodico: chiede gli speedtest arrivati al loro turno. Una sonda spenta, in
    pausa o con uno speedtest già in corso salta quel turno (niente arretrati)."""
    now = time.time()
    owners = {registry.owner_of(k) for k, s in list(_speed.items()) if s.get("on")}
    da_fare, cambiato = [], False
    for owner in owners - {None}:
        for k, (last, _nxt) in speed_plan(owner, now).items():
            s = _speed[k]
            if last <= float(s.get("last_slot") or 0):
                continue
            s["last_slot"] = last
            cambiato = True
            if now - last <= SPEED_WINDOW:
                da_fare.append(k)
    if cambiato:
        speed_save()
    return da_fare


def speed_alert_check(key, p, st):
    """Dopo ogni speedtest riuscito: avviso se la velocità resta bassa per SPEED_LOW_RUN test di fila
    (sotto le soglie scelte, o sotto la percentuale scelta della media dei 7 giorni), e avviso di
    ripristino quando torna normale. Restituisce l'evento da registrare e notificare, o None."""
    owner = registry.owner_of(key)
    if not owner or st.get("down") is None:
        return None
    al = speed_prefs(owner)["alerts"]
    if not (al["down_on"] or al["up_on"] or al["pct_on"]):
        return None
    with db() as conn:
        avg = conn.execute("SELECT AVG(down), COUNT(*) FROM speedtests WHERE probe = ? AND ts >= ? AND ts < ?",
                           (key, st["finished"] - 7 * 86400, st["finished"] - 1)).fetchone()
    f = lambda v: f"{v:.1f}".replace(".", ",")      # noqa: E731
    motivi = []
    if al["down_on"] and st["down"] < al["down"]:
        motivi.append(f"download {f(st['down'])} Mbit/s, sotto {al['down']}")
    if al["up_on"] and st.get("up") is not None and st["up"] < al["up"]:
        motivi.append(f"upload {f(st['up'])} Mbit/s, sotto {al['up']}")
    if al["pct_on"] and avg[0] and avg[1] >= 3 and st["down"] < avg[0] * al["pct"] / 100:
        motivi.append(f"download al {round(st['down'] / avg[0] * 100)}% della media dei 7 giorni ({f(avg[0])} Mbit/s)")
    s = _speed.setdefault(key, {})
    nome = label_of(key, p)
    evento = None
    if motivi:
        s["low"] = int(s.get("low") or 0) + 1
        if s["low"] >= SPEED_LOW_RUN and not s.get("alerted"):
            s["alerted"] = True
            evento = (f"[SPEEDTEST] {nome}: velocità bassa",
                      f"Ultimi {SPEED_LOW_RUN} speedtest sotto la soglia. Ultimo: {' · '.join(motivi)}.", False)
    else:
        if s.get("alerted"):
            evento = (f"[SPEEDTEST] {nome}: velocità tornata normale",
                      f"↓ {f(st['down'])} Mbit/s · ↑ {f(st.get('up') or 0)} Mbit/s", True)
        s["low"], s["alerted"] = 0, False
    speed_save()
    return evento


def speed_alert_notify(key, p, evento):
    """Avviso sulla velocità al proprietario, sui canali scelti per il tipo «speedtest»."""
    send, to = recipients(key)
    if not send or not notify_allowed(to["owner"], time.time())[0]:
        log.info("Avviso «%s» non inviato (nessun destinatario o troppi avvisi)", evento[0][:80])
        return
    notify(evento[0], evento[1], not evento[2], evento[2], label_of(key, p), to, "speedtest")


def speed_forget(key):
    if _speed.pop(key, None) is not None:
        speed_save()


# ---- controllo di sicurezza dei dispositivi: porte aperte e servizi a rischio --------------------
# Lo esegue la sonda, un dispositivo alla volta, su richiesta dalla pagina o una volta al giorno per i
# dispositivi scelti. Qui restano richieste, ultimi risultati e scelte «ogni giorno», in un file a
# parte (scans.json): lo stato delle sonde si azzera alla fine di una pausa, queste scelte no.
SCAN_FILE = DATA_DIR / "scans.json"
SCAN_TIMEOUT = 1800           # secondi: oltre, la richiesta non eseguita scade
SCAN_GAP = 60                 # secondi minimi tra due controlli dello stesso dispositivo dalla pagina
SCAN_DAILY = 86400            # controllo automatico: una volta al giorno
SCAN_RISKS = ("alta", "media", "bassa", "info")
SCAN_MODES = ("veloce", "standard", "approfondito")
SCAN_QUEUE_MAX = 20           # controlli in coda per sonda, dopo quello in corso
PORTCHECK_PORTS = 5           # porte provate quando il ping fallisce (dall'ultimo controllo riuscito)
_scans = {}


def scans_load():
    try:
        data = json.loads(SCAN_FILE.read_text())
        _scans.update(data if isinstance(data, dict) else {})
    except (OSError, ValueError):
        pass


scans_load()


def scans_save():
    tmp = SCAN_FILE.with_suffix(".tmp")
    tmp.write_text(json.dumps(_scans, separators=(",", ":")))
    tmp.replace(SCAN_FILE)


def scan_entry(key):
    e = _scans.setdefault(key, {})
    e.setdefault("daily", [])
    e.setdefault("last", {})
    e.setdefault("req", None)
    e.setdefault("queue", [])
    e.setdefault("portcheck", [])
    return e


def port_check_for(key, p=None):
    """{dispositivo: porte} da provare quando il ping fallisce: solo i dispositivi scelti, con le porte
    trovate aperte dall'ultimo controllo di sicurezza riuscito (le prime PORTCHECK_PORTS)."""
    e = _scans.get(key) or {}
    p = p or monitor.state.get(key) or {}
    hosts = (p.get("config") or {}).get("devices") or {}
    out = {}
    for dev in e.get("portcheck") or []:
        last = (e.get("last") or {}).get(dev) or {}
        ports = [f["port"] for f in last.get("ports") or []] if last.get("ok") else []
        if dev in hosts and ports:
            out[dev] = ports[:PORTCHECK_PORTS]
    return out


def scan_next(key):
    """Finito (o scaduto) un controllo: parte il primo in coda, se il dispositivo c'è ancora."""
    e = _scans.get(key) or {}
    p = monitor.state.get(key) or {}
    hosts = (p.get("config") or {}).get("devices") or {}
    while e.get("queue") and not e.get("req"):
        q = e["queue"].pop(0)
        if q["device"] in hosts:
            scan_request(key, q["device"], str(hosts[q["device"]]), q["by"], q.get("mode"))
    scans_save()


def pending_scan(key):
    """Richiesta da consegnare alla sonda ({"id", "host"}), o None. Una scaduta diventa un errore."""
    e = _scans.get(key)
    req = (e or {}).get("req")
    if not req:
        return None
    if time.time() - req["requested"] > SCAN_TIMEOUT:
        e["last"][req["device"]] = {**e["last"].get(req["device"], {}), "finished": time.time(), "ok": False,
                                    "error": "la sonda non l'ha eseguito in tempo"}
        e["req"] = None
        scans_save()
        scan_next(key)
        return pending_scan(key)
    return {"id": req["id"], "host": req["host"], "mode": req.get("mode") or "standard"}


def scan_request(key, device, host, by, mode="standard"):
    e = scan_entry(key)
    e["req"] = {"id": secrets.token_hex(8), "device": device, "host": host, "requested": time.time(), "by": by,
                "mode": mode if mode in SCAN_MODES else "standard"}
    e["last"].setdefault(device, {})["tried"] = time.time()
    scans_save()


def scan_enqueue(key, device, by, mode):
    """Un altro controllo è in corso: questo aspetta il suo turno. Restituisce la posizione in coda."""
    e = scan_entry(key)
    if len(e["queue"]) >= SCAN_QUEUE_MAX:
        raise HTTPException(status_code=429, detail="Troppi controlli in coda: aspetta che finiscano.")
    e["queue"].append({"device": device, "by": by, "mode": mode, "queued": time.time()})
    scans_save()
    return len(e["queue"])


def _scan_ports(raw):
    out = []
    if not isinstance(raw, list):          # un dizionario o un numero qui era un errore 500
        return out
    for f in raw[:80]:
        if not isinstance(f, dict):
            continue
        try:
            port = int(f.get("port"))
        except (TypeError, ValueError):
            continue
        if not 0 < port < 65536:
            continue
        risk = f.get("risk") if f.get("risk") in SCAN_RISKS else "info"
        out.append({"port": port, "service": str(f.get("service") or "")[:30], "risk": risk,
                    "note": str(f.get("note") or "")[:160]})
    return sorted(out, key=lambda f: f["port"])


def apply_scan(key, p, res):
    """Risultato inviato dalla sonda. Restituisce (id da confermare, evento, testo dell'avviso o None)."""
    e = _scans.get(key) or {}
    req = e.get("req")
    rid = res.get("id") if isinstance(res, dict) else None
    if not req or rid != req["id"]:
        return rid, None, None
    dev, prev = req["device"], e["last"].get(req["device"]) or {}
    e["req"] = None
    who = f"{label_of(key, p)} › {dev}"
    # chiesto dall'utente con «Controlla adesso»: l'esito gli arriva sempre, anche senza rischi
    manual = req.get("by") != "ogni giorno"
    if not res.get("ok"):
        e["last"][dev] = {**prev, "finished": time.time(), "ok": False, "error": str(res.get("error") or "non riuscito")[:200],
                          "mode": req.get("mode") or "standard"}
        scan_next(key)
        text = (f"Il controllo di sicurezza di {dev} ({req['host']}) non è riuscito: {e['last'][dev]['error']}"
                if manual else None)
        return rid, (f"[SICUREZZA] {who}: controllo non riuscito ({e['last'][dev]['error']})", False), text
    ports = _scan_ports(res.get("ports"))
    e["last"][dev] = {"finished": time.time(), "ok": True, "host": req["host"], "ip": str(res.get("ip") or "")[:45],
                      "ports": ports, "complete": bool(res.get("complete", True)), "tried": prev.get("tried"),
                      "seconds": finite(res.get("seconds")), "mode": req.get("mode") or "standard"}
    scan_next(key)
    alte = [f for f in ports if f["risk"] == "alta"]
    medie = [f for f in ports if f["risk"] == "media"]
    parti = [f"{len(ports)} porte aperte" if len(ports) > 1 else "1 porta aperta" if ports else "nessuna porta aperta"]
    if alte:
        parti.append(f"{len(alte)} a rischio alto")
    if medie:
        parti.append(f"{len(medie)} a rischio medio")
    event = (f"[SICUREZZA] {who}: " + ", ".join(parti), not alte and not medie)
    # Avviso solo per i rischi nuovi (alti o medi) rispetto al controllo precedente: lo stesso
    # servizio già segnalato ieri non riparte ogni giorno.
    before = {(f["port"], f["risk"]) for f in prev.get("ports") or []} if prev.get("ok") else set()
    nuovi = [f for f in alte + medie if (f["port"], f["risk"]) not in before]
    text = None
    if nuovi or (manual and (alte or medie)):
        righe = [f"• {f['port']} {f['service']} (rischio {'alto' if f['risk'] == 'alta' else 'medio'}): {f['note']}" for f in (nuovi or alte + medie)]
        text = (f"Il controllo di sicurezza di {dev} ({req['host']}) ha trovato servizi a rischio:\n"
                + "\n".join(righe) + "\n\nDettagli e consigli nella pagina di stato (scudo accanto al dispositivo).")
    elif manual:
        text = (f"Il controllo di sicurezza di {dev} ({req['host']}) è terminato: nessun servizio a rischio.\n"
                + (parti[0] if ports else "Nessuna porta aperta tra quelle controllate."))
    return rid, event, text


def scan_notify(key, p, title, text, ok=False):
    send, to = recipients(key)
    if not send:
        log.info("Avviso «%s» non inviato: sonda senza proprietario o utente bloccato", title[:80])
        return
    if not notify_allowed(to["owner"], time.time())[0]:
        log.info("Avviso «%s» non inviato: troppi avvisi nell'ultima ora", title[:80])
        return
    notify(title, text, not ok, ok, label_of(key, p), to, "sicurezza")


def scans_public(key):
    e = _scans.get(key)
    if not e:
        return None
    pending_scan(key)
    last = {}
    for dev, r in (e.get("last") or {}).items():
        if not r.get("finished"):
            continue
        ports = r.get("ports") or []
        last[dev] = {k: r.get(k) for k in ("finished", "ok", "error", "host", "ip", "ports", "complete", "mode")}
        last[dev]["worst"] = next((k for k in SCAN_RISKS if any(f["risk"] == k for f in ports)), None)
    req = e.get("req") or {}
    return {"daily": e.get("daily") or [], "portcheck": e.get("portcheck") or [],
            "pending": req.get("device"), "pending_mode": req.get("mode"),
            "queue": [{"device": q["device"], "mode": q.get("mode")} for q in e.get("queue") or []], "last": last}


def scans_daily_due(now):
    """Un controllo giornaliero alla volta per sonda: il dispositivo scelto controllato da più tempo."""
    for key, e in _scans.items():
        p = monitor.state.get(key)
        if not e.get("daily") or e.get("req") or e.get("queue") or not p or not (p.get("system") or {}).get("scan"):
            continue
        if now - float(p.get("last_seen") or 0) > 600:         # sonda ferma: si riprova quando torna
            continue
        hosts = (p.get("config") or {}).get("devices") or {}
        due = [(float((e["last"].get(d) or {}).get("tried") or 0), d) for d in e["daily"] if d in hosts]
        due = [x for x in due if now - x[0] > SCAN_DAILY]
        if due:
            dev = min(due)[1]
            scan_request(key, dev, str(hosts[dev]), "ogni giorno")
            log.info("Controllo di sicurezza giornaliero di %s › %s", key, dev)


def scans_forget(key):
    if _scans.pop(key, None) is not None:
        scans_save()


def _pct(part, whole):
    part, whole = finite(part), finite(whole)
    if part is None or not whole or whole <= 0:
        return None
    return round(max(0.0, min(100.0, part / whole * 100)), 1)


def system_row(sysinfo):
    """(temperatura, carico, CPU %, memoria %, disco %) di un report: quello che manca resta None.
    CPU % = carico medio di un minuto diviso per i processori (oltre 100: processi in coda)."""
    temp, load = finite(sysinfo.get("temp_c")), finite(sysinfo.get("load1"))
    cpus = finite(sysinfo.get("cpus"))
    cpu = round(max(0.0, load / cpus * 100), 1) if load is not None and cpus and cpus > 0 else None
    mt, ma = finite(sysinfo.get("mem_total")), finite(sysinfo.get("mem_available"))
    mem = _pct(mt - ma, mt) if mt is not None and ma is not None else None
    disk = _pct(sysinfo.get("disk_used"), sysinfo.get("disk_total"))
    return (temp, load, cpu, mem, disk)


def clean_system(raw):
    """Stato della sonda: valori semplici (numeri finiti) ed elenchi brevi di testi."""
    out = {}
    for k, v in list(raw.items())[:60]:
        if len(k) > MAX_FIELD_NAME:
            continue
        if isinstance(v, list):
            out[k] = [str(x)[:60] for x in v[:10]]
        elif isinstance(v, (str, int, float, bool, type(None))) and (not isinstance(v, str) or len(v) <= 200):
            out[k] = scrub(v)
    return out


def guest_alerts(key, p, fritz, now):
    """Confronta gli ospiti attuali con quelli visti di recente e prepara le notifiche."""
    if "guests" not in fritz:
        return []
    settings = {**ALERT_DEFAULTS, **p.get("alerts", {})}
    seen = p.setdefault("guest_seen", {})           # MAC -> ultima volta visto
    grace = settings["guest_grace"] * 60
    alerts = []
    probe = label_of(key, p)
    for g in fritz["guests"]:
        mac = str(g["mac"]).upper()
        last = seen.get(mac)
        if settings["guest"] and (last is None or now - last > grace):
            name = g.get("name") or "Dispositivo senza nome"
            lines = [f"Dispositivo: '{name}'",
                     f"IP: {g.get('ip') or 'non ancora assegnato'}",
                     f"Collegato alle {local_time(now, '%H:%M del %d/%m/%Y')}"]
            if last is not None:
                lines.append(f"Non si vedeva da {fmt_duration(now - last)}")
            alerts.append(Alert(f"[OSPITE] {name} si è collegato alla rete ospiti ({probe})",
                                "\n".join(lines), subject=name, key=key, kind="ospiti"))
        seen[mac] = now
    # Dimentico i dispositivi non visti da 30 giorni
    for mac in [m for m, t in seen.items() if now - t > 30 * 86400]:
        del seen[mac]
    return alerts


MESH_GONE_READS = 2       # letture della mappa di fila senza il repeater prima dell'avviso (~10 minuti)
MESH_SLOW_READS = 3       # letture di fila con il collegamento lento (~15 minuti)
MESH_SLOW = 0.25          # lento: sotto un quarto della velocità massima del collegamento Wi-Fi
MESH_OK = 0.35            # tornato normale: sopra il 35%, per non avvisare a ogni oscillazione


def mesh_alerts(key, p, mesh, now):
    """Repeater usciti dalla mesh o con il collegamento Wi-Fi lento, confrontando le letture.
    Lo stato si aggiorna sempre, gli avvisi partono solo se l'utente li ha attivati."""
    on = {**ALERT_DEFAULTS, **p.get("alerts", {})}["mesh"]
    seen = p.setdefault("mesh_seen", {})              # nome repeater -> stato
    probe = label_of(key, p)
    alerts = []
    present = {n["name"]: n for n in mesh["nodes"] if not n.get("master")}
    for name, n in present.items():
        st = seen.setdefault(name, {"missing": 0, "slow": 0, "gone": False, "slow_alert": False})
        st["missing"], st["last"] = 0, now
        if st["gone"]:
            st["gone"] = False
            if on:
                alerts.append(Alert(f"[MESH] {name} è di nuovo nella rete mesh ({probe})",
                                    f"Il repeater '{name}' è tornato collegato alla rete mesh.",
                                    recovery=True, subject=name, key=key, kind="mesh"))
        up = n.get("up") or {}
        if up.get("type") != "cavo" and up.get("rate") and up.get("max"):
            ratio = up["rate"] / up["max"]
            st["slow"] = st["slow"] + 1 if ratio < MESH_SLOW else 0 if ratio >= MESH_OK else st["slow"]
            mbit = lambda v: f"{v / 1000:.0f} Mbit/s"
            if st["slow"] >= MESH_SLOW_READS and not st["slow_alert"]:
                st["slow_alert"] = True
                if on:
                    alerts.append(Alert(f"[MESH] Collegamento lento per {name} ({probe})",
                                        f"Il repeater '{name}' è collegato a {mbit(up['rate'])} su {mbit(up['max'])} "
                                        f"possibili ({ratio:.0%}) da circa {MESH_SLOW_READS * 5} minuti, via "
                                        f"{up.get('type') or 'Wi-Fi'}.\n\nDi solito è troppo lontano dal nodo a cui "
                                        "si collega, o c'è un ostacolo nuovo: prova ad avvicinarlo.",
                                        subject=name, key=key, kind="mesh"))
            elif st["slow_alert"] and ratio >= MESH_OK:
                st["slow_alert"], st["slow"] = False, 0
                if on:
                    alerts.append(Alert(f"[MESH] Collegamento di nuovo normale per {name} ({probe})",
                                        f"Il repeater '{name}' è collegato a {mbit(up['rate'])} su {mbit(up['max'])}.",
                                        recovery=True, subject=name, key=key, kind="mesh"))
    for name, st in list(seen.items()):
        if name in present:
            continue
        st["missing"] += 1
        if st["missing"] >= MESH_GONE_READS and not st["gone"]:
            st["gone"] = True
            if on:
                alerts.append(Alert(f"[MESH] {name} è uscito dalla rete mesh ({probe})",
                                    f"Il repeater '{name}' non compare più nella mappa mesh del FRITZ!Box da circa "
                                    f"{MESH_GONE_READS * 5} minuti: spento, staccato dalla corrente o fuori portata.",
                                    critical=True, subject=name, key=key, kind="mesh"))
        if now - float(st.get("last") or now) > 30 * 86400:     # tolto davvero: dimenticato
            del seen[name]
    return alerts


ORPHAN_DAYS = float(os.getenv("ORPHAN_DAYS", "30"))    # 0 = non eliminare mai le sonde senza account


def orphan_keys(now):
    """Sonde senza account ferme da più di ORPHAN_DAYS giorni: nessuno le vede né riceve avvisi.
    Succede quando una sonda si ripresenta con un'identità nuova (reinstallazione, chiave del
    server) o quando si elimina solo l'account: quella vecchia resterebbe per sempre."""
    if ORPHAN_DAYS <= 0:
        return []
    owned = registry.owned_keys()
    return [k for k, p in monitor.state.items()
            if k not in owned and now - float(p.get("last_seen") or 0) > ORPHAN_DAYS * 86400]


EVENTS_PER_PROBE = int(os.getenv("EVENTS_PER_PROBE", "5000"))   # eventi conservati per sonda
# Registro amministrativo (eventi senza sonda: VM, aggiornamenti, account): contiene anche le email
# degli utenti, quindi scade anche lui (GDPR, limitazione della conservazione). 0 = mai.
ADMIN_EVENTS_DAYS = float(os.getenv("ADMIN_EVENTS_DAYS", "365"))


PURGE_CHUNK = 20_000      # righe per transazione: il database resta libero per i report fra un pezzo e l'altro


def _keys_in_index(conn, table, cols):
    """Valori distinti delle prime colonne di un indice, letti saltando da uno al successivo.

    SELECT DISTINCT leggerebbe tutto l'indice (300 ms su un mese di misure); qui ogni passo e'
    una ricerca nell'indice, quindi il costo dipende da quante sonde e dispositivi ci sono e non
    da quanti dati. Due ricerche separate perche' SQLite, con un confronto su due colonne
    insieme, usa solo la prima per saltare e scorre il resto."""
    if len(cols) == 1:
        c0 = cols[0]
        r = conn.execute(f"SELECT {c0} FROM {table} WHERE {c0} IS NOT NULL ORDER BY {c0} LIMIT 1").fetchone()
        while r is not None:
            yield r
            r = conn.execute(f"SELECT {c0} FROM {table} WHERE {c0} > ? ORDER BY {c0} LIMIT 1", r).fetchone()
        return
    c0, c1 = cols
    r = conn.execute(f"SELECT {c0}, {c1} FROM {table} ORDER BY {c0}, {c1} LIMIT 1").fetchone()
    while r is not None:
        yield r
        r = (conn.execute(f"SELECT {c0}, {c1} FROM {table} WHERE {c0} = ? AND {c1} > ? "
                          f"ORDER BY {c1} LIMIT 1", r).fetchone()
             or conn.execute(f"SELECT {c0}, {c1} FROM {table} WHERE {c0} > ? "
                             f"ORDER BY {c0}, {c1} LIMIT 1", (r[0],)).fetchone())


def _delete_older(conn, table, cols, limit):
    """Cancella le righe con ts < limit usando l'indice (cols…, ts), a pezzi da PURGE_CHUNK.
    limit puo' essere una funzione della sonda (prima colonna): None = per lei niente da togliere.

    Un DELETE ... WHERE ts < ? su tutta la tabella non puo' usare l'indice (comincia dalla
    sonda, non dal tempo) e la scorrerebbe tutta tenendo bloccate le scritture: 25 volte piu'
    lento, e sempre di piu' man mano che lo storico cresce. Un indice sul solo tempo lo
    risolverebbe, ma costerebbe un quarto di spazio in piu' su disco."""
    cond = " AND ".join(f"{c} = ?" for c in cols)
    tolte = 0
    for chiave in list(_keys_in_index(conn, table, cols)):
        prima = limit(chiave[0]) if callable(limit) else limit
        if prima is None:
            continue
        while True:
            n = conn.execute(f"DELETE FROM {table} WHERE rowid IN (SELECT rowid FROM {table} "
                             f"WHERE {cond} AND ts < ? LIMIT {PURGE_CHUNK})", (*chiave, prima)).rowcount
            conn.commit()
            tolte += n
            if n < PURGE_CHUNK:
                break
    return tolte


def purge_samples(keys=None):
    """Toglie misure ed eventi piu' vecchi della conservazione scelta: quella di chi possiede la
    sonda, o quella del server. Con keys solo quelle sonde (e niente registro amministrativo).
    Restituisce quante righe."""
    now = time.time()
    owners = registry.owners()
    scelte = set(owners.values()) | {None}
    with_limit = any(user_retention_days(uid) for uid in scelte)

    def limit(probe):
        if keys is not None and probe not in keys:
            return None
        giorni = user_retention_days(owners.get(probe))
        return now - giorni * 86400 if giorni else None

    tolte = 0
    conn = db()
    try:
        if with_limit:
            tolte += _delete_older(conn, "samples", ("probe", "device"), limit)
            tolte += _delete_older(conn, "traffic", ("probe", "box"), limit)
            tolte += _delete_older(conn, "fritz_hist", ("probe", "box"), limit)
            tolte += _delete_older(conn, "speedtests", ("probe",), limit)
            tolte += _delete_older(conn, "system_samples", ("probe",), limit)
            # solo gli eventi delle sonde: il registro amministrativo ha la sua durata (sotto)
            tolte += _delete_older(conn, "events", ("probe",), limit)
            conn.commit()
        if keys is not None:
            return tolte
        if ADMIN_EVENTS_DAYS > 0:
            tolte += conn.execute("DELETE FROM events WHERE probe IS NULL AND ts < ?",
                                  (time.time() - ADMIN_EVENTS_DAYS * 86400,)).rowcount
            conn.commit()
        # Tetto agli eventi per sonda, anche con «conserva tutto»: senza, una sonda che ne genera
        # a raffica riempirebbe il disco.
        for (probe,) in conn.execute("SELECT probe FROM events WHERE probe IS NOT NULL GROUP BY probe "
                                     "HAVING COUNT(*) > ?", (EVENTS_PER_PROBE,)).fetchall():
            tolte += conn.execute("DELETE FROM events WHERE probe = ? AND rowid NOT IN "
                                  "(SELECT rowid FROM events WHERE probe = ? ORDER BY ts DESC LIMIT ?)",
                                  (probe, probe, EVENTS_PER_PROBE)).rowcount
            conn.commit()
    finally:
        conn.close()
    return tolte


# ------------------------------------------------------------------ limiti alle scritture delle sonde
# Database e disco sono di tutti gli utenti: una sonda (o chi ne ha il token) non deve poterli
# riempire né tenere occupato il server. Una sonda vera sta molto sotto questi limiti; se li
# supera riceve 429 e tiene le misure nel suo buffer, come quando il server non risponde.
class Bucket:
    """Secchiello di gettoni per chiave: `burst` gettoni subito, poi `rate` al secondo."""

    MAX_KEYS = 10_000

    def __init__(self, rate, burst):
        self.rate, self.burst = float(rate), float(burst)
        self._state = {}              # chiave -> (gettoni, istante)
        self._lock = threading.Lock()

    def take(self, key, n=1) -> bool:
        now = time.monotonic()
        with self._lock:
            if len(self._state) > self.MAX_KEYS:      # le chiavi ferme sono tornate piene: si dimenticano
                self._state = {k: v for k, v in self._state.items()
                               if v[0] + (now - v[1]) * self.rate < self.burst}
            tokens, at = self._state.get(key, (self.burst, now))
            tokens = min(self.burst, tokens + (now - at) * self.rate)
            if tokens < n:
                self._state[key] = (tokens, now)
                return False
            self._state[key] = (tokens - n, now)
            return True


# Report: l'intervallo minimo di una sonda è 10 secondi; qui al massimo uno ogni 5, con un margine
# per i report ravvicinati dopo un cambio di configurazione.
report_limit = Bucket(rate=1 / 5, burst=10)
# Buffer: una sonda che torna dopo un'interruzione invia fino a 5000 report a blocchi di 200.
backfill_limit = Bucket(rate=1 / 2, burst=40)
# Misure del buffer e campioni di traffico, per sonda: una riserva per svuotare un buffer pieno,
# poi il ritmo di una sonda con 200 dispositivi controllati ogni 10 secondi.
BULK_ROWS_BURST = int(os.getenv("BULK_ROWS_BURST", "1500000"))
bulk_rows_limit = Bucket(rate=20, burst=BULK_ROWS_BURST)
TOO_FAST = "Troppe richieste da questa sonda: riprova più tardi."

# Sotto questa soglia di spazio libero le misure non vengono più salvate (stato e avvisi sì):
# un disco pieno fermerebbe il server per tutti.
MIN_FREE_MB = int(os.getenv("MIN_FREE_MB", "300"))
_disk_check = [0.0, False]


def disk_low() -> bool:
    now = time.monotonic()
    if now - _disk_check[0] > 30 or not _disk_check[0]:
        try:
            low = shutil.disk_usage(DATA_DIR).free < MIN_FREE_MB * 1024 * 1024
        except OSError:
            low = False
        _disk_check[:] = [now, low]
    return _disk_check[1]


def disk_low_notice():
    admin_notice("[ALERT] Spazio su disco quasi esaurito: le misure non vengono salvate",
                 f"Sul disco della VM restano meno di {MIN_FREE_MB} MB liberi. Finché non si libera spazio "
                 "il server continua a controllare le sonde e a inviare gli avvisi, ma non salva lo "
                 "storico (ping, traffico, temperatura).\n\n"
                 "Controlla nella scheda Server la dimensione dei database: se è cresciuta di colpo, "
                 "una sonda sta inviando una quantità anomala di misure.",
                 ok=False, gap_key="disk_low", gap=6 * 3600)


def traffic_rows(probe, samples, now, box=""):
    """Campioni di traffico validi: [ts, up bit/s, down bit/s, durata s] (box: quale FRITZ!Box)."""
    oldest = oldest_accepted(now, probe)
    rows = []
    for smp in samples or []:
        if len(smp) < 3:
            continue
        ts, up, down = smp[0], smp[1], smp[2]
        dt = smp[3] if len(smp) > 3 else 10
        # 0 <= x < inf: scarta anche NaN e infinito (renderebbero illeggibile lo storico)
        if oldest <= ts <= now + 300 and 0 <= up < math.inf and 0 <= down < math.inf and 0 < dt <= 3600:
            rows.append((ts, probe, up, down, dt, box))
    return rows


def traffic_rows_all(probe, main, more, now):
    """Campioni del primo FRITZ!Box e degli altri principali."""
    rows = traffic_rows(probe, main, now) if main else []
    for box, samples in (more or {}).items():
        rows += traffic_rows(probe, samples, now, box)
    return rows


_fritz_last = {}                      # (probe, box) -> ultimo istante campionato
_rep_traffic_last = {}                # (probe, repeater) -> ultimo campione di traffico

def fritz_row(key, f, box=""):
    """Una riga di storico per un FRITZ!Box ([ts, probe, box, down, up, max_down, max_up,
    lan, wifi-json]), o None se non misurabile o già campionato da poco. wifi-json: i clienti
    di ciascuna rete Wi-Fi (chiave per SSID) più gli ospiti, sotto «guests»."""
    if not f.get("ok"):
        return None
    k = (key, box)
    if time.time() - _fritz_last.get(k, 0) < FRITZ_HIST_MIN:
        return None
    _fritz_last[k] = time.time()
    # stessa rete su più bande (2,4 e 5 GHz con lo stesso nome): i clienti si sommano
    wlans = {}
    for w in (f.get("wlans") or []):
        if not w.get("guest"):
            ssid = w.get("ssid") or "Wi-Fi"
            wlans[ssid] = wlans.get(ssid, 0) + int(w.get("clients") or 0)
    if isinstance(f.get("guests"), list):
        wlans["guests"] = len(f["guests"])
    # collegamento di ogni repeater verso la mesh, in kbit/s (chiave «mesh:nome»)
    for n in ((f.get("mesh") or {}).get("nodes") or []):
        up = n.get("up") or {}
        if not n.get("master") and up.get("rate") is not None:
            wlans["mesh:" + n["name"]] = up["rate"]
    # clean_fritz lascia passare anche testi brevi: qui contano solo i numeri finiti, altrimenti
    # float("abc") faceva fallire con un errore 500 l'intero report della sonda
    num = lambda k: None if finite(f.get(k)) is None else float(f[k])   # noqa: E731
    todo = (int(time.time()), key, box, num("rate_down"), num("rate_up"), num("max_down"), num("max_up"),
            num("lan_active"), json.dumps(wlans))
    return todo


def store_report(samples, system, traffic, fritz=None):
    """Misure di un report (ping, temperatura, traffico, metriche FRITZ!Box) in un'unica
    transazione."""
    with db() as conn:
        if samples:
            conn.executemany("INSERT OR IGNORE INTO samples VALUES (?,?,?,?,?)", samples)
        if system:
            conn.executemany("INSERT OR IGNORE INTO system_samples (ts, probe, temp, load1, cpu, mem, disk) "
                             "VALUES (?,?,?,?,?,?,?)", system)
        if traffic:
            conn.executemany("INSERT OR IGNORE INTO traffic (ts, probe, up, down, dt, box) VALUES (?,?,?,?,?,?)", traffic)
        if fritz:
            conn.executemany("INSERT OR IGNORE INTO fritz_hist "
                             "(ts, probe, box, down, up, max_down, max_up, lan, wifi) "
                             "VALUES (?,?,?,?,?,?,?,?,?)", fritz)


async def dispatch(alerts):
    if alerts:
        await asyncio.to_thread(_dispatch_sync, alerts)


async def watchdog():
    """Controlla periodicamente se qualche sonda è diventata silenziosa."""
    last_purge = last_expiry = last_auto = 0.0
    while True:
        await asyncio.sleep(CHECK_INTERVAL)
        try:
            if time.time() - last_expiry > 300:
                last_expiry = time.time()
                await asyncio.to_thread(expiry_run)
            # aggiornamenti automatici delle sonde rimaste indietro rispetto al server
            if time.time() - last_auto > 600:
                last_auto = time.time()
                keys = list(monitor.state)
                owners = await asyncio.to_thread(lambda: {k: registry.owner_of(k) for k in keys})
                off = await asyncio.to_thread(auth.probe_auto_off)
                pause = set((await asyncio.to_thread(registry.pauses_for, keys))[0])
                async with lock:
                    avviate = auto_update_run(owners, off, pause)
                    if avviate:
                        save_state()
                if avviate:
                    log.info("Aggiornamento automatico chiesto a %d sonde: %s", len(avviate), ", ".join(avviate))
            # speedtest periodici arrivati al loro turno
            turni = await asyncio.to_thread(speed_run)
            if turni:
                pause = set((await asyncio.to_thread(registry.pauses_for, turni))[0])
                async with lock:
                    for k in turni:
                        p = monitor.state.get(k)
                        if (p is None or k in pause or p.get("offline") or not (p.get("system") or {}).get("speedtest")
                                or pending_speedtest(p)):
                            log.info("Speedtest periodico di %s saltato (sonda spenta, in pausa o già occupata)", k)
                            continue
                        speed_request(k, p, True, "programmato")
                        log.info("Speedtest periodico chiesto alla sonda %s", k)
                    save_state()
            if time.time() - last_purge > 3600:
                last_purge = time.time()
                _user_retention.clear()           # account importati nel frattempo
                await asyncio.to_thread(purge_samples)
                await asyncio.to_thread(auth.purge_expired)
                await asyncio.to_thread(vmops.trim_self)    # memoria libera del server restituita al sistema
                orphans = await asyncio.to_thread(orphan_keys, time.time())
                if orphans:
                    async with lock:
                        names = [label_of(k, monitor.state[k]) for k in orphans if k in monitor.state]
                        for k in orphans:
                            monitor.state.pop(k, None)
                        save_state()
                    for k in orphans:
                        await asyncio.to_thread(wipe_probe, k)
                    log.warning("Eliminate %d sonde senza account ferme da più di %g giorni: %s",
                                len(orphans), ORPHAN_DAYS, ", ".join(names))
            # Pause scadute: la sonda torna a parlare da capo. Si azzera il suo stato, cosi' quello
            # che era gia' rotto prima della pausa viene segnalato di nuovo invece di restare zitto
            # perche' «lo stato non e' cambiato». La sonda ha il tempo di farsi viva prima di essere
            # dichiarata muta, perche' lo stato nuovo riparte da adesso.
            # Pause di singoli dispositivi scadute: basta rimandare la configurazione completa,
            # la sonda ricomincia a pingarli al controllo successivo.
            tornati = await asyncio.to_thread(registry.clear_expired_device_pauses, time.time())
            if tornati:
                async with lock:
                    for k in tornati:
                        if k in monitor.state:
                            bump_config_rev(monitor.state[k])
                    save_state()
                log.info("Pausa finita per i dispositivi di %d sonde: %s", len(tornati), ", ".join(tornati))
            scadute = await asyncio.to_thread(registry.clear_expired_pauses, time.time())
            if scadute:
                async with lock:
                    for k in scadute:
                        monitor.state.pop(k, None)
                    save_state()
                log.info("Pausa finita per %d sonde: %s", len(scadute), ", ".join(scadute))
            async with lock:
                alerts = monitor.check(time.time())
                if alerts:
                    save_state()
                await asyncio.to_thread(flush_state)
                scans_daily_due(time.time())
                if await asyncio.to_thread(inactive_wipe, None, time.time()):
                    save_state()
            await dispatch(alerts)
        except Exception as exc:  # noqa: BLE001
            log.exception("Errore nel watchdog")
            await asyncio.to_thread(admin_notice, "[ALERT] Errore interno del server", internal_error_text(exc),
                                    False, "watchdog", 6 * 3600)
        try:
            await run_schedules()
        except Exception as exc:  # noqa: BLE001
            log.exception("Errore negli aggiornamenti programmati")
            await asyncio.to_thread(admin_notice, "[ALERT] Errore negli aggiornamenti programmati",
                                    internal_error_text(exc), False, "sched", 6 * 3600)


def internal_error_text(exc):
    return (f"Il server ha incontrato un errore: {exc.__class__.__name__}: {str(exc)[:300]}\n\n"
            "Continua a funzionare, ma controlla il registro: sudo journalctl -u netmon-server -n 100\n"
            "(questo avviso non si ripete per 6 ore)")


def check_unclean_stop():
    """Il servizio segna "in funzione" all'avvio e "fermo" quando si ferma normalmente (anche per un
    aggiornamento o un riavvio della VM). Se all'avvio risulta ancora "in funzione", l'ultima volta si
    è interrotto di colpo: crash, memoria esaurita o VM spenta senza arresto regolare."""
    prev = auth.get_setting("server_running")
    auth.set_setting("server_running", json.dumps({"since": time.time(), "version": VERSION}))
    if prev and prev != "0":
        try:
            since = json.loads(prev).get("since")
        except (ValueError, AttributeError):
            since = None
        admin_notice("[ALERT] Il server netmon si è riavviato dopo un arresto imprevisto",
                     "Il servizio netmon-server si era fermato senza un arresto regolare"
                     + (f" (era in funzione dal {local_time(since, '%d/%m/%Y %H:%M')})" if since else "")
                     + ": crash del programma, memoria esaurita o VM spenta di colpo. Ora è di nuovo attivo.\n\n"
                     "Per capire la causa: sudo journalctl -u netmon-server -b -1 -n 100 (avvio precedente) "
                     "oppure sudo journalctl -u netmon-server -n 200.", False)
        log.warning("Riavvio dopo un arresto imprevisto del servizio")


@asynccontextmanager
async def lifespan(_app):
    await asyncio.to_thread(check_unclean_stop)
    for f in DATA_DIR.glob(".export-*.zip"):        # «Scarica i miei dati» interrotti: dati personali
        f.unlink(missing_ok=True)
    # Dopo un riavvio del server, concede alle sonde un intero timeout prima di allarmarsi
    now = time.time()
    for p in monitor.state.values():
        if not p["offline"]:
            p["last_seen"] = max(p["last_seen"], now - monitor.offline_after(p) / 2)
    task = asyncio.create_task(watchdog())
    yield
    task.cancel()
    flush_state()                         # nulla va perso quando il servizio si ferma
    auth.set_setting("server_running", "0")      # arresto regolare


# Niente documentazione automatica dell'API, nemmeno lo schema /openapi.json: elencherebbe a chiunque
# tutte le rotte, comprese quelle del pannello di amministrazione
app = FastAPI(title="netmon", lifespan=lifespan, docs_url=None, redoc_url=None, openapi_url=None)

# Intestazioni di sicurezza per tutte le risposte. Le pagine hanno script e stili nel file stesso
# (per questo 'unsafe-inline') e non caricano niente da altri siti, nemmeno i caratteri (vedi
# fonts.py); nessuna pagina può essere incorniciata da un altro sito (niente clickjacking).
CSP = ("default-src 'self'; script-src 'self' 'unsafe-inline'; "
       "style-src 'self' 'unsafe-inline'; font-src 'self'; "
       "img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'")
SECURITY_HEADERS = {"X-Content-Type-Options": "nosniff", "X-Frame-Options": "DENY",
                    "Referrer-Policy": "no-referrer"}


@app.exception_handler(RequestValidationError)
async def validation_error(_request: Request, exc: RequestValidationError):
    """Risposta 422 standard, ma senza NaN/infinito: l'errore riporta il valore ricevuto, e un
    numero non finito farebbe fallire la risposta stessa (500 al posto di 422)."""
    return JSONResponse({"detail": scrub(jsonable_encoder(exc.errors()))}, status_code=422)


# Tentativi di accesso in corso nella richiesta attuale: (limitatore, chiavi) riservati da
# too_many/admin_too_many e liberati dal middleware quando la richiesta finisce, comunque finisca.
_attempts = contextvars.ContextVar("netmon_attempts", default=None)


def reserve_attempt(limiter, keys):
    held = _attempts.get()
    if held is None:
        return
    limiter.reserve(*keys)
    held.append((limiter, keys))


# Dominio cambiato: i vecchi nomi di questa macchina (OLD_HOSTS nel .env, li scrive installa-server.sh)
# restano serviti da Caddy e rimandano tutti a PUBLIC_URL. Le sonde ricevono il nuovo indirizzo con la
# risposta 410 con «moved» e lo scrivono da sole nella configurazione.
OLD_HOSTS = {h.strip().lower() for h in os.getenv("OLD_HOSTS", "").split(",") if h.strip()}
PROBE_PATHS = ("/api/report", "/api/backfill", "/api/probe-config", "/api/probe-update", "/api/probe-package")


def old_host_reply(request: Request):
    """Risposta a una richiesta arrivata a un vecchio nome di questa macchina, altrimenti None."""
    if not OLD_HOSTS:
        return None
    host = request.headers.get("host", "").lower().split(":", 1)[0]
    if host not in OLD_HOSTS:
        return None
    base = os.getenv("PUBLIC_URL", "").strip().rstrip("/")
    parts = urlsplit(base)
    if parts.scheme != "https" or not parts.hostname or parts.hostname in OLD_HOSTS:
        return None
    path = request.url.path
    if path.startswith(PROBE_PATHS) and request.headers.get("authorization", "").startswith("Bearer "):
        url = base + "/api/report"
        return JSONResponse({"detail": f"Sonda spostata: ora scrive a {url}.", "moved": url},
                            status_code=410, headers=SECURITY_HEADERS)
    if request.method in ("GET", "HEAD"):
        target = base + path + (("?" + request.url.query) if request.url.query else "")
        return RedirectResponse(target, status_code=301, headers=SECURITY_HEADERS)
    return JSONResponse({"detail": f"Indirizzo cambiato: usa {base}."}, status_code=421, headers=SECURITY_HEADERS)


@app.middleware("http")
async def security_middleware(request: Request, call_next):
    # Corpo della richiesta troppo grande: rifiutato prima di leggerlo (anche Caddy ha un limite)
    try:
        length = int(request.headers.get("content-length") or 0)
    except ValueError:
        length = 0
    path = request.url.path
    # Il JSON si legge tutto prima di ogni controllo: corpi grandi solo dove servono, e per le sonde
    # solo con un token valido (altrimenti chiunque potrebbe far esaurire la memoria del servizio).
    limit = MAX_BODY_BYTES if path in BIG_BODY_PATHS else SMALL_BODY_BYTES
    if length > limit:
        return JSONResponse({"detail": "Richiesta troppo grande."}, status_code=413, headers=SECURITY_HEADERS)
    if length > SMALL_BODY_BYTES and path in PROBE_BODY_PATHS:
        tok = request.headers.get("authorization", "").removeprefix("Bearer ").strip()
        if not tok or not await asyncio.to_thread(registry.by_token, tok):
            return JSONResponse({"detail": "token non valido"}, status_code=401, headers=SECURITY_HEADERS)
    moved = old_host_reply(request)                                        # dominio cambiato
    if moved is not None:
        return moved
    held = []
    _attempts.set(held)
    try:
        response = await call_next(request)
    finally:
        for limiter, keys in held:
            limiter.release(*keys)
    for k, v in SECURITY_HEADERS.items():
        response.headers.setdefault(k, v)
    if response.headers.get("content-type", "").startswith("text/html"):
        response.headers.setdefault("Content-Security-Policy", CSP)
    # I dati (stato, sonde, account) viaggiano su /api e su /admin/api: non devono finire in nessuna
    # cache, ne' del browser ne' di un intermediario, cosi' un logout lascia davvero nulla dietro.
    # Le pagine /, /dashboard e /admin restano con ETag: sono solo gusci HTML senza dati.
    if request.url.path.startswith(("/api/", "/admin/api")):
        response.headers.setdefault("Cache-Control", "no-store")
    return response


# ------------------------------------------------------------------ account della pagina di stato
auth = AuthDB(DATA_DIR / "auth.db")
registry = ProbeRegistry(auth)
throttle = Throttle(max_fails=5, window=15 * 60)
COOKIE = "netmon_session"


def migrate_env_channels():
    """Versioni precedenti: chat ID Telegram e topic ntfy dell'utente principale stavano nel file
    .env. Una sola volta vengono copiati nel suo account (se non ne ha già di suoi); da lì in poi
    ogni utente gestisce i propri in Impostazioni → Notifiche e le righe del .env sono ignorate."""
    if auth.get_setting("env_channels_moved") == "1":
        return
    uid = auth.admin_id()
    if uid is None:
        return                                    # nessun account ancora: niente da spostare
    u = auth.get_user(uid)
    chat = u["telegram_chat"] or os.getenv("TELEGRAM_CHAT_ID", "").strip()
    ntfy = u["ntfy_url"] or os.getenv("NTFY_URL", "").strip()
    if (chat, ntfy) != (u["telegram_chat"], u["ntfy_url"]):
        auth.set_notify(uid, chat, ntfy, u["notify_email"])
        log.info("Canali Telegram/ntfy del file .env spostati nell'account %s", u["email"])
    auth.set_setting("env_channels_moved", "1")


migrate_env_channels()


# Il traffico pubblico arriva da Caddy, sulla stessa macchina (127.0.0.1). Con un altro proxy davanti
# (per esempio un bilanciatore) TRUSTED_PROXIES nel .env elenca gli indirizzi a cui credere per X-Forwarded-For.
TRUSTED_PROXIES = {"127.0.0.1", "::1"} | {a.strip() for a in os.getenv("TRUSTED_PROXIES", "").split(",") if a.strip()}


def client_ip(request: Request) -> str:
    """IP del browser. Dietro Caddy la connessione arriva da 127.0.0.1: l'IP vero è nell'ultima
    voce di X-Forwarded-For, aggiunta da Caddy (considerata solo se la richiesta arriva da un
    proxy fidato: in locale o da TRUSTED_PROXIES)."""
    peer = request.client.host if request.client else "?"
    if peer in TRUSTED_PROXIES:
        fwd = request.headers.get("x-forwarded-for", "")
        if fwd:
            return fwd.split(",")[-1].strip()[:64] or peer
    return peer


# Cookie solo su HTTPS. Il server è sempre dietro Caddy con HTTPS: il valore non dipende più da
# come uvicorn interpreta le intestazioni del proxy. COOKIE_SECURE=0 solo per prove in locale su http.
COOKIE_SECURE = os.getenv("COOKIE_SECURE", "1").strip() != "0"


def set_session_cookie(response, request: Request, raw: str, remember: bool):
    response.set_cookie(COOKIE, raw, max_age=SESSION_DAYS_REMEMBER * 86400 if remember else None,
                        httponly=True, secure=COOKIE_SECURE, samesite="strict", path="/")


def probe_identity(name: str, authorization: str):
    """Chiave interna della sonda che sta scrivendo. Il secondo valore resta per compatibilita'
    con chi lo chiama, ed e' sempre None: il server non emette piu' token da solo.

    Una sonda si identifica SOLO con il suo token personale, quello generato nella pagina
    (Impostazioni → Sonde). La chiave del server non vale piu' per le sonde: e' un segreto
    condiviso da chiunque l'abbia usata per un'installazione, e con quella si potevano creare
    sonde o, in certe finestre, agganciarsi a quelle degli altri. Il token invece vale per una
    sonda sola, e chi lo perde ne genera uno nuovo senza toccare le altre."""
    tok = authorization.removeprefix("Bearer ").strip()
    found = registry.by_token(tok)
    if found:
        return found[0], None
    if tok and hmac.compare_digest(tok, API_TOKEN):
        server_key_refused(name)
    raise HTTPException(status_code=401, detail="token non valido")


INST_RE = re.compile(r"^[0-9a-f]{32}$")


def dup_text(key, found):
    """Avviso «stesso token su due dispositivi»: (titolo, testo) per le notifiche."""
    nome = registry.name_of(key) or key
    a, b = found["inst"], found["dup"]
    chi = lambda d: (d.get("host") or "dispositivo senza nome") + (f" ({d['ip']})" if d.get("ip") else "")
    title = f"[ALERT] Due dispositivi usano il token della sonda «{nome}»"
    primo, secondo = a.get("host") or "il primo dispositivo", b.get("host") or "il secondo"
    since, first = (local_time(x or time.time(), "%d/%m/%Y %H:%M") for x in (a.get("since"), b.get("first")))
    righe = [f"Il server ha ricevuto dati per la sonda «{nome}» da due dispositivi diversi con lo stesso token.",
             "",
             f"• {chi(a)}: collegato dal {since}. I suoi dati vengono tenuti.",
             f"• {chi(b)}: si è presentato il {first}. I suoi dati vengono scartati: non entrano nello storico "
             "e non fanno partire avvisi.",
             "",
             "Ogni sonda deve avere il suo token. Per usare anche il secondo dispositivo: pagina di stato → "
             "Impostazioni → Sonde → «Aggiungi una sonda», e scrivi il nuovo token nella pagina locale del "
             "secondo dispositivo, sezione Server.",
             "",
             f"Se invece hai sostituito {primo} con {secondo}, nella pagina di stato (Dashboard o Stato rete) "
             "premi «Usa il nuovo dispositivo»."]
    body = "\n".join(righe)
    return title, body


def dup_public(info):
    """Secondo dispositivo con lo stesso token, per la pagina (niente identificativi interni)."""
    if not info:
        return None
    a, b = info["inst"], info["dup"]
    return {"old_host": a.get("host") or "", "old_ip": a.get("ip") or "", "new_host": b.get("host") or "",
            "new_ip": b.get("ip") or "", "last": b.get("last")}


def probe_instance_check(key, inst, host, ip=None):
    """Un token, un dispositivo: il primo che lo usa ne è il titolare. Un altro dispositivo con lo
    stesso token riceve 409 (i suoi dati non entrano) e l'utente un avviso, al massimo ogni 12 ore.
    Le sonde di prima, che non mandano la loro identità, non vengono controllate."""
    inst = (inst or "").strip().lower()
    if not INST_RE.match(inst):
        return
    host = re.sub(r"[^A-Za-z0-9._-]", "", host or "")[:60]
    ip = ip if isinstance(ip, str) and len(ip) <= 45 and re.fullmatch(r"[0-9a-fA-F:.]+", ip) else None
    found = registry.instance_seen(key, inst, host, ip)
    if found is None:
        return
    if found["notify"]:
        title, body = dup_text(key, found)
        log.warning("Sonda %s: token usato anche da %s (%s), dati rifiutati", key, found["dup"].get("host"),
                    found["dup"].get("ip"))
        _dispatch_sync([Alert(title, body, critical=True, subject=registry.name_of(key) or key, key=key, kind="sonde")])
    nome, chi = registry.name_of(key) or key, found["inst"].get("host") or "un altro dispositivo"
    raise HTTPException(status_code=409, detail=(
        f"Token già in uso da un'altra sonda («{nome}», dispositivo {chi}). Ogni sonda deve avere il suo token: "
        "nella pagina di stato, Impostazioni → Sonde → «Aggiungi una sonda», poi scrivi qui il nuovo token. "
        "Se questo dispositivo sostituisce l'altro, nella pagina di stato premi «Usa il nuovo dispositivo»."))


def server_key_refused(name):
    """Una sonda si e' presentata con la chiave del server, che non vale piu' per le sonde.

    Senza un avviso sarebbe solo una sonda che smette di comunicare, e non si capirebbe perche'.
    Va all'amministrazione al massimo ogni 6 ore: il nome lo sceglie chi chiama, quindi non puo'
    essere lui a decidere quante email partono."""
    nome = re.sub(r"[^A-Za-z0-9 _.\-]", "", str(name or ""))[:40] or "senza nome"
    log.warning("Sonda '%s' rifiutata: si presenta con la chiave del server invece del suo token", nome)
    admin_notice("[ALERT] Una sonda usa ancora la chiave del server",
                 f"La sonda '{nome}' ha provato a collegarsi con la chiave del server, che per le sonde "
                 "non vale piu'. Finche' non riceve il suo token personale non invia dati.\n\n"
                 "Il proprietario apre la pagina di stato → Impostazioni → Sonde, genera un token "
                 "(«Aggiungi una sonda», oppure «Nuovo token» se la sonda e' gia' in elenco) e lo inserisce "
                 "nella pagina locale della sonda, sezione Server → Token.",
                 ok=False, gap_key="chiave_sonde", gap=6 * 3600)
    raise HTTPException(status_code=401, detail="La chiave del server non vale piu' per le sonde: "
                                                "usa il token personale della sonda (Impostazioni → Sonde).")


def owns(user, key):
    """Errore 404 se la sonda non appartiene all'utente (non rivela se esiste)."""
    if registry.owner_of(key) != user["id"] or key not in monitor.state:
        raise HTTPException(status_code=404, detail="sonda non trovata")


async def ui_user(request: Request):
    """Accesso alle API della pagina: solo con la sessione del browser (email e password).
    La chiave del server NON dà accesso a queste API: vale solo per creare il primo account."""
    user = await asyncio.to_thread(auth.session_user, request.cookies.get(COOKIE))
    if user is None:
        raise HTTPException(status_code=401, detail="accesso richiesto")
    if user.get("must_change"):
        raise HTTPException(status_code=403, detail="Prima di continuare cambia la password provvisoria.")
    VIEW_TZ.set(tz_named(user.get("tz")))
    return user


def ordered_names(p):
    """Ordine scelto dall'utente; i dispositivi nuovi vanno in fondo, nell'ordine della sonda."""
    order = p.get("order", [])
    pos = {n: i for i, n in enumerate(order)}
    names = list(p["devices"])
    return sorted(names, key=lambda n: (pos.get(n, len(order)), names.index(n)))


@app.post("/api/report")
async def report(r: Report, authorization: str = Header(default=""), x_netmon_instance: str = Header(default=""),
                 x_netmon_host: str = Header(default="")):
    key, _ = await asyncio.to_thread(probe_identity, r.probe, authorization)
    await asyncio.to_thread(probe_instance_check, key, x_netmon_instance, x_netmon_host, (r.system or {}).get("ip"))
    if not report_limit.take(key):
        raise HTTPException(status_code=429, detail=TOO_FAST)
    # Un dispositivo appena messo in pausa puo' arrivare ancora in un report: la sonda riceve
    # l'elenco nuovo solo al giro dopo. Si scarta qui, cosi' non genera stato, avvisi ne' misure
    # nemmeno in quel giro di mezzo.
    in_pausa = await asyncio.to_thread(registry.device_pauses, key)
    # Oltre ai fermi, quelli oltre il limite di dispositivi dell'account (vedi devices_left_out):
    # una sonda vecchia, o una configurazione appena cambiata, può ancora mandarli
    cfg_ora = (monitor.state.get(key) or {}).get("config")
    if r.config is not None and r.config_rev >= int((monitor.state.get(key) or {}).get("config_rev") or 0):
        cfg_ora = r.config.model_dump()
    al = await asyncio.to_thread(allowance_of, key)
    fuori = await asyncio.to_thread(devices_left_out, key, cfg_ora, in_pausa, al["devices"])
    misure = {n: v for n, v in r.devices.items() if n not in fuori}
    # FRITZ!Box oltre la parte dell'account che spetta a questa sonda: il server non li tiene, anche
    # se la sonda li manda (una sonda vecchia, o un limite appena abbassato)
    if r.fritz is not None and al["fritz"] < 1:
        r.fritz, r.traffic = None, None
    extra = max(0, al["fritz"] - (1 if r.fritz is not None else 0))
    if r.fritz_boxes and len(r.fritz_boxes) > extra:
        r.fritz_boxes = r.fritz_boxes[:extra]
        tenuti = {str(b.get("id") or "") for b in r.fritz_boxes}
        if r.traffic_more:
            r.traffic_more = {k: v for k, v in r.traffic_more.items() if k in tenuti}
    # ping fallito ma una porta già vista aperta risponde: il dispositivo è acceso, niente avviso
    porte = port_check_for(key)
    porta_ok = {n: v.port for n, v in misure.items()
                if not isinstance(v, bool) and not v.ok and v.port in porte.get(n, ())}
    status = {n: (v if isinstance(v, bool) else v.ok or n in porta_ok) for n, v in misure.items()}
    async with lock:
        alerts = monitor.process_report(key, status, time.time(), r.interval,
                                        r.thresholds.model_dump() if r.thresholds else None)
        devices = monitor.state[key]["devices"]
        for name, v in misure.items():
            if not isinstance(v, bool) and name in devices:
                devices[name]["host"] = v.host
                devices[name]["rtt"] = v.rtt if v.ok else None
                devices[name]["port_ok"] = porta_ok.get(name)
        # Scambio della configurazione: vince la revisione più alta
        p = monitor.state[key]
        if not p.get("name"):
            p["name"] = registry.name_of(key) or r.probe   # nome mostrato; si cambia con "Rinomina"
        server_rev = int(p.get("config_rev") or 0)
        if r.config is not None and r.config_rev >= server_rev:
            nuova = r.config.model_dump()
            # Alla sonda i dispositivi in pausa non erano stati mandati: quando rimanda indietro la
            # sua configurazione non devono sparire da quella del server, o la pausa diventerebbe
            # una cancellazione.
            vecchi = (p.get("config") or {}).get("devices") or {}
            for nome in fuori:
                if nome in vecchi:
                    nuova.setdefault("devices", {}).setdefault(nome, vecchi[nome])
            p["config"] = nuova
            p["config_rev"] = server_rev = r.config_rev
            if p["config"].get("probe_name"):
                p["name"] = p["config"]["probe_name"]
        p["applied_rev"] = r.config_rev
        if r.fritz is not None:
            fresca = isinstance(r.fritz.get("mesh"), dict)
            nuovo = clean_fritz(r.fritz)
            if "netdev" in nuovo:
                netdev_seen(p, nuovo["netdev"], time.time())
            p["fritz"] = carry_mesh(p.get("fritz"), nuovo, time.time())
            p["fritz"]["ts"] = time.time()
            if p["fritz"].get("ok"):
                with viewer_tz(owner_tz(key)):          # «Collegato alle …» nel fuso del proprietario
                    alerts += guest_alerts(key, p, p["fritz"], time.time())
                if fresca and p["fritz"].get("mesh"):
                    alerts += mesh_alerts(key, p, p["fritz"]["mesh"], time.time())
        else:
            p.pop("fritz", None)
        if r.fritz_boxes:
            p["fritz_boxes"] = [repeater_from_mesh(b, (p.get("fritz") or {}).get("mesh")) if b.get("role") == "wifi" else b
                                for b in clean_fritz_boxes(r.fritz_boxes, p.get("fritz_boxes"))]
        else:
            p.pop("fritz_boxes", None)
        if r.system is not None:
            p["system"] = clean_system(r.system)
            p["system"]["ts"] = time.time()
            # programma della sonda appena ripartito (aggiornato a mano, riavviato, corrente tornata):
            # i primi cicli sono lenti, si concedono alcuni minuti prima di dirla in ritardo
            pu = finite(p["system"].get("probe_uptime"))
            if pu is not None and 0 <= pu < RESTART_GRACE:
                p["restart_at"] = time.time() - pu
        # La parte dei limiti dell'account che spetta a questa sonda cambia anche quando cambiano le
        # altre sonde: se è diversa da quella mandata l'ultima volta, la configurazione riparte.
        firma = [*probe_caps(al), sorted(fuori - set(in_pausa or ()))]
        if p.get("config") and p.get("sent_caps") != firma:
            p["sent_caps"] = firma
            bump_config_rev(p)
            server_rev = int(p["config_rev"])
        save_state()

    frows = []
    if p.get("fritz"):
        s = fritz_row(key, p["fritz"])
        if s: frows.append(s)
    for fb in (p.get("fritz_boxes") or []):
        s = fritz_row(key, fb, fb.get("id", ""))
        if s: frows.append(s)

    now = time.time()
    rows = [(now, key, n, 1 if (v if isinstance(v, bool) else v.ok) else 0,
             None if isinstance(v, bool) else (v.rtt if v.ok else None))
            for n, v in misure.items()]
    sys_rows = []
    if r.system:
        sysrow = system_row(r.system)
        if any(v is not None for v in sysrow):
            sys_rows = [(now, key, *sysrow)]
    trows = traffic_rows_all(key, r.traffic, r.traffic_more, now) if (r.traffic or r.traffic_more) else None
    # repeater collegati alla mesh via cavo: un campione di traffico per report, nello stesso storico
    # dei FRITZ!Box principali (grafico «Traffico»), con la media dall'ultimo riepilogo della sonda
    for fb in (p.get("fritz_boxes") or []):
        if fb.get("role") == "wifi" and fb.get("rate_down") is not None and fb.get("rate_up") is not None:
            last = _rep_traffic_last.get((key, fb["id"]))
            dt = fb.get("rate_dt") or (min(3600.0, now - last) if last else None)
            _rep_traffic_last[(key, fb["id"])] = now
            if dt and 0 < dt <= 3600:
                trows = (trows or []) + [(now, key, float(fb["rate_up"]), float(fb["rate_down"]), float(dt), fb["id"])]
    extra = (trows or []) + frows
    if extra and not bulk_rows_limit.take(key, len(extra)):
        log.warning("Sonda %s: troppi campioni di traffico, scartati %d", key, len(extra))
        trows, frows = None, []
    if await asyncio.to_thread(disk_low):
        await asyncio.to_thread(disk_low_notice)      # stato e avvisi proseguono, lo storico no
    else:
        await asyncio.to_thread(store_report, rows, sys_rows, trows, frows or None)

    speed_ack = None
    if r.speedtest is not None:
        async with lock:
            speed_ack, speed_event = apply_speedtest(key, p, r.speedtest)
            save_state()
        if speed_event:
            st_now = p["speedtest"]
            await asyncio.to_thread(store_speedtest, key, st_now, (p.get("system") or {}).get("link"))
            # i test periodici non scrivono un evento ogni volta e non mandano notifiche: notifiche
            # solo per gli speedtest avviati a mano
            if not st_now.get("auto"):
                await asyncio.to_thread(add_event, speed_event[0], "", speed_event[1], key)
                await asyncio.to_thread(speedtest_notify, key, p, speed_event)
            if st_now.get("state") == "done":
                lento = await asyncio.to_thread(speed_alert_check, key, p, st_now)
                if lento:
                    await asyncio.to_thread(add_event, lento[0], lento[1], lento[2], key)
                    if not st_now.get("auto"):
                        await asyncio.to_thread(speed_alert_notify, key, p, lento)

    scan_ack = None
    if r.scan is not None:
        async with lock:
            scan_ack, scan_event, scan_text = apply_scan(key, p, r.scan)
        if scan_event:
            await asyncio.to_thread(add_event, scan_event[0], "", scan_event[1], key)
        if scan_text:
            await asyncio.to_thread(scan_notify, key, p, scan_event[0], scan_text, scan_event[1])

    ack, event = None, None
    if r.command_status is not None:
        async with lock:
            ack, event = apply_command_status(key, p, r.command_status)
            save_state()
    if event:
        await asyncio.to_thread(add_event, event[0], "", event[1], key)
        sid = (p.get("command") or {}).get("schedule")
        if not event[1] and sid is not None:                                        # programmato in /admin
            sch = await asyncio.to_thread(auth.get_schedule, sid)
            if not (sch or {}).get("batch"):        # in una campagna: nel riepilogo finale, non una mail a sonda
                await asyncio.to_thread(admin_notice, event[0], "Aggiornamento programmato non riuscito su una sonda.\n\n"
                                        "Il registro dell'operazione è nella scheda Sonde del pannello.", False)

    await dispatch(alerts)
    reply = {"ok": True, "alerts": len(alerts), "config_rev": server_rev,
             "has_config": p.get("config") is not None}
    if server_rev > r.config_rev and p.get("config"):
        reply["config"] = await asyncio.to_thread(config_for_probe, key, p["config"])
    if ack:
        reply["command_ack"] = ack
    cmd = pending_command(p)
    if cmd:
        reply["command"] = cmd
    if speed_ack:
        reply["speedtest_ack"] = speed_ack
    if speedtest := pending_speedtest(p):
        reply["speedtest"] = speedtest
    if scan_ack:
        reply["scan_ack"] = scan_ack
    if scan := pending_scan(key):
        reply["scan"] = scan
    if porte:
        reply["port_check"] = porte
    return reply


@app.post("/api/backfill")
async def backfill(b: Backfill, authorization: str = Header(default=""), x_netmon_instance: str = Header(default=""),
                   x_netmon_host: str = Header(default="")):
    """Accoda allo storico le misure bufferizzate. Non tocca lo stato né genera alert."""
    probe_key, _ = await asyncio.to_thread(probe_identity, b.probe, authorization)
    await asyncio.to_thread(probe_instance_check, probe_key, x_netmon_instance, x_netmon_host)
    if not backfill_limit.take(probe_key):
        raise HTTPException(status_code=429, detail=TOO_FAST)
    if await asyncio.to_thread(disk_low):
        await asyncio.to_thread(disk_low_notice)
        raise HTTPException(status_code=507, detail="Spazio sul server esaurito: le misure restano sulla sonda.")
    now = time.time()
    oldest = oldest_accepted(now, probe_key)
    rows = []
    trows = []
    for rep in b.reports:
        trows += traffic_rows_all(probe_key, rep.traffic, rep.traffic_more, now)
        if not oldest <= rep.ts <= now + 300:      # scarto timestamp assurdi
            continue
        for n, v in rep.devices.items():
            ok = v if isinstance(v, bool) else v.ok
            rtt = None if isinstance(v, bool) else (v.rtt if v.ok else None)
            rows.append((rep.ts, probe_key, n, 1 if ok else 0, rtt))
    if (rows or trows) and not bulk_rows_limit.take(probe_key, len(rows) + len(trows)):
        raise HTTPException(status_code=429, detail=TOO_FAST)
    if rows or trows:
        await asyncio.to_thread(store_report, rows, None, trows)
    log.info("Backfill da '%s': %d report, %d misure", probe_key, len(b.reports), len(rows))
    return {"ok": True, "stored": len(rows)}


