def account_retention_body(uid):
    valore, unita = user_retention(uid)
    sv, su = retention()
    giorni = user_retention_days(uid)
    return {"value": valore, "unit": unita or "server", "days": giorni,
            "text": retention_text(valore, unita) if unita else retention_text(sv, su),
            "server_text": retention_text(sv, su), "server_days": retention_days(), "max": RETENTION_MAX}


async def check_user_pw(user, password, request):
    """Le azioni che cancellano dati chiedono di nuovo la password dell'utente."""
    ip = client_ip(request)
    too_many("ip:" + ip, "uid:%d" % user["id"])
    if not await asyncio.to_thread(auth.check_password, user["id"], password):
        throttle.fail("ip:" + ip, "uid:%d" % user["id"])
        raise HTTPException(status_code=401, detail="La password non è corretta.")


@app.get("/api/account/retention")
async def api_account_retention(user: dict = Depends(ui_user)):
    """Per quanto il server conserva lo storico delle sonde di questo account."""
    return await asyncio.to_thread(account_retention_body, user["id"])


@app.post("/api/account/retention")
async def api_account_retention_set(b: AccountRetention, request: Request, user: dict = Depends(ui_user)):
    """L'utente sceglie per quanto conservare misure ed eventi delle sue sonde (o tutto, o quanto il
    server). Accorciarla cancella subito quello che resta fuori, quindi serve la password."""
    await check_user_pw(user, b.password, request)
    if b.unit in RETENTION_UNITS and not 1 <= b.value <= RETENTION_MAX[b.unit]:
        raise HTTPException(status_code=422, detail=f"Scegli un numero da 1 a {RETENTION_MAX[b.unit]} {b.unit}.")
    valore = b.value if b.unit in RETENTION_UNITS else None
    unita = None if b.unit == "server" else b.unit
    await asyncio.to_thread(auth.set_retention, user["id"], valore, unita)
    _user_retention.clear()
    keys = set(await asyncio.to_thread(registry.keys_of, user["id"]))
    tolte = await asyncio.to_thread(purge_samples, keys) if keys else 0
    body = await asyncio.to_thread(account_retention_body, user["id"])
    log.info("Conservazione dei dati di %s: %s (%d righe eliminate)", user["email"],
             body["text"] + ("" if unita else " (quella del server)"), tolte)
    return {"ok": True, "deleted": tolte, **body}


@app.post("/api/account/history/delete")
async def api_account_history_delete(b: HistoryDelete, request: Request, user: dict = Depends(ui_user)):
    """Cancella subito tutto lo storico delle sonde dell'utente (misure ed eventi). Le sonde, la
    loro configurazione e l'account restano: da qui in poi lo storico riparte da zero."""
    await check_user_pw(user, b.password, request)
    if b.confirm.strip().upper() != "ELIMINA":
        raise HTTPException(status_code=422, detail="Per eliminare lo storico scrivi ELIMINA nel campo di conferma.")
    tolte = 0
    for key in await asyncio.to_thread(registry.keys_of, user["id"]):
        tolte += await asyncio.to_thread(wipe_history, key)
    log.warning("Storico delle sonde di %s eliminato dall'utente (%d righe)", user["email"], tolte)
    return {"ok": True, "deleted": tolte}


