NTFY_BASE = (os.getenv("NTFY_BASE", "").strip() or "https://ntfy.sh").rstrip("/")


def ntfy_suggest(email: str) -> str:
    """Topic ntfy proposto all'utente: 16 lettere e cifre calcolate dalla sua email con una chiave
    che resta sul server. Sempre lo stesso per lo stesso utente, ma non si ricava dalla sola email:
    su ntfy.sh chi conosce il nome di un topic ne legge i messaggi."""
    seed = auth.get_setting("ntfy_seed")
    if not seed:
        seed = secrets.token_hex(32)
        auth.set_setting("ntfy_seed", seed)
    n = int.from_bytes(hmac.new(seed.encode(), email.strip().lower().encode(), hashlib.sha256).digest(), "big")
    topic = ""
    for _ in range(16):
        n, r = divmod(n, 36)
        topic += "0123456789abcdefghijklmnopqrstuvwxyz"[r]
    return f"{NTFY_BASE}/netmon-{topic}"


