class TelegramTest(BaseModel):
    chat: str = Field(default="", max_length=40)


_tg_test_last = {}                 # utente -> (istante, riuscita): 20 s dopo un invio, 3 s dopo un errore


@app.post("/api/account/telegram/test")
async def api_account_telegram_test(b: TelegramTest, user: dict = Depends(ui_user)):
    """Messaggio di prova al chat ID scritto nella pagina (o a quello salvato): un chat ID sbagliato,
    o il bot mai avviato, non si vedrebbero in nessun altro modo."""
    chat = b.chat.strip()
    if not chat:
        chat = ((await asyncio.to_thread(auth.get_user, user["id"])) or {}).get("telegram_chat") or ""
    if not chat:
        raise HTTPException(status_code=422, detail="Prima scrivi il tuo chat ID.")
    if not re.match(r"^-?\d{3,20}$", chat):
        raise HTTPException(status_code=422, detail="Il chat ID di Telegram è un numero (per esempio 123456789).")
    if not os.getenv("TELEGRAM_BOT_TOKEN", "").strip():
        raise HTTPException(status_code=409, detail="Telegram non è configurato sul server.")
    now = time.time()
    last, riuscita = _tg_test_last.get(user["id"], (0, False))
    if now - last < (20 if riuscita else 3):
        raise HTTPException(status_code=429, detail="Aspetta qualche secondo prima di riprovare.")
    _tg_test_last[user["id"]] = (now, False)
    try:
        lang = user.get("lang") or "it"
        await asyncio.to_thread(send_telegram, i18n.tr(lang, "netmon: messaggio di prova"),
                                i18n.tr(lang, "Se leggi questo, gli avvisi delle tue sonde arriveranno qui."), False, "", chat)
        _tg_test_last[user["id"]] = (now, True)
    except Exception as exc:  # noqa: BLE001
        log.info("Prova Telegram non riuscita per %s: %s", user["email"], exc)
        bot = await asyncio.to_thread(telegram_bot_name)
        raise HTTPException(status_code=502, detail="Telegram non ha accettato il messaggio: controlla il chat ID "
                            "e di aver premuto Avvia nella chat con " + (f"@{bot}" if bot else "il bot del server") + ".")
    # Il messaggio di prova è arrivato: il chat ID funziona e si salva subito. Prima restava solo
    # nella pagina finché non si premeva «Salva»: la prova riusciva ma gli avvisi non partivano.
    u = (await asyncio.to_thread(auth.get_user, user["id"])) or {}
    if u and (chat != (u.get("telegram_chat") or "") or not u.get("telegram_on")):
        await asyncio.to_thread(auth.set_notify, user["id"], chat, u.get("ntfy_url") or "", u.get("notify_email"),
                                telegram_on=True)
        log.info("Chat Telegram di %s salvata dopo la prova riuscita", user["email"])
    return {"ok": True, "saved": True}


class NtfyTest(BaseModel):
    url: str = Field(default="", max_length=300)


_ntfy_test_last = {}               # utente -> (istante, riuscita), come per Telegram


@app.post("/api/account/ntfy/test")
async def api_account_ntfy_test(b: NtfyTest, user: dict = Depends(ui_user)):
    """Notifica di prova al topic scritto nella pagina: si vede subito se l'app è iscritta a quello
    giusto. Non salva nulla: ntfy si accende con l'interruttore e «Salva»."""
    url = b.url.strip()
    if not url:
        raise HTTPException(status_code=422, detail="Prima scrivi l'indirizzo del tuo topic.")
    if not re.match(r"^https://[^\s/]+/[^\s]+$", url):
        raise HTTPException(status_code=422, detail="L'indirizzo ntfy deve essere del tipo https://ntfy.sh/nome-topic.")
    now = time.time()
    last, riuscita = _ntfy_test_last.get(user["id"], (0, False))
    if now - last < (20 if riuscita else 3):
        raise HTTPException(status_code=429, detail="Aspetta qualche secondo prima di riprovare.")
    _ntfy_test_last[user["id"]] = (now, False)
    try:
        lang = user.get("lang") or "it"
        await asyncio.to_thread(send_ntfy, i18n.tr(lang, "netmon: notifica di prova"),
                                i18n.tr(lang, "Se leggi questo, gli avvisi delle tue sonde arriveranno qui."),
                                False, False, url)
        _ntfy_test_last[user["id"]] = (now, True)
    except UnsafeUrl as exc:
        raise HTTPException(status_code=422, detail=f"Indirizzo ntfy non utilizzabile: {exc}.")
    except Exception as exc:  # noqa: BLE001
        log.info("Prova ntfy non riuscita per %s: %s", user["email"], exc)
        raise HTTPException(status_code=502, detail="ntfy non ha accettato la notifica: controlla l'indirizzo.")
    return {"ok": True}


