# ------------------------------------------------------------------ funzioni dell'amministratore

# ------------------------------------------------------------------ amministrazione (pagina /admin)
# Account e sessioni separati dagli utenti: il cookie dell'amministrazione viene inviato solo
# alle API /api/admin, e gli utenti della pagina di stato non possono usarle.
ADMIN_COOKIE = "netmon_admin"
# Cookie separato dalla sessione: vive 15 giorni e dice solo «su questo dispositivo il secondo
# fattore e' gia' stato dato». Da solo non fa entrare: la password serve lo stesso.
ADMIN_TRUST_COOKIE = "netmon_admin_trust"
# Il blocco scade da solo: non serve più rigenerare la password dalla VM, che era un vicolo cieco
# per l'amministratore se qualcuno bloccava il suo account apposta.
ADMIN_LOCKED = ("Account bloccato per qualche minuto: troppi codici di verifica sbagliati. "
                "Riprova più tardi.")
# tentativi da uno stesso indirizzo IP su qualsiasi amministratore
admin_throttle = Throttle(max_fails=20, window=15 * 60)
# Password sbagliate su un amministratore: 5 per indirizzo IP, e un tetto alto da qualunque
# indirizzo. Non bloccano l'account né chiudono le sessioni (lo farebbe chiunque ne conosca
# l'email): il blocco vero, nel database, scatta solo sui codici di verifica sbagliati, a cui si
# arriva con la password giusta.
admin_pw_throttle = Throttle(max_fails=5, window=15 * 60)
admin_account_throttle = Throttle(max_fails=100, window=15 * 60)


def admin_locked_detail(minutes: int) -> str:
    """Messaggio di account bloccato con l'attesa reale, così l'utente sa quando riprovare."""
    if not minutes:
        return ADMIN_LOCKED
    if minutes == 1:
        return ADMIN_LOCKED + " Riprova tra poco."
    return ADMIN_LOCKED + f" Riprova tra circa {minutes} minuti."


def admin_lock_notice(login: str, minutes: int, ip: str):
    """Avviso all'amministratore: il suo account è stato bloccato.

    Serve perché il blocco non è più permanente: nessuno deve restare a chiedersi perché
    l'accesso non funziona, e il tentativo di blocco va registrato da qual parte di ispezionabile."""
    log.warning("Amministrazione: account %s bloccato per %d minuti (tentativo da %s)", login, minutes, ip)
    base = os.getenv("PUBLIC_URL", "").strip().rstrip("/") or "questa istanza"
    to = auth.admin_email_by_login(login)
    if to:
        send_admin_mail(to, f"netmon: account di amministrazione bloccato per {minutes} minuti",
                        f"Buongiorno,\n\nl'accesso di amministrazione all'indirizzo {base} "
                        f"è stato bloccato per {minutes} minuti dopo troppi tentativi sbagliati.\n\n"
                        f"Ultimo tentativo da: {ip}\n\n"
                        "Il blocco scade da solo e le sessioni aperte sono state chiuse. Se i tentativi "
                        "non sono tuoi, cambia la password il prima possibile dalla pagina /admin "
                        "(serve la password attuale).\n")
    else:
        log.warning("Amministrazione: nessuna email di notifica per il blocco di %s", login)


def admin_too_many(*keys, limiter=None):
    limiter = limiter or admin_throttle
    wait = limiter.wait_seconds(*keys)
    if wait:
        minutes = max(1, round(wait / 60))
        raise HTTPException(status_code=429, detail=f"Troppi tentativi non riusciti: riprova tra {minutes} "
                                                    f"{'minuto' if minutes == 1 else 'minuti'}.")
    reserve_attempt(limiter, keys)


STAGE_MESSAGES = {"mfa": "Inserisci il codice di verifica.",
                  "password": "Prima di continuare cambia la password provvisoria.",
                  "setup": "Prima di continuare attiva l'app di autenticazione."}


async def admin_user(request: Request):
    """Amministratore con accesso completo (password e verifica in due passaggi)."""
    adm = await asyncio.to_thread(auth.admin_session, request.cookies.get(ADMIN_COOKIE))
    if adm is None:
        raise HTTPException(status_code=401, detail="accesso richiesto")
    if adm["stage"] != "full":
        raise HTTPException(status_code=403, detail=STAGE_MESSAGES[adm["stage"]])
    VIEW_TZ.set(tz_named(adm.get("tz")))
    return adm


async def admin_in_stage(request: Request, *stages):
    """Amministratore a metà accesso, nella fase indicata (per i passi dell'accesso)."""
    adm = await asyncio.to_thread(auth.admin_session, request.cookies.get(ADMIN_COOKIE))
    if adm is None:
        raise HTTPException(status_code=401, detail="accesso richiesto")
    if adm["stage"] not in stages:
        raise HTTPException(status_code=409, detail=STAGE_MESSAGES.get(adm["stage"], "Passaggio non valido."))
    return adm


def set_admin_cookie(response, request: Request, raw: str):
    response.set_cookie(ADMIN_COOKIE, raw, max_age=ADMIN_SESSION_HOURS * 3600, httponly=True,
                        secure=COOKIE_SECURE, samesite="strict", path="/api/admin")


def set_trust_cookie(response, raw: str):
    # path /api: lo legge anche la schermata d'accesso unica (/api/auth/login), non solo il pannello
    response.set_cookie(ADMIN_TRUST_COOKIE, raw, max_age=ADMIN_TRUST_DAYS * 86400, httponly=True,
                        secure=COOKIE_SECURE, samesite="strict", path="/api")


