async def admin_password_step(login_in: str, password: str, request: Request, extra: Optional[dict] = None):
    """Primo passaggio dell'accesso di un amministratore (password): dal pannello o dalla schermata
    d'accesso unica della dashboard (/api/auth/login, con extra = {"redirect": "/admin"})."""
    ip, login = client_ip(request), normalize_email(login_in)
    pair = f"ip:{ip}|{login}"
    admin_too_many("ip:" + ip)
    admin_too_many(pair, limiter=admin_pw_throttle)
    admin_too_many("acct:" + login, limiter=admin_account_throttle)
    aid, outcome = await asyncio.to_thread(auth.verify_admin, login, password)
    if outcome == "locked":
        admin_throttle.fail("ip:" + ip)
        left = await asyncio.to_thread(auth.admin_lock_left, aid) if aid else 0
        await asyncio.to_thread(admin_lock_notice, login, left, ip)
        raise HTTPException(status_code=423, detail=admin_locked_detail(left))
    if outcome != "ok":
        admin_throttle.fail("ip:" + ip)
        admin_pw_throttle.fail(pair)
        admin_account_throttle.fail("acct:" + login)
        log.warning("Amministrazione: accesso non riuscito per %s da %s", login or "?", ip)
        raise HTTPException(status_code=401, detail="Email o password non corretti.")
    admin_throttle.success("ip:" + ip)
    admin_pw_throttle.success(pair)
    admin_account_throttle.success("acct:" + login)
    # Dispositivo gia' riconosciuto: la sessione nasce con il secondo fattore gia' assolto, quindi
    # si entra con la sola password. Il segno vale per QUESTO account: un cookie di un altro
    # amministratore non serve a nulla qui.
    fidato = await asyncio.to_thread(auth.device_is_trusted,
                                     request.cookies.get(ADMIN_TRUST_COOKIE), aid)
    raw = await asyncio.to_thread(auth.create_admin_session, aid, fidato)
    adm = await asyncio.to_thread(auth.admin_session, raw)
    if fidato:
        log.info("Amministrazione: %s su dispositivo riconosciuto, codice non richiesto", login)
    log.info("Amministrazione: password corretta per %s da %s (fase: %s)", login, ip, adm["stage"])
    resp = JSONResponse({"ok": True, **admin_state_body(adm), **(extra or {})})
    set_admin_cookie(resp, request, raw)
    return resp


@app.post("/api/admin/auth/mfa")
async def admin_mfa(b: AdminCode, request: Request):
    """Secondo passaggio: codice dell'app di autenticazione o codice ricevuto via email."""
    adm = await admin_in_stage(request, "mfa")
    ip = client_ip(request)
    admin_too_many("ip:" + ip)
    check = auth.totp_check if b.method == "app" else auth.mail_code_check
    outcome = await asyncio.to_thread(check, adm["id"], b.code)
    if outcome == "locked":
        admin_throttle.fail("ip:" + ip)
        left = await asyncio.to_thread(auth.admin_lock_left, adm["id"])
        admin_lock_notice(adm["login"], left, ip)
        raise HTTPException(status_code=423, detail=admin_locked_detail(left))
    if outcome == "expired":
        raise HTTPException(status_code=410, detail="Il codice è scaduto o non è stato richiesto: chiedine uno nuovo.")
    if outcome != "ok":
        admin_throttle.fail("ip:" + ip)
        raise HTTPException(status_code=401, detail="Codice non corretto.")
    raw = request.cookies.get(ADMIN_COOKIE)
    await asyncio.to_thread(auth.refresh_admin_session, raw, True)
    log.info("Amministrazione: verifica in due passaggi completata per %s (%s)", adm["login"],
             "app" if b.method == "app" else "email")
    resp = JSONResponse({"ok": True, **admin_state_body(await asyncio.to_thread(auth.admin_session, raw))})
    if b.remember:
        trust = await asyncio.to_thread(auth.trust_device, adm["id"])
        set_trust_cookie(resp, trust)
        log.info("Amministrazione: dispositivo riconosciuto per %s, niente codice per %d giorni",
                 adm["login"], ADMIN_TRUST_DAYS)
    return resp


@app.post("/api/admin/auth/mfa/email")
async def admin_mfa_email(request: Request):
    """Codice di riserva: 6 cifre via email, valido 10 minuti (al massimo 1 al minuto e 5 all'ora)."""
    adm = await admin_in_stage(request, "mfa")
    body = admin_state_body(adm)
    if not body["email_fallback"]:
        raise HTTPException(status_code=409, detail="Codice via email non disponibile per questo account.")
    code, wait = await asyncio.to_thread(auth.mail_code_new, adm["id"])
    if code is None:
        raise HTTPException(status_code=429, detail=f"Hai già chiesto un codice: puoi chiederne un altro tra "
                                                    f"{wait if wait < 120 else round(wait / 60)} "
                                                    f"{'secondi' if wait < 120 else 'minuti'}.")
    ok = await asyncio.to_thread(send_admin_mail, adm["email"], f"netmon: codice di verifica {code}",
                                 f"Il tuo codice di verifica per l'amministrazione di netmon è:\n\n    {code}\n\n"
                                 f"Vale {mfa.MAIL_CODE_MINUTES} minuti e una sola volta.\n\n"
                                 f"Se non stai accedendo tu, qualcuno conosce la tua password: cambiala appena possibile.\n"
                                 f"Richiesta da {client_ip(request)} il {local_time(time.time(), '%d/%m/%Y alle %H:%M')}.")
    if not ok:
        raise HTTPException(status_code=502, detail="Invio dell'email non riuscito: controlla la configurazione SMTP del server.")
    log.info("Amministrazione: codice di verifica inviato via email a %s", adm["login"])
    return {"ok": True, "sent_to": body["email_hint"], "minutes": mfa.MAIL_CODE_MINUTES}


@app.post("/api/admin/auth/totp/begin")
async def admin_totp_begin(b: TotpBegin, request: Request):
    """Chiave e QR code per l'app. Alla prima attivazione basta la sessione in corso; per cambiare
    telefono (accesso completo) serve di nuovo la password."""
    adm = await admin_in_stage(request, "setup", "full")
    if adm["stage"] == "full":
        ip = client_ip(request)
        admin_too_many("ip:" + ip)
        if not await asyncio.to_thread(auth.check_admin_password, adm["id"], b.password):
            admin_throttle.fail("ip:" + ip)
            raise HTTPException(status_code=401, detail="La password non è corretta.")
    secret = await asyncio.to_thread(auth.totp_begin, adm["id"])
    uri = mfa.otpauth_uri(secret, adm["email"] or adm["login"])
    return {"ok": True, "secret": mfa.group(secret), "uri": uri, "qr": await asyncio.to_thread(mfa.qr_svg, uri)}


@app.post("/api/admin/auth/totp/confirm")
async def admin_totp_confirm(b: AdminCode, request: Request):
    adm = await admin_in_stage(request, "setup", "full")
    ip = client_ip(request)
    admin_too_many("ip:" + ip)
    outcome = await asyncio.to_thread(auth.totp_confirm, adm["id"], b.code)
    if outcome == "locked":
        left = await asyncio.to_thread(auth.admin_lock_left, adm["id"])
        admin_lock_notice(adm["login"], left, ip)
        raise HTTPException(status_code=423, detail=admin_locked_detail(left))
    if outcome == "none":
        raise HTTPException(status_code=409, detail="Genera prima il QR code.")
    if outcome != "ok":
        admin_throttle.fail("ip:" + ip)
        raise HTTPException(status_code=401, detail="Codice non corretto: controlla che l'ora del telefono sia giusta e riprova.")
    raw = request.cookies.get(ADMIN_COOKIE)
    await asyncio.to_thread(auth.refresh_admin_session, raw, True)
    first = adm["stage"] == "setup"
    log.warning("Amministrazione: app di autenticazione %s per %s", "attivata" if first else "cambiata", adm["login"])
    if adm["email"]:
        await asyncio.to_thread(send_admin_mail, adm["email"], "netmon: verifica in due passaggi " + ("attivata" if first else "aggiornata"),
                                ("La verifica in due passaggi con l'app di autenticazione è stata attivata"
                                 if first else "L'app di autenticazione è stata cambiata (nuovo telefono o nuova chiave)")
                                + f" per l'amministrazione di netmon, il {local_time(time.time(), '%d/%m/%Y alle %H:%M')} "
                                  f"da {ip}.\n\nSe non sei stato tu, avvisa subito chi gestisce il server.")
    return {"ok": True, **admin_state_body(await asyncio.to_thread(auth.admin_session, raw))}


@app.post("/api/admin/auth/logout")
async def admin_logout(request: Request):
    await asyncio.to_thread(auth.delete_admin_session, request.cookies.get(ADMIN_COOKIE))
    resp = JSONResponse({"ok": True})
    resp.delete_cookie(ADMIN_COOKIE, path="/api/admin")
    return resp


@app.post("/api/admin/auth/password")
async def admin_password(b: AdminPassword, request: Request):
    """Cambio password dell'amministratore (anche quella provvisoria): chiude le altre sessioni.
    Non si può fare prima della verifica in due passaggi."""
    adm = await admin_in_stage(request, "password", "setup", "full")
    ip = client_ip(request)
    admin_too_many("ip:" + ip)
    if not await asyncio.to_thread(auth.check_admin_password, adm["id"], b.current):
        admin_throttle.fail("ip:" + ip)
        raise HTTPException(status_code=401, detail="La password attuale non è corretta.")
    problem = password_problem(b.new, adm["login"])
    if problem:
        raise HTTPException(status_code=422, detail=problem)
    if b.new == b.current:
        raise HTTPException(status_code=422, detail="La nuova password deve essere diversa da quella attuale.")
    await asyncio.to_thread(auth.set_admin_password, adm["id"], b.new)
    raw = await asyncio.to_thread(auth.create_admin_session, adm["id"], adm["mfa"])
    log.info("Amministrazione: password cambiata per %s", adm["login"])
    resp = JSONResponse({"ok": True, **admin_state_body(await asyncio.to_thread(auth.admin_session, raw))})
    set_admin_cookie(resp, request, raw)
    return resp


