@app.post("/api/admin/telegram")
async def api_admin_telegram_set(b: AdminTelegram, adm: dict = Depends(admin_user)):
    """Imposta o toglie la tua chat Telegram: gli avvisi amministrativi arrivano anche li'.

    Non serve la password: non si apre nessun accesso e non si tocca nessun altro account. Si
    sceglie dove farsi avvisare, come fa un utente dalle sue impostazioni.
    """
    chat = b.chat.strip()
    if chat and not re.match(r"^-?\d{3,20}$", chat):
        raise HTTPException(status_code=422, detail="Il chat ID di Telegram è un numero (per esempio 123456789).")
    await asyncio.to_thread(auth.set_admin_telegram, adm["id"], chat)
    log.info("Amministrazione: chat Telegram %s per %s", "impostata" if chat else "tolta", adm["login"])
    return {"ok": True, "chat": chat}


