@app.post("/api/admin/telegram/test")
async def api_admin_telegram_test(b: AdminTelegram, adm: dict = Depends(admin_user)):
    """Manda un messaggio di prova alla chat indicata: un chat ID sbagliato non si vede in nessun
    altro modo, gli avvisi semplicemente non arriverebbero."""
    chat = b.chat.strip() or await asyncio.to_thread(auth.admin_telegram, adm["id"])
    if not chat:
        raise HTTPException(status_code=422, detail="Prima indica il chat ID.")
    if not os.getenv("TELEGRAM_BOT_TOKEN", "").strip():
        raise HTTPException(status_code=409, detail="Il server non ha un bot Telegram configurato "
                                                    "(TELEGRAM_BOT_TOKEN nel file .env della VM).")
    try:
        await asyncio.to_thread(send_telegram, "netmon: messaggio di prova",
                                "Se leggi questo, gli avvisi dell'amministrazione arriveranno qui.",
                                False, "", chat)
    except Exception as exc:  # noqa: BLE001
        log.warning("Prova Telegram non riuscita per %s: %s", adm["login"], exc)
        raise HTTPException(status_code=502, detail="Telegram non ha accettato il messaggio: controlla il "
                                                    "chat ID e che tu abbia già scritto almeno una volta al bot.")
    # prova riuscita: il chat ID si salva subito, senza dover premere anche «Salva»
    if chat != await asyncio.to_thread(auth.admin_telegram, adm["id"]):
        await asyncio.to_thread(auth.set_admin_telegram, adm["id"], chat)
        log.info("Amministrazione: chat Telegram di %s salvata dopo la prova riuscita", adm["login"])
    return {"ok": True, "saved": True}


