# ------------------------------------------------------------------ backup completo e ripristino
# Server › Backup e ripristino: tutto il server (utenti, amministratori, sonde, storico, codici di
# accesso, impostazioni del pannello) in un file cifrato con la password scelta da chi lo scarica, come
# i file di trasferimento. Restano fuori il .env (chiave del server, bot Telegram) e le chiavi della
# VM (firma degli aggiornamenti delle sonde e chiave di rilascio). Il ripristino prepara i file in
# data/ripristino/ e riavvia il servizio: li mette al loro posto restore_apply(), all'avvio.
BACKUP_FORMAT = "netmon-backup-completo"
BACKUP_DBS = ("auth.db", "events.db")
BACKUP_NEEDED_TABLES = {"auth.db": ("users", "admins", "probes"), "events.db": ("events",)}


def restart_service():
    """Chiude il processo: systemd lo fa ripartire (Restart=always in netmon-server.service)."""
    os._exit(3)


def backup_counts(auth_path):
    with sqlite3.connect(f"file:{auth_path}?mode=ro", uri=True, factory=ClosingConnection) as c:
        return {t: c.execute(f"SELECT COUNT(*) FROM {t}").fetchone()[0] for t in ("users", "admins", "probes")}


def backup_build(out_zip):
    """Scrive in out_zip il backup in chiaro (poi cifrato da chi chiama). Restituisce il manifesto."""
    import zipfile
    tmpdir = Path(tempfile.mkdtemp(prefix=".backup-", dir=DATA_DIR))
    try:
        files = {}
        for name in BACKUP_DBS:                 # copia coerente anche mentre il servizio scrive
            src = sqlite3.connect(DATA_DIR / name, timeout=30)
            dst = sqlite3.connect(tmpdir / name)
            try:
                src.backup(dst)
            finally:
                dst.close()
                src.close()
            files[name] = tmpdir / name
        for name in BACKUP_FILES:
            if name not in files and (DATA_DIR / name).is_file():
                shutil.copy2(DATA_DIR / name, tmpdir / name)
                files[name] = tmpdir / name
        counts = backup_counts(files["auth.db"])
        man = {"format": BACKUP_FORMAT, "version": VERSION, "created": time.time(),
               "server": urlsplit(os.getenv("PUBLIC_URL", "")).hostname or "", "counts": counts,
               "files": {n: f.stat().st_size for n, f in files.items()}}
        with zipfile.ZipFile(out_zip, "w", zipfile.ZIP_DEFLATED) as zf:
            zf.writestr("manifest.json", json.dumps(man, indent=1))
            for name, f in files.items():
                zf.write(f, name)
        return man
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)


def backup_read(path):
    """Manifesto di un backup in chiaro, dopo averne controllato contenuto e versione."""
    import zipfile
    try:
        zf = zipfile.ZipFile(path)
    except (zipfile.BadZipFile, OSError):
        raise HTTPException(status_code=422, detail="Il file non è un backup di netmon.")
    with zf:
        names = set(zf.namelist())
        try:
            man = json.loads(zf.read("manifest.json"))
        except (KeyError, ValueError):
            raise HTTPException(status_code=422, detail="Il file non è un backup completo di netmon "
                                                        "(per un singolo utente usa «Importa un utente»).")
        if not isinstance(man, dict) or man.get("format") != BACKUP_FORMAT:
            raise HTTPException(status_code=422, detail="Il file non è un backup completo di netmon "
                                                        "(per un singolo utente usa «Importa un utente»).")
        extra = names - {"manifest.json", *BACKUP_FILES}
        if extra or not set(BACKUP_DBS) <= names:
            raise HTTPException(status_code=422, detail="Backup incompleto o con file inattesi: non si può ripristinare.")
        if pkgcheck.version_key(str(man.get("version"))) > pkgcheck.version_key(VERSION):
            raise HTTPException(status_code=422, detail=f"Il backup viene da netmon {man.get('version')}, più recente di "
                                                        f"quella installata ({VERSION}): aggiorna prima il server.")
        man["size"] = sum(i.file_size for i in zf.infolist())
    return man


def backup_stage(path):
    """Estrae il backup in data/ripristino/, controlla i database e lo segna pronto per l'avvio."""
    import zipfile
    man = backup_read(path)
    if shutil.disk_usage(DATA_DIR).free < man["size"] + MIN_FREE_MB * 1024 * 1024:
        raise HTTPException(status_code=507, detail="Spazio su disco insufficiente per il ripristino.")
    shutil.rmtree(RESTORE_DIR, ignore_errors=True)
    RESTORE_DIR.mkdir(mode=0o700)
    ok = False
    try:
        with zipfile.ZipFile(path) as zf:
            for name in BACKUP_FILES:
                if name in zf.namelist():
                    with zf.open(name) as src, open(RESTORE_DIR / name, "wb") as dst:
                        shutil.copyfileobj(src, dst, 1024 * 1024)
        for name, tables in BACKUP_NEEDED_TABLES.items():
            try:
                with sqlite3.connect(f"file:{RESTORE_DIR / name}?mode=ro", uri=True, factory=ClosingConnection) as c:
                    if c.execute("PRAGMA integrity_check").fetchone()[0] != "ok":
                        raise sqlite3.DatabaseError("integrity_check")
                    have = {r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type = 'table'")}
            except sqlite3.DatabaseError:
                raise HTTPException(status_code=422, detail=f"Nel backup il database {name} è danneggiato: non si può ripristinare.")
            if not set(tables) <= have:
                raise HTTPException(status_code=422, detail=f"Nel backup il database {name} non è di netmon.")
        for name in ("state.json", "speedtests.json", "scans.json", "inactive.json"):
            f = RESTORE_DIR / name
            if f.exists():
                try:
                    json.loads(f.read_text(encoding="utf-8"))
                except (OSError, ValueError):
                    raise HTTPException(status_code=422, detail=f"Nel backup il file {name} è danneggiato.")
        (RESTORE_DIR / "PRONTO").write_text(json.dumps(man))
        ok = True
    finally:
        if not ok:
            shutil.rmtree(RESTORE_DIR, ignore_errors=True)
    return man


class BackupExport(BaseModel):
    password: str = Field(default="", max_length=256)
    file_password: str = Field(default="", max_length=256)


@app.post("/api/admin/backup/export")
async def api_backup_export(b: BackupExport, request: Request, adm: dict = Depends(admin_user)):
    """Prepara il backup completo cifrato; si scarica con /api/admin/transfer/download."""
    await check_admin_pw(adm, b.password, request)
    if len(b.file_password) < FILE_PW_MIN:
        raise HTTPException(status_code=422, detail=f"La password del file deve avere almeno {FILE_PW_MIN} caratteri.")
    need = sum((DATA_DIR / n).stat().st_size for n in BACKUP_FILES if (DATA_DIR / n).is_file())
    if shutil.disk_usage(DATA_DIR).free < 2 * need + MIN_FREE_MB * 1024 * 1024:
        raise HTTPException(status_code=507, detail="Spazio su disco insufficiente per preparare il backup.")
    TRANSFER_DIR.mkdir(mode=0o700, parents=True, exist_ok=True)
    name = secrets.token_hex(8)
    plain, path = TRANSFER_DIR / f"backup-{name}.zip", TRANSFER_DIR / f"backup-{name}.netmon"
    host = re.sub(r"[^A-Za-z0-9.-]+", "_", urlsplit(public_base(request)).hostname or "server")
    tid = transfer_new("export", adm, file=str(path),
                       name=f"netmon-backup-{host}-{datetime.now(LOCAL_TZ).strftime('%Y%m%d-%H%M')}.netmon")

    async def work():
        async with lock:
            await asyncio.to_thread(flush_state)      # lo stato delle sonde di adesso, non quello di qualche secondo fa
        try:
            man = await asyncio.to_thread(backup_build, plain)
            await asyncio.to_thread(xfer_encrypt, plain, path, b.file_password)
        finally:
            plain.unlink(missing_ok=True)             # il backup in chiaro non resta sul disco
        c = man["counts"]
        log.warning("Backup completo scaricato da %s (%d utenti, %d amministratori, %d sonde)", adm["login"],
                    c["users"], c["admins"], c["probes"])
        await asyncio.to_thread(admin_notice, "[INFO] Backup completo del server",
                                f"{adm.get('name') or adm['login']} ha creato un backup completo del server "
                                f"({c['users']} utenti, {c['admins']} amministratori, {c['probes']} sonde).")
        return {**c, "size": path.stat().st_size}
    asyncio.create_task(transfer_run(tid, "export", work))
    return {"ok": True, "id": tid}


@app.post("/api/admin/backup/upload")
async def api_backup_upload(request: Request, id: str = Query(max_length=64), part: int = Query(ge=0, lt=600),
                            parts: int = Query(ge=1, le=600), adm: dict = Depends(admin_user)):
    """Un pezzo del file di backup da ripristinare (corpo application/octet-stream)."""
    if not _TRANSFER_ID.fullmatch(id):
        raise HTTPException(status_code=422, detail="Identificativo non valido.")
    data = await request.body()
    if not data or len(data) > TRANSFER_PART + 1024:
        raise HTTPException(status_code=413, detail="Pezzo vuoto o troppo grande.")
    if parts * TRANSFER_PART > TRANSFER_MAX:
        raise HTTPException(status_code=413, detail="File troppo grande.")
    folder = TRANSFER_DIR / f"bk-{id}"

    def store():
        transfer_clean()
        TRANSFER_DIR.mkdir(mode=0o700, parents=True, exist_ok=True)
        folder.mkdir(mode=0o700, exist_ok=True)
        (folder / f"{part:04d}").write_bytes(data)
        if part != parts - 1:
            return {"ok": True, "received": part + 1}
        if any(not (folder / f"{i:04d}").exists() for i in range(parts)):
            raise HTTPException(status_code=422, detail="Caricamento incompleto: riprova.")
        whole = folder / "upload"
        with open(whole, "wb") as out:
            for i in range(parts):
                with open(folder / f"{i:04d}", "rb") as f:
                    shutil.copyfileobj(f, out, 1024 * 1024)
                (folder / f"{i:04d}").unlink()
        if not xfer_encrypted(whole):
            shutil.rmtree(folder, ignore_errors=True)
            raise HTTPException(status_code=422, detail="Il file non è un backup cifrato di netmon.")
        return {"ok": True, "encrypted": True}
    return await asyncio.to_thread(store)


class BackupOpen(BaseModel):
    id: str = Field(max_length=64)
    file_password: str = Field(max_length=256)


@app.post("/api/admin/backup/open")
async def api_backup_open(b: BackupOpen, adm: dict = Depends(admin_user)):
    """Apre il backup caricato con la sua password e dice cosa contiene (niente viene ancora toccato)."""
    if not _TRANSFER_ID.fullmatch(b.id):
        raise HTTPException(status_code=422, detail="Identificativo non valido.")
    folder = TRANSFER_DIR / f"bk-{b.id}"
    if not (folder / "upload").exists() and not (folder / "zip").exists():
        raise HTTPException(status_code=404, detail="File non trovato (caricato più di 2 ore fa?): caricalo di nuovo.")

    def open_file():
        if not (folder / "zip").exists():
            tmp = folder / "zip.tmp"
            try:
                xfer_decrypt(folder / "upload", tmp, b.file_password)
            except ValueError as exc:
                log.warning("Backup non aperto da %s: password sbagliata o file danneggiato", adm["login"])
                raise HTTPException(status_code=422, detail=str(exc))
            tmp.replace(folder / "zip")
            (folder / "upload").unlink(missing_ok=True)
        man = backup_read(folder / "zip")
        return {"ok": True, "version": man.get("version"), "created": fmt_when(man.get("created")),
                "server": man.get("server") or "", "counts": man.get("counts") or {}, "size": man["size"],
                "current": backup_counts(DATA_DIR / "auth.db")}
    return await asyncio.to_thread(open_file)


class BackupRestore(BaseModel):
    id: str = Field(max_length=64)
    password: str = Field(default="", max_length=256)
    confirm: str = Field(default="", max_length=20)


@app.post("/api/admin/backup/restore")
async def api_backup_restore(b: BackupRestore, request: Request, adm: dict = Depends(admin_user)):
    """Ripristina il backup aperto: prepara i file e riavvia il servizio. Tutti i dati di adesso vengono
    sostituiti (restano da parte in data/prima-del-ripristino-…)."""
    await check_admin_pw(adm, b.password, request)
    if b.confirm != "RIPRISTINA":
        raise HTTPException(status_code=422, detail="Scrivi RIPRISTINA per confermare.")
    whole = TRANSFER_DIR / f"bk-{b.id}" / "zip"
    if not _TRANSFER_ID.fullmatch(b.id) or not whole.exists():
        raise HTTPException(status_code=404, detail="Backup non trovato (caricato più di 2 ore fa?): caricalo di nuovo.")
    if any(t["state"] == "running" for t in _transfers.values()):
        raise HTTPException(status_code=409, detail="C'è un trasferimento in corso: aspetta che finisca.")
    man = await asyncio.to_thread(backup_stage, whole)
    await asyncio.to_thread(shutil.rmtree, whole.parent, True)
    c = man.get("counts") or {}
    log.warning("Ripristino del backup del %s (netmon %s) avviato da %s: il servizio si riavvia",
                fmt_when(man.get("created")), man.get("version"), adm["login"])
    await asyncio.to_thread(admin_notice, "[INFO] Ripristino di un backup completo",
                            f"{adm.get('name') or adm['login']} ha ripristinato il backup del {fmt_when(man.get('created'))} "
                            f"(netmon {man.get('version')}: {c.get('users', '?')} utenti, {c.get('admins', '?')} "
                            f"amministratori, {c.get('probes', '?')} sonde). I dati di prima sono sulla VM in "
                            "data/prima-del-ripristino-….")
    asyncio.get_running_loop().call_later(1.5, restart_service)
    return {"ok": True, "restart": True}


# ------------------------------------------------------------------ aggiornamenti programmati (VM e sonde)
# Un amministratore programma un aggiornamento per una data e un'ora (o per subito). Il watchdog lo
# avvia all'ora stabilita: sulla VM con lo stesso script del pulsante "Aggiorna sistema" (oppure,
# per un pacchetto netmon.zip caricato, con netmon-vm-selfupdate), sulle sonde come comando
# consegnato al report successivo (le sonde spente lo ricevono quando tornano).
# Un aggiornamento delle sonde può essere "a catena" (after_id): parte solo quando è finito bene
# l'aggiornamento della VM da cui dipende; se quello non riesce o viene annullato, si annulla anche lui.
# Dopo un aggiornamento del sistema si riavvia solo se serve (nuovo kernel e simili). Il riavvio
# della VM si può anche programmare da solo (cmd "reboot"): non ha una fase "in corso" da seguire,
# perché a riavviarsi è il server stesso, quindi l'esito viene scritto PRIMA di lanciarlo.
# Avvisi: subito, 1 ora prima (se programmato con più anticipo) e se viene annullato; ai
# proprietari delle sonde sui loro canali, agli amministratori via email. Tutto finisce anche nel
# registro eventi.
SCHED_WHAT = {"upgrade": "Aggiornamento del sistema", "update": "Aggiornamento di netmon",
              "package": "Aggiornamento di netmon da pacchetto", "reboot": "Riavvio"}
SCHED_MAX_DAYS = 90
SCHED_VM_TIMEOUT = 3 * 3600
SCHED_PKG_TIMEOUT = 45 * 60


def sched_keys(s):
    """Sonde a cui è destinata la programmazione: quelle indicate, oppure tutte quelle con un account."""
    owned = registry.owned_keys()
    keys = s["probes"] if s["probes"] is not None else list(monitor.state)
    return [k for k in keys if k in monitor.state and k in owned]


def sched_now(s):
    """Programmata per «Adesso» (e non per una data e un'ora): parte senza avvisi, solo nel registro."""
    return s["at"] - s["created"] < 90


def sched_when(s):
    when = "adesso" if s["at"] - s["created"] < 90 else "il " + local_time(s["at"], "%d/%m/%Y alle %H:%M")
    return f"dopo l'aggiornamento della VM ({when})" if s.get("after_id") else when


def sched_version(s):
    return (s.get("package") or {}).get("version") or ""


# cosa è stato scelto per le sonde insieme all'installazione di un pacchetto sulla VM
PROBES_AFTER = {"none": "Per le sonde non è stato programmato nessun aggiornamento.",
                "all": "Dopo la VM si aggiornano tutte le sonde.",
                "some": "Dopo la VM si aggiornano le sonde scelte."}


def sched_text(s, kind):
    """(titolo, corpo) dell'avviso. kind: created | reminder | cancelled"""
    what = SCHED_WHAT[s["cmd"]]
    where = "della VM" if s["target"] == "vm" else "delle sonde"
    tag = {"created": "[PROGRAMMATO]", "reminder": "[TRA UN'ORA]", "cancelled": "[ANNULLATO]"}[kind]
    when = sched_when(s)
    title = f"{tag} {what} {where} {when}" if kind != "reminder" else f"{tag} {what} {where}"
    if s["target"] == "vm" and s["cmd"] == "package":
        pkg = s.get("package") or {}
        effect = (f"Si installa netmon {pkg.get('version', '?')} dal pacchetto caricato da {pkg.get('by', '?')} "
                  f"(impronta SHA-256 {str(pkg.get('sha256', ''))[:16]}…), al posto della {VERSION}. "
                  "Il server si riavvia: pagina di stato e avvisi si fermano per circa un minuto, le sonde "
                  "conservano le misure e le inviano quando il server torna. Se il server non riparte, "
                  "torna da solo la versione precedente.")
        if "probes_changed" in pkg:
            effect += "\n\n" + probes_need_text(pkg["probes_changed"]) + " " + PROBES_AFTER.get(pkg.get("probes_after"), "")
    elif s["target"] == "vm" and s["cmd"] == "reboot":
        effect = ("La VM viene riavviata, senza aggiornare nulla: pagina di stato e avvisi si fermano per un "
                  "paio di minuti, le sonde conservano le misure e le inviano quando il server torna.")
    elif s["target"] == "vm":
        effect = ("Si aggiornano i pacchetti del sistema operativo della VM. Se serve (per esempio per un "
                  "nuovo kernel) la VM si riavvia da sola alla fine: pagina di stato e avvisi si fermano per "
                  "un paio di minuti, le sonde conservano le misure e le inviano quando il server torna.")
    elif s["cmd"] == "upgrade":
        effect = ("Si aggiornano i pacchetti del sistema operativo delle sonde. Se serve (per esempio per un "
                  "nuovo kernel) ogni sonda si riavvia da sola alla fine: qualche minuto senza misure.")
    else:
        effect = ("Le sonde passano alla versione di netmon del server "
                  f"({sched_version(s) or probe_dist_version() or 'non disponibile'}): si riavviano per "
                  "qualche secondo.")
        if s.get("after_id"):
            effect += " Partono solo se l'aggiornamento della VM riesce."
    cosa = "un riavvio" if s["cmd"] == "reboot" else "un aggiornamento"
    il_cosa = "Il riavvio" if s["cmd"] == "reboot" else "L'aggiornamento"
    lead = {"created": f"È stato programmato {cosa}: {when}.",
            "reminder": f"Promemoria: {il_cosa.lower()} parte tra circa un'ora ({local_time(s['at'], '%H:%M del %d/%m/%Y')}).",
            "cancelled": f"{il_cosa} programmato {when} è stato annullato: non verrà eseguito."}[kind]
    body = lead + ("" if kind == "cancelled" else "\n\n" + effect)
    return title, body


def sched_announce(s, kind, by=""):
    """Avvisi della programmazione: proprietari (le loro sonde) e amministratori (tutto).
    Un aggiornamento «Adesso» non manda notifiche a nessuno: resta solo nel registro eventi
    (se qualcosa va storto, gli amministratori ricevono comunque l'allarme)."""
    title, body = sched_text(s, kind)
    quiet = kind == "created" and sched_now(s)
    who = f"\n\nProgrammato da {s['created_by']}." if kind != "cancelled" else (f"\n\nAnnullato da {by}." if by else "")
    if s["target"] == "probes":
        keys = sched_keys(s)
        by_owner = {}
        for k in keys:
            by_owner.setdefault(registry.owner_of(k), []).append(k)
        for owner, ks in by_owner.items():
            names = [label_of(k, monitor.state[k]) for k in ks if k in monitor.state]
            send, to = recipients(ks[0])
            with viewer_tz((to or {}).get("tz")):              # orari nel fuso del proprietario
                otitle, obody = sched_text(s, kind)
            text = obody + "\n\nSonde interessate:\n" + "\n".join(f"    {n}" for n in names)
            if send and not quiet:
                notify(otitle, text, False, False, "", to, "manutenzione")
            if kind != "reminder":
                for k in ks:
                    add_event(f"{title.split(' ', 1)[0]} {SCHED_WHAT[s['cmd']]} della sonda "
                              f"'{label_of(k, monitor.state[k])}' {sched_when(s)}", "", kind != "cancelled", k)
        body += "\n\nSonde interessate: " + (", ".join(label_of(k, monitor.state[k]) for k in keys) or "nessuna")
        if kind != "reminder":
            add_event(title, body, kind != "cancelled", None)       # registro amministrativo
    else:
        if kind != "reminder":
            add_event(title, "", kind != "cancelled", None)
        if not quiet:
            users_notice(lambda: sched_user_text(s, kind), kind != "cancelled")   # manutenzione: tutti gli utenti
    if quiet or s.get("batch"):          # campagna del pannello: agli admin un solo riepilogo (sched_batch_*)
        return
    if s["cmd"] == "package" and kind == "created":
        who += "\nSe non te lo aspettavi, annullalo subito dal pannello /admin, scheda Server."
    admin_send(title, body + who, "manutenzione")


def sched_user_text(s, kind):
    """(titolo, corpo) dell'avviso di manutenzione della VM per gli utenti: cosa succede al servizio,
    senza dettagli tecnici. kind: created | reminder | cancelled"""
    when = sched_when(s)
    if kind == "cancelled":
        return (f"[ANNULLATO] Manutenzione del server netmon {when}",
                f"La manutenzione del server netmon programmata {when} è stata annullata.")
    if s["cmd"] == "reboot":
        effect = ("Il server viene riavviato: per un paio di minuti pagina di stato e avvisi non sono "
                  "disponibili.")
    elif s["cmd"] == "package":
        effect = ("Si installa una nuova versione di netmon: il server si riavvia e per circa un minuto pagina "
                  "di stato e avvisi non sono disponibili.")
    else:
        effect = ("Si aggiorna il sistema del server: se alla fine serve un riavvio, pagina di stato e avvisi "
                  "non sono disponibili per un paio di minuti.")
    effect += " Le tue sonde continuano a misurare e inviano i dati appena il server torna."
    if kind == "reminder":
        return ("[TRA UN'ORA] Manutenzione del server netmon",
                f"Promemoria: la manutenzione del server parte tra circa un'ora "
                f"({local_time(s['at'], '%H:%M del %d/%m/%Y')}).\n\n{effect}")
    return (f"[MANUTENZIONE] Manutenzione del server netmon {when}",
            f"È prevista una manutenzione del server netmon: {when}.\n\n{effect}")


def users_notice(make, ok=True):
    """Avviso a tutti gli utenti che hanno almeno una sonda (manutenzione della VM): sui loro canali e
    negli Ultimi eventi della loro pagina (una volta per utente, sulla prima delle sue sonde).
    make() -> (titolo, testo), composto per ognuno nel suo fuso orario."""
    first = {}
    for k in sorted(registry.owned_keys()):
        owner = registry.owner_of(k)
        if owner is not None and owner not in first:
            first[owner] = k
    for owner, k in first.items():
        send, to = recipients(k)
        if not send:
            continue                                    # utente bloccato
        with viewer_tz(to.get("tz")):
            title, body = make()
        add_event(title, body, ok, k)
        notify(title, body, False, False, "", to, "manutenzione")


# Aggiornamenti automatici delle sonde (Impostazioni → Sonde, attivi se l'utente non li ha spenti):
# quando il server distribuisce una versione nuova, le sonde rimaste indietro ricevono il comando di
# aggiornamento come dal pannello. Solo sonde in linea, non in pausa, libere e capaci di aggiornarsi
# da remoto (non l'add-on di Home Assistant, che si aggiorna da Home Assistant); un tentativo ogni
# PROBE_AUTO_GAP per sonda e al massimo PROBE_AUTO_MAX per giro, per non aggiornarle tutte insieme.
PROBE_AUTO_GAP = 6 * 3600
PROBE_AUTO_MAX = 20
_auto_upd = {}


def auto_update_run(owners, off, pause, now=None):
    """Chiede l'aggiornamento alle sonde che ne hanno bisogno. owners: sonda -> proprietario; off:
    utenti che hanno spento gli aggiornamenti automatici; pause: sonde in pausa."""
    now = now or time.time()
    if not probe_dist_version():
        return []
    started = []
    for k, p in monitor.state.items():
        if len(started) >= PROBE_AUTO_MAX:
            break
        sysd, owner = p.get("system") or {}, owners.get(k)
        if (owner is None or owner in off or k in pause or p.get("offline") or not sysd.get("version")
                or sysd.get("remote_ops") is False or sysd.get("managed_by")
                or probe_is_current(sysd.get("version"))
                or (p.get("command") or {}).get("state") in ("pending", "running")
                or now - _auto_upd.get(k, 0) < PROBE_AUTO_GAP):
            continue
        _auto_upd[k] = now
        p["command"] = {"id": secrets.token_hex(8), "cmd": "update", "state": "pending", "requested": now,
                        "by": "aggiornamento automatico"}
        started.append(k)
    return started


def sched_start_probes(s):
    """Consegna il comando alle sonde (al report successivo). Restituisce l'esito da mostrare."""
    dist = probe_dist_version()
    sent, busy, same, spente, gestite = [], [], [], [], []
    # «Tutte le sonde»: salta quelle degli utenti che hanno spento gli aggiornamenti automatici
    # (le sonde scelte una per una dall'amministratore si aggiornano comunque)
    off = auth.probe_auto_off() if s["cmd"] == "update" and s["probes"] is None else set()
    for k in sched_keys(s):
        p = monitor.state[k]
        if off and registry.owner_of(k) in off:
            spente.append(label_of(k, p))
            continue
        if probe_managed_by(p):                    # si aggiorna e si riavvia dal sistema che la gestisce
            gestite.append(label_of(k, p))
            continue
        cur = p.get("command") or {}
        if cur.get("state") in ("pending", "running"):
            busy.append(label_of(k, p))
            continue
        if s["cmd"] == "update" and probe_is_current((p.get("system") or {}).get("version")):
            same.append(label_of(k, p))
            continue
        p["command"] = {"id": secrets.token_hex(8), "cmd": s["cmd"], "state": "pending", "requested": time.time(),
                        "by": f"programmato da {s['created_by']}", "auto_reboot": s["cmd"] == "upgrade",
                        "schedule": s["id"]}
        sent.append(label_of(k, p))
    save_state()
    parts = [f"inviato a {len(sent)} {'sonda' if len(sent) == 1 else 'sonde'}"]
    if same:
        parts.append(f"{len(same)} già alla versione {dist}")
    if busy:
        parts.append(f"{len(busy)} con un'altra operazione in corso ({', '.join(busy)})")
    if spente:
        parts.append(f"{len(spente)} saltate perché l'utente ha spento gli aggiornamenti automatici ({', '.join(spente)})")
    if gestite:
        parts.append(f"{len(gestite)} saltate perché gestite da un altro sistema, che le aggiorna e le riavvia "
                     f"({', '.join(gestite)})")
    return "; ".join(parts)


def sched_children(sid):
    return [c for c in auth.schedules_in("pending") if c.get("after_id") == sid]


def sched_cancel_children(s, reason, by=""):
    """La programmazione s non verrà eseguita (o non è riuscita): annulla quelle che aspettavano lei."""
    for c in sched_children(s["id"]):
        auth.update_schedule(c["id"], state="cancelled", result=reason, finished=time.time())
        sched_announce(c, "cancelled", by)


def sched_drop_package(s):
    """Elimina il file del pacchetto di una programmazione conclusa o annullata."""
    name = (s.get("package") or {}).get("file") or ""
    if re.fullmatch(r"pkg-[0-9a-f]{16}\.zip", name) and not any(
            (o.get("package") or {}).get("file") == name for o in auth.schedules_in("pending", "running") if o["id"] != s["id"]):
        (UPLOAD_DIR / name).unlink(missing_ok=True)
        sig_of(UPLOAD_DIR / name).unlink(missing_ok=True)


_sched_lock = asyncio.Lock()


async def run_schedules():
    async with _sched_lock:                             # mai due esecuzioni insieme (watchdog e pulsante)
        await _run_schedules()


async def _admin_mail_all(subject, body, s=None):
    """Errore di un aggiornamento programmato: agli amministratori, come allarme. In una campagna del
    pannello no: l'errore finisce nel riepilogo finale (sched_batch_tick), insieme a tutto il resto."""
    if s is not None and s.get("batch"):
        return
    await asyncio.to_thread(admin_send, subject.removeprefix("netmon: "), body, "allarmi", True)


async def _start_package(s, now):
    """Avvia l'installazione del pacchetto di una programmazione: ricontrollato subito prima."""
    pkg = s.get("package") or {}
    path = UPLOAD_DIR / str(pkg.get("file") or "-")

    def prepare():
        if not re.fullmatch(r"pkg-[0-9a-f]{16}\.zip", path.name) or not path.is_file():
            return "il pacchetto caricato non c'è più: caricalo di nuovo"
        if hashlib.sha256(path.read_bytes()).hexdigest() != pkg.get("sha256"):
            return "il pacchetto caricato è stato modificato: caricalo di nuovo"
        sig = read_sig(path)
        report = package_check(path, sig)
        if not report["ok"] or report["version"] != pkg.get("version"):
            return "pacchetto non più idoneo: " + "; ".join(report["errors"])
        # prima la firma, poi lo zip: netmon-vm-selfupdate li legge insieme
        sig_of(STAGED_ZIP).write_bytes(sig)
        tmp = UPLOAD_DIR / ".netmon.zip.tmp"
        shutil.copyfile(path, tmp)
        os.replace(tmp, STAGED_ZIP)
        return ""
    problem = await asyncio.to_thread(prepare)
    if not problem:
        # "in corso" PRIMA di avviare: l'installazione riavvia questo stesso servizio
        await asyncio.to_thread(auth.update_schedule, s["id"], state="running", result="in corso")
        ok, message = await asyncio.to_thread(vmops.start_selfupdate)
        if ok:
            await asyncio.to_thread(add_event, f"[AVVIATO] Aggiornamento di netmon della VM {VERSION} → "
                                               f"{pkg.get('version')} (programmato da {s['created_by']})")
            log.warning("Aggiornamento programmato %d: installazione di netmon %s avviata", s["id"], pkg.get("version"))
            return
        problem = message
    await asyncio.to_thread(auth.update_schedule, s["id"], state="error", result=problem, finished=now)
    await asyncio.to_thread(add_event, "[ALERT] Aggiornamento programmato di netmon della VM non avviato", problem, False)
    await asyncio.to_thread(sched_cancel_children, s, "non eseguito: l'aggiornamento della VM non è partito")
    await asyncio.to_thread(sched_drop_package, s)
    await _admin_mail_all("netmon: aggiornamento programmato di netmon della VM non avviato",
                          f"L'installazione di netmon {pkg.get('version')} programmata da {s['created_by']} "
                          f"non è partita:\n\n    {problem}", s)
    log.warning("Aggiornamento programmato %d non avviato: %s", s["id"], problem)


async def _run_schedules():
    now = time.time()
    await asyncio.to_thread(sched_batch_tick)
    for s in await asyncio.to_thread(auth.schedules_in, "pending"):
        # promemoria un'ora prima, solo se programmato con più di un'ora di anticipo
        if not s["reminded"] and s["at"] > now and s["at"] - now <= 3600 and s["at"] - s["created"] > 3600:
            await asyncio.to_thread(auth.update_schedule, s["id"], reminded=1)
            await asyncio.to_thread(sched_announce, s, "reminder")
        if s["at"] > now:
            continue
        if s.get("after_id"):                          # a catena: aspetta l'aggiornamento della VM
            parent = await asyncio.to_thread(auth.get_schedule, s["after_id"])
            if parent is not None and parent["state"] in ("pending", "running"):
                continue
            if parent is None or parent["state"] != "done":
                await asyncio.to_thread(auth.update_schedule, s["id"], state="cancelled", finished=now,
                                        result="non eseguito: l'aggiornamento della VM non è riuscito")
                continue
        if s["target"] == "probes":
            async with lock:
                result = sched_start_probes(s)
            await asyncio.to_thread(auth.update_schedule, s["id"], state="done", result=result, finished=now)
            log.warning("Aggiornamento programmato %d avviato: %s", s["id"], result)
            continue
        # VM: se è già in corso un aggiornamento avviato a mano, aspetto che finisca (fino a un'ora)
        busy = ((await asyncio.to_thread(vmops.upgrade_status)).get("state") == "running"
                or (await asyncio.to_thread(vmops.selfupdate_status)).get("state") == "running")
        if busy:
            if now - s["at"] > 3600:
                await asyncio.to_thread(auth.update_schedule, s["id"], state="error", finished=now,
                                        result="non avviato: un altro aggiornamento era in corso")
                await asyncio.to_thread(sched_cancel_children, s, "non eseguito: l'aggiornamento della VM non è partito")
                await asyncio.to_thread(sched_drop_package, s)
            continue
        if s["cmd"] == "package":
            await _start_package(s, now)
            continue
        if s["cmd"] == "reboot":
            await _start_reboot(s, now)
            continue
        ok, message = await asyncio.to_thread(vmops.start_upgrade)
        if ok:
            await asyncio.to_thread(auth.update_schedule, s["id"], state="running", result="in corso")
            await asyncio.to_thread(add_event, "[AVVIATO] Aggiornamento programmato del sistema della VM")
        else:
            await asyncio.to_thread(auth.update_schedule, s["id"], state="error", result=message, finished=now)
            await asyncio.to_thread(add_event, "[ALERT] Aggiornamento programmato della VM non avviato", message, False)
        log.warning("Aggiornamento programmato della VM: %s", message)

    for s in await asyncio.to_thread(auth.schedules_in, "running"):
        if s["cmd"] == "package":
            await _poll_package(s, now)
            continue
        if s["cmd"] == "reboot":
            continue            # chiuso appena lanciato: non c'e' un "in corso" da seguire
        st = await asyncio.to_thread(vmops.upgrade_status)
        fresh = (st.get("started") or 0) >= s["at"] - 5
        if fresh and st.get("state") == "running":
            if now - s["at"] > SCHED_VM_TIMEOUT:
                await asyncio.to_thread(auth.update_schedule, s["id"], state="error", finished=now,
                                        result="l'aggiornamento non è terminato entro 3 ore")
            continue
        if not fresh or st.get("state") not in ("ok", "error"):
            if now - s["at"] > SCHED_VM_TIMEOUT:
                await asyncio.to_thread(auth.update_schedule, s["id"], state="error", finished=now,
                                        result="esito dell'aggiornamento non disponibile")
            continue
        if st["state"] == "error":
            await asyncio.to_thread(auth.update_schedule, s["id"], state="error", finished=now,
                                    result="aggiornamento non riuscito: vedi il registro nella scheda Server")
            await asyncio.to_thread(add_event, "[ALERT] Aggiornamento programmato della VM non riuscito", "", False)
            await _admin_mail_all("netmon: aggiornamento programmato della VM non riuscito",
                                  "L'aggiornamento programmato del sistema della VM non è riuscito.\n\n"
                                  "Il registro è nella pagina /admin, scheda Server.", s)
            continue
        rb = await asyncio.to_thread(vmops.reboot_required)
        result = "completato" + (", riavvio della VM" if rb.get("required") else ", nessun riavvio necessario")
        await asyncio.to_thread(auth.update_schedule, s["id"], state="done", result=result, finished=now)
        await asyncio.to_thread(add_event if sched_now(s) or s.get("batch") else admin_notice,
                                f"[OK] Aggiornamento programmato della VM {result}")
        log.warning("Aggiornamento programmato della VM %s", result)
        if rb.get("required"):
            _state_dirty[0] = True
            await asyncio.to_thread(flush_state)
            ok, message = await asyncio.to_thread(vmops.reboot, 10)
            if ok:
                await asyncio.to_thread(auth.set_setting, "vm_last_reboot",
                                        json.dumps({"ts": time.time(), "by": "aggiornamento programmato"}))


async def _start_reboot(s, now):
    """Riavvio programmato della VM. L'esito si scrive PRIMA di lanciarlo: subito dopo il server
    non c'e' piu', e al ritorno la programmazione deve risultare fatta, non rimasta "in corso"."""
    if not (await asyncio.to_thread(vmops.permissions)).get("can_reboot"):
        await asyncio.to_thread(auth.update_schedule, s["id"], state="error", finished=now,
                                result="permessi non configurati per il riavvio")
        await asyncio.to_thread(add_event, "[ALERT] Riavvio programmato della VM non avviato",
                                vmops.SUDOERS_HINT, False)
        return
    _state_dirty[0] = True
    await asyncio.to_thread(flush_state)                 # stato delle sonde salvato prima del riavvio
    await asyncio.to_thread(auth.update_schedule, s["id"], state="done", finished=now,
                            result="riavvio avviato")
    await asyncio.to_thread(auth.set_setting, "vm_last_reboot",
                            json.dumps({"ts": time.time(), "by": f"programmato da {s['created_by']}"}))
    await asyncio.to_thread(add_event, "[AVVIATO] Riavvio programmato della VM")
    # 15 secondi: il tempo di scrivere tutto e di far partire gli avvisi
    ok, message = await asyncio.to_thread(vmops.reboot, 15)
    if not ok:
        await asyncio.to_thread(auth.update_schedule, s["id"], state="error", finished=now, result=message)
        await asyncio.to_thread(add_event, "[ALERT] Riavvio programmato della VM non avviato", message, False)
    log.warning("Riavvio programmato della VM: %s", message)


async def _poll_package(s, now):
    """Esito dell'installazione di un pacchetto (controllato anche dal server appena riavviato)."""
    st = await asyncio.to_thread(vmops.selfupdate_status)
    fresh = (st.get("started") or 0) >= s["at"] - 5
    pkg = s.get("package") or {}
    if not fresh or st.get("state") not in ("ok", "error"):
        if now - s["at"] > SCHED_PKG_TIMEOUT:
            await asyncio.to_thread(auth.update_schedule, s["id"], state="error", finished=now,
                                    result="esito dell'installazione non disponibile")
            await asyncio.to_thread(sched_cancel_children, s, "non eseguito: l'aggiornamento della VM non è riuscito")
            await asyncio.to_thread(sched_drop_package, s)
        return
    await asyncio.to_thread(sched_drop_package, s)
    if st["state"] == "ok" and st.get("version") == pkg.get("version"):
        result = f"installata la versione {pkg.get('version')}"
        await asyncio.to_thread(auth.update_schedule, s["id"], state="done", result=result, finished=now)
        # avviso: dopo questa installazione le sonde vanno aggiornate oppure no
        body = ""
        if "probes_changed" in pkg:
            behind = await asyncio.to_thread(probes_behind)
            body = probes_need_text(pkg["probes_changed"], behind) + " " + PROBES_AFTER.get(pkg.get("probes_after"), "")
        await asyncio.to_thread(add_event if sched_now(s) or s.get("batch") else admin_notice,
                                f"[OK] Aggiornamento di netmon della VM: {result}", body)
        log.warning("Aggiornamento programmato %d: %s", s["id"], result)
        return
    await asyncio.to_thread(auth.update_schedule, s["id"], state="error", finished=now,
                            result="installazione non riuscita, rimasta la versione precedente: "
                                   "vedi il registro nella scheda Server")
    await asyncio.to_thread(add_event, "[ALERT] Aggiornamento di netmon della VM non riuscito",
                            f"rimasta la versione {VERSION}", False)
    await asyncio.to_thread(sched_cancel_children, s, "non eseguito: l'aggiornamento della VM non è riuscito")
    await _admin_mail_all("netmon: aggiornamento di netmon della VM non riuscito",
                          f"L'installazione di netmon {pkg.get('version')} non è riuscita: la VM è rimasta alla "
                          f"versione {VERSION}.\n\nIl registro è nella pagina /admin, scheda Server."
                          + ("\n\nL'aggiornamento delle sonde che doveva seguire è stato annullato."
                             if s.get("id") else ""), s)


# ------------------------------------------------------------------ campagne del pannello
# Un aggiornamento lanciato dal pannello tocca più programmazioni: il server e le sue
# sonde. Prima ognuna mandava le sue email agli amministratori (creazione, promemoria, esito della
# VM, una per ogni sonda non riuscita): con molte sonde, centinaia di email. Ora hanno tutte lo
# stesso codice di campagna e nessuna avvisa gli amministratori da sola: il server manda UN riepilogo alla programmazione, UNO
# un'ora prima e UNO con l'esito di tutto. Gli utenti ricevono gli avvisi di sempre.
SCHED_BATCH_KEY = "sched_batches"
BATCH_PATTERN = r"^[0-9a-f]{16}$"
SCHED_BATCH_TIMEOUT = 4 * 3600          # dopo, l'esito si manda comunque (sonde spente restano «in attesa»)


def sched_batch_local(bid):
    """Le programmazioni di questa macchina in una campagna, con l'esito sonda per sonda."""
    out = []
    for s in auth.schedules_of_batch(bid):
        item = {"target": s["target"], "cmd": s["cmd"], "what": sched_public(s)["what"], "state": s["state"],
                "result": s["result"], "at": s["at"], "version": sched_version(s) or None}
        if s["target"] == "probes":
            keys = sched_keys(s)
            st = {"total": len(keys), "chosen": s["probes"] is not None, "done": [], "error": [], "waiting": []}
            started = s["state"] not in ("pending", "running")
            for k in keys:
                c = (monitor.state.get(k) or {}).get("command") or {}
                if not started or c.get("schedule") != s["id"]:
                    continue                          # non ancora partito, oppure saltata (già aggiornata, …)
                owner = auth.get_user(registry.owner_of(k)) or {}
                name = label_of(k, monitor.state[k]) + (f" ({owner['email']})" if owner.get("email") else "")
                st["done" if c.get("state") == "done" else "error" if c.get("state") == "error" else "waiting"].append(name)
            item["probes"] = st
        out.append(item)
    return out


def sched_batch_collect(bid):
    """{"server": elenco delle programmazioni della campagna}, vuoto se non ce ne sono."""
    items = sched_batch_local(bid)
    return {"server": items} if items else {}


def _batches():
    try:
        v = json.loads(auth.get_setting(SCHED_BATCH_KEY) or "[]")
    except ValueError:
        v = []
    return [b for b in v if isinstance(b, dict) and b.get("id")]


def _batches_save(lst):
    now = time.time()
    keep = [b for b in lst if not b.get("done") or now - b.get("at", now) < 30 * 86400]   # un mese di storia
    auth.set_setting(SCHED_BATCH_KEY, json.dumps(keep[-200:]))


_batch_lock = threading.Lock()


def sched_batch_register(bid, at, by):
    with _batch_lock:
        lst = _batches()
        if not any(b["id"] == bid for b in lst):
            now = time.time()
            lst.append({"id": bid, "at": max(at or now, now), "created": now, "by": by, "now": at is None or at - now < 90,
                        "reminded": False, "done": False, "last": 0})
            _batches_save(lst)


def _batch_update(bid, **kw):
    with _batch_lock:
        lst = _batches()
        for b in lst:
            if b["id"] == bid:
                b.update(kw)
        _batches_save(lst)


def sched_batch_text(b, data, kind):
    """(titolo, testo, problemi) del riepilogo: kind created | reminder | result."""
    when = "adesso" if b.get("now") else "il " + local_time(b["at"], "%d/%m/%Y alle %H:%M")
    righe, problemi, versioni = [], 0, set()
    for vm in sorted(data):
        items = data[vm]
        righe.append(f"{vm}:")
        if items is None:
            righe.append("  • non risponde: esito sconosciuto, controlla nel pannello")
            problemi += 1
            continue
        for it in items:
            if it.get("version"):
                versioni.add(it["version"])
            if it["target"] == "probes":
                pr = it.get("probes") or {}
                n = pr.get("total", 0)
                chi = (f"{n} {'sonda scelta' if n == 1 else 'sonde scelte'}" if pr.get("chosen")
                       else f"tutte le sonde della VM ({n})")
                riga = f"  • {it['what']}: {chi}"
                if kind == "result":
                    if it["state"] == "cancelled":
                        riga += f" — {it['result'] or 'annullato'}"
                    else:
                        nd, ne = len(pr.get("done", [])), len(pr.get("error", []))
                        parti = [f"{nd} {'aggiornata' if nd == 1 else 'aggiornate'}"]
                        if pr.get("error"):
                            parti.append(f"{ne} {'non riuscita' if ne == 1 else 'non riuscite'}: " + ", ".join(pr["error"][:30])
                                         + (" …" if len(pr["error"]) > 30 else ""))
                            problemi += len(pr["error"])
                        if pr.get("waiting"):
                            parti.append(f"{len(pr['waiting'])} in attesa (spente o non collegate): "
                                         + ", ".join(pr["waiting"][:30]) + (" …" if len(pr["waiting"]) > 30 else ""))
                        riga += " — " + "; ".join(parti)
                        res = it.get("result") or ""
                        if any(w in res for w in ("già", "saltate", "altra operazione")):
                            riga += f" ({res})"           # sonde non toccate: già aggiornate, spente dall'utente…
            else:
                riga = f"  • {it['what']}"
                if kind == "result":
                    riga += f" — {it['result'] or it['state']}"
                    if it["state"] in ("error", "cancelled"):
                        problemi += 1
            righe.append(riga)
    if versioni:
        righe.insert(0, f"Versione: {', '.join(sorted(versioni))}")
        righe.insert(1, "")
    if kind == "created":
        title = f"[PROGRAMMATO] Aggiornamento di netmon {when}"
        head = f"Aggiornamento programmato {when} da {b.get('by') or 'un amministratore'}. Verrà aggiornato:"
        tail = ("Le sonde si aggiornano dopo la loro VM, solo se la VM si è aggiornata bene. Gli utenti ricevono il "
                "loro avviso di manutenzione. Se non te lo aspettavi, annulla dal pannello /admin, scheda Server.")
    elif kind == "reminder":
        title = "[TRA UN'ORA] Aggiornamento di netmon"
        head = f"Promemoria: l'aggiornamento parte tra circa un'ora ({local_time(b['at'], '%H:%M del %d/%m/%Y')}). Verrà aggiornato:"
        tail = "Per annullarlo: pannello /admin, scheda Server."
    else:
        title = ("[ALERT] Aggiornamento di netmon: 1 problema" if problemi == 1
                 else f"[ALERT] Aggiornamento di netmon: {problemi} problemi" if problemi
                 else "[OK] Aggiornamento di netmon completato")
        head = f"Esito dell'aggiornamento partito {when} (programmato da {b.get('by') or 'un amministratore'}):"
        tail = "I registri sono nel pannello /admin, schede Server e Sonde."
    return title, head + "\n\n" + "\n".join(righe) + "\n\n" + tail, problemi


def sched_batch_announce(bid):
    """Riepilogo alla programmazione (solo se non è «adesso»: quelle partono in silenzio come sempre)."""
    b = next((x for x in _batches() if x["id"] == bid), None)
    if b is None or b.get("now"):
        return
    data = sched_batch_collect(bid)
    if not data:
        return
    title, body, _ = sched_batch_text(b, data, "created")
    admin_notice(title, body)


def sched_batch_tick():
    """Dal watchdog: promemoria un'ora prima ed esito finale delle campagne aperte."""
    now = time.time()
    for b in _batches():
        if b.get("done") or now - b.get("last", 0) < 120:
            continue
        if not b.get("reminded") and b["at"] > now and b["at"] - now <= 3600 and b["at"] - b["created"] > 3600:
            data = sched_batch_collect(b["id"])
            _batch_update(b["id"], reminded=True, last=now)
            if data:
                title, body, _ = sched_batch_text(b, data, "reminder")
                admin_notice(title, body)
            continue
        if now < b["at"] + 60:
            continue
        data = sched_batch_collect(b["id"])
        _batch_update(b["id"], last=now)
        if not data:                                   # niente programmato (tutto annullato o rifiutato)
            _batch_update(b["id"], done=True)
            continue
        finito = all(items is not None and all(
            it["state"] in ("done", "error", "cancelled") and not (it.get("probes") or {}).get("waiting")
            for it in items) for items in data.values())
        if not finito and now - b["at"] < SCHED_BATCH_TIMEOUT:
            continue
        title, body, problemi = sched_batch_text(b, data, "result")
        _batch_update(b["id"], done=True)
        if b.get("now") and not problemi:              # «adesso» senza problemi: solo nel registro, come sempre
            add_event(title, body[:2000])
        else:
            admin_notice(title, body, not problemi)


class BatchRef(BaseModel):
    id: str = Field(pattern=BATCH_PATTERN)
    at: Optional[float] = None


@app.post("/api/admin/schedules/batch")
async def api_sched_batch(b: BatchRef, adm: dict = Depends(admin_user)):
    """Apre una campagna: le programmazioni con questo codice non avvisano gli admin una per una."""
    await asyncio.to_thread(sched_batch_register, b.id, b.at, adm.get("name") or adm["login"])
    return {"ok": True}


@app.post("/api/admin/schedules/batch/announce")
async def api_sched_batch_announce(b: BatchRef, adm: dict = Depends(admin_user)):
    """Programmazioni create: un solo riepilogo agli amministratori."""
    await asyncio.to_thread(sched_batch_announce, b.id)
    return {"ok": True}


def sched_public(s):
    """Programmazione per la pagina: con i nomi delle sonde."""
    names = None
    if s["probes"] is not None:
        names = [label_of(k, monitor.state[k]) if k in monitor.state else (registry.name_of(k) or k) for k in s["probes"]]
    what = SCHED_WHAT[s["cmd"]]
    if sched_version(s):
        what += f" {sched_version(s)}" if s["cmd"] == "package" else f" (alla {sched_version(s)})"
    if s.get("after_id"):
        what += ", dopo la VM"
    return {**{k: v for k, v in s.items() if k != "package"}, "names": names, "what": what,
            "version": sched_version(s) or None}


class ScheduleNew(BaseModel):
    target: Literal["vm", "probes"]
    cmd: Literal["upgrade", "update", "reboot"]
    probes: Optional[list[str]] = Field(default=None, max_length=1000)   # None = tutte
    at: Optional[float] = None                                          # None = adesso
    password: str = Field(max_length=256)
    batch: Optional[str] = Field(default=None, pattern=BATCH_PATTERN)    # campagna: un solo riepilogo agli admin


class PackageSchedule(BaseModel):
    at: Optional[float] = None                                          # None = adesso
    batch: Optional[str] = Field(default=None, pattern=BATCH_PATTERN)    # campagna: un solo riepilogo agli admin
    probes_mode: Literal["none", "all", "some"] = "none"                # sonde da aggiornare dopo la VM
    probes: Optional[list[str]] = Field(default=None, max_length=1000)
    password: str = Field(max_length=256)


class ScheduleRef(BaseModel):
    id: int


@app.get("/api/admin/probes")
async def api_admin_probes(adm: dict = Depends(admin_user)):
    """Tutte le sonde collegate a un account, con stato, versione e operazione in corso."""
    def collect():
        owned = registry.owned_keys()
        pause_sonde = registry.pauses_for(owned, time.time())[0] if owned else {}
        pending = [s for s in auth.schedules_in("pending") if s["target"] == "probes"]
        emails = {}
        now = time.time()
        out = []
        auto_off = auth.probe_auto_off()
        for k, p in monitor.state.items():
            if k not in owned:
                continue
            owner = registry.owner_of(k)
            if owner not in emails:
                u = auth.get_user(owner)
                emails[owner] = u["email"] if u else ""
            silence = now - p["last_seen"]
            # «In pausa» e' uno stato a se': spiega perche' una sonda muta non ha fatto scattare
            # nessun avviso, che altrimenti sembrerebbe un guasto del monitoraggio.
            pausa = pause_sonde.get(k)
            state = ("paused" if pausa else "offline" if p["offline"]
                     else "late" if silence > monitor.stale_after(p) else "online")
            c = p.get("command") or {}
            out.append({"key": k, "name": label_of(k, p), "owner": emails[owner], "state": state,
                        "paused_until": fmt_when(pausa["until"]) if pausa and pausa["until"] else None,
                        "paused_note": pausa["note"] if pausa else "",
                        "last_seen": p["last_seen"], "version": (p.get("system") or {}).get("version"),
                        "auto_update": owner not in auto_off,
                        "full_update": (p.get("system") or {}).get("full_update"),
                        "managed_by": (p.get("system") or {}).get("managed_by"),
                        "model": (p.get("system") or {}).get("model"), "devices": len(p.get("devices") or {}),
                        "command": {x: c.get(x) for x in ("cmd", "state", "requested", "finished", "by",
                                                         "reboot_required", "output")} if c else None,
                        "scheduled": next(({"what": sched_public(s)["what"], "at": s["at"]} for s in pending
                                           if s["probes"] is None or k in s["probes"]), None)})
        out.sort(key=lambda x: (x["owner"], x["name"].lower()))
        return out, [sched_public(s) for s in auth.list_schedules()]
    probes, schedules = await asyncio.to_thread(collect)
    return {"probes": probes, "schedules": schedules, "dist_version": await asyncio.to_thread(probe_dist_version),
            "dist_same": await asyncio.to_thread(probe_dist_same)}


def sched_check_at(at_in):
    now = time.time()
    at = now if at_in is None else float(at_in)
    if at < now - 120:
        raise HTTPException(status_code=422, detail="La data e l'ora scelte sono già passate.")
    if at > now + SCHED_MAX_DAYS * 86400:
        raise HTTPException(status_code=422, detail=f"Si può programmare al massimo {SCHED_MAX_DAYS} giorni avanti.")
    return max(at, now)


async def sched_check_vm_free():
    if any(s["target"] == "vm" for s in await asyncio.to_thread(auth.schedules_in, "pending", "running")):
        raise HTTPException(status_code=409, detail="C'è già un aggiornamento della VM programmato: annullalo prima.")


async def sched_pick_probes(selected):
    """None = tutte (se ce n'è almeno una), altrimenti le sonde indicate che esistono e hanno un account."""
    owned = await asyncio.to_thread(registry.owned_keys)
    if selected is not None:
        probes = [k for k in dict.fromkeys(selected) if k in owned and k in monitor.state]
        if not probes:
            raise HTTPException(status_code=422, detail="Seleziona almeno una sonda.")
        return probes
    if not any(k in owned for k in monitor.state):
        raise HTTPException(status_code=422, detail="Nessuna sonda collegata a cui inviarlo.")
    return None


@app.post("/api/admin/schedules")
async def api_schedule_new(b: ScheduleNew, request: Request, adm: dict = Depends(admin_user)):
    await check_admin_pw(adm, b.password, request)
    now = time.time()
    at = sched_check_at(b.at)
    probes = None
    if b.target == "vm":
        if b.cmd not in ("upgrade", "reboot"):
            raise HTTPException(status_code=422,
                                detail="Sulla VM si programma qui l'aggiornamento del sistema o il riavvio.")
        await sched_check_vm_free()
        needed = "can_reboot" if b.cmd == "reboot" else "can_upgrade"
        if not (await asyncio.to_thread(vmops.permissions)).get(needed):
            raise HTTPException(status_code=409, detail="Permessi non configurati: aggiorna il server con installa-server.sh --aggiorna.")
    else:
        if b.cmd == "reboot":
            raise HTTPException(status_code=422, detail="Il riavvio delle sonde non si programma da qui.")
        probes = await sched_pick_probes(b.probes)
        if b.cmd == "update" and not await asyncio.to_thread(probe_dist_version):
            raise HTTPException(status_code=409, detail="Sul server mancano i programmi della sonda: "
                                                        "aggiorna il server con installa-server.sh --aggiorna.")
    who = adm.get("name") or adm["login"]
    sid = await asyncio.to_thread(auth.add_schedule, b.target, b.cmd, probes, at, who, None, None, b.batch)
    s = await asyncio.to_thread(auth.get_schedule, sid)
    log.warning("Aggiornamento programmato da %s: %s %s %s", adm["login"], b.target, b.cmd, sched_when(s))
    await asyncio.to_thread(sched_announce, s, "created")
    if at - now < 90:
        await run_schedules()                           # adesso: parte subito, senza aspettare il watchdog
    return {"ok": True, "schedule": sched_public(await asyncio.to_thread(auth.get_schedule, sid))}


@app.post("/api/admin/schedules/cancel")
async def api_schedule_cancel(b: ScheduleRef, adm: dict = Depends(admin_user)):
    s = await asyncio.to_thread(auth.get_schedule, b.id)
    if s is None or s["state"] != "pending":
        raise HTTPException(status_code=409, detail="Si può annullare solo un aggiornamento non ancora partito.")
    who = adm.get("name") or adm["login"]
    await asyncio.to_thread(auth.update_schedule, s["id"], state="cancelled", result=f"annullato da {who}",
                            finished=time.time())
    log.warning("Aggiornamento programmato %d annullato da %s", s["id"], adm["login"])
    await asyncio.to_thread(sched_announce, s, "cancelled", who)
    await asyncio.to_thread(sched_cancel_children, s, f"annullato da {who} insieme all'aggiornamento della VM", who)
    await asyncio.to_thread(sched_drop_package, s)
    return {"ok": True}


# ------------------------------------------------------------------ aggiornamento di netmon da pacchetto (zip)
# Solo dal pannello di amministrazione. L'amministratore carica netmon.zip: il server lo controlla
# subito con il verificatore (lo stesso che userà root) e lo tiene da parte; poi sceglie quando
# installarlo (adesso o a una data e ora) e se, dopo la VM, aggiornare anche le sonde (nessuna,
# alcune o tutte). All'ora stabilita il pacchetto viene ricontrollato e installato da
# /usr/local/sbin/netmon-vm-selfupdate (root), che ricontrolla tutto su una copia privata.
# L'installazione rifà il pacchetto completo per le sonde, firmato da root (netmon-firma-sonde).
# Ogni pacchetto va caricato con la FIRMA DELL'AUTORE (file .sig fatto sul Mac con «Firma NetMon»,
# tools/mac): root la verifica con la chiave pubblica di rilascio prima di installare. Qui la si
# controlla solo per mostrare subito l'esito nel pannello: il servizio non è mai considerato affidabile.
import pkgcheck  # noqa: E402

UPLOAD_DIR = DATA_DIR / "upload"
STAGED_ZIP = UPLOAD_DIR / "netmon.zip"                 # quello che legge netmon-vm-selfupdate
UPLOADED_ZIP = UPLOAD_DIR / "caricato.zip"             # caricato, non ancora programmato
STAGED_MINUTES = 60                                    # un pacchetto caricato vale un'ora
_staged = {}                                           # dati del pacchetto in attesa di programmazione


RELEASE_KEY = Path("/usr/local/share/netmon/release-key.pub")   # di root, installata da installa-server.sh
SIG_MAX = 512                                          # una firma ECDSA P-256 (DER) è di circa 72 byte


def sig_of(path: Path) -> Path:
    """File della firma dell'autore accanto a un pacchetto (netmon.zip -> netmon.zip.sig)."""
    return path.with_name(path.name + ".sig")


def key_fingerprint(pem: bytes) -> str:
    """Impronta di una chiave pubblica: SHA-256 della forma DER, prime 16 cifre a gruppi di 4 (come
    installa-server.sh, netmon-vm-selfupdate e «Firma NetMon» sul Mac)."""
    body = b"".join(l for l in pem.strip().splitlines() if not l.startswith(b"-----"))
    h = hashlib.sha256(base64.b64decode(body)).hexdigest()[:16]
    return " ".join(h[i:i + 4] for i in range(0, 16, 4))


def release_key_info() -> dict:
    """Chiave di rilascio installata sulla VM (per il pannello)."""
    try:
        return {"release_key": key_fingerprint(RELEASE_KEY.read_bytes())}
    except (OSError, ValueError):
        return {"release_key": None}


def signature_check(path: Path, sig: bytes | None):
    """(esito, testo) della firma dell'autore sul pacchetto: con la chiave installata, oppure, se la
    VM non ne ha ancora una, con quella contenuta nel pacchetto (prima chiave)."""
    import subprocess
    import zipfile
    if not sig:
        return False, "Manca la firma dell'autore: seleziona insieme al pacchetto il suo file .sig (fatto con «Firma NetMon»)"
    try:
        key = RELEASE_KEY.read_bytes()
        first = False
    except OSError:
        try:
            with zipfile.ZipFile(path) as zf:
                info = zf.getinfo("netmon/server/release-key.pub")
                key = zf.read(info) if info.file_size <= 4096 else b""
        except (KeyError, OSError, zipfile.BadZipFile):
            key = b""
        if not key:
            return False, ("La VM non ha ancora la chiave di rilascio e il pacchetto non la contiene: firmalo con "
                           "«Firma NetMon» (la versione aggiornata dell'app la aggiunge da sola) e ricaricalo insieme al nuovo .sig")
        first = True
    with tempfile.TemporaryDirectory(dir=UPLOAD_DIR) as tmp:
        kf, sf = Path(tmp) / "key.pub", Path(tmp) / "zip.sig"
        kf.write_bytes(key)
        sf.write_bytes(sig)
        try:
            r = subprocess.run(["openssl", "dgst", "-sha256", "-verify", str(kf), "-signature", str(sf), str(path)],
                               capture_output=True, timeout=30)
            ok = r.returncode == 0
        except (OSError, subprocess.TimeoutExpired):
            return False, "Firma dell'autore non verificabile (openssl non risponde)"
    try:
        fp = key_fingerprint(key)
    except ValueError:
        return False, "Chiave di rilascio non valida"
    if not ok:
        return False, f"Firma dell'autore NON valida per la chiave {fp}: pacchetto rifiutato"
    if first:
        return True, f"Firma dell'autore valida. Prima chiave di rilascio di questa VM: {fp} (controlla che sia la tua)"
    return True, f"Firma dell'autore verificata (chiave {fp})"


def package_check(path, sig: bytes | None = None):
    good, version, checks, errors, zf = pkgcheck.check(str(path), "server", VERSION)
    if zf is not None:
        zf.close()
    if zf is not None and version:
        signed, text = signature_check(Path(path), sig)
        checks.insert(0, ["ok" if signed else "bad", text])
        if not signed:
            errors.insert(0, text)
            good = False
    return {"ok": good, "version": version, "installed": VERSION, "checks": checks, "errors": errors}


def read_sig(path: Path) -> bytes | None:
    try:
        data = sig_of(path).read_bytes()
    except OSError:
        return None
    return data if 0 < len(data) <= SIG_MAX else None


def staged_info():
    """Pacchetto caricato e in attesa di essere programmato, se c'è e non è scaduto."""
    if not _staged or not UPLOADED_ZIP.exists():
        return None
    if time.time() - _staged["ts"] > STAGED_MINUTES * 60:
        UPLOADED_ZIP.unlink(missing_ok=True)
        sig_of(UPLOADED_ZIP).unlink(missing_ok=True)
        _staged.clear()
        return None
    return {**{k: _staged[k] for k in ("version", "sha256", "ts", "by", "size")},
            "probes_changed": _staged.get("probes_changed")}


@app.post("/api/admin/package")
async def api_package_upload(request: Request, adm: dict = Depends(admin_user)):
    """Riceve netmon.zip (corpo della richiesta, application/zip) con la firma dell'autore
    (intestazione X-Netmon-Signature: il contenuto del file .sig, in base64) e lo verifica. Non installa nulla."""
    if request.headers.get("content-type", "").split(";")[0].strip() != "application/zip":
        raise HTTPException(status_code=415, detail="Carica un file .zip.")
    raw_sig = request.headers.get("x-netmon-signature", "").strip()
    sig = None
    if raw_sig:
        try:
            sig = base64.b64decode(raw_sig, validate=True) if len(raw_sig) <= 2 * SIG_MAX else b""
        except ValueError:
            sig = b""
        if not 0 < len(sig) <= SIG_MAX:
            raise HTTPException(status_code=422, detail="Il file .sig non è una firma di «Firma NetMon».")
    data = await request.body()
    if not data:
        raise HTTPException(status_code=422, detail="File vuoto.")
    if len(data) > pkgcheck.MAX_ZIP:
        raise HTTPException(status_code=413, detail="File troppo grande per essere un pacchetto netmon.")

    def store():
        UPLOAD_DIR.mkdir(mode=0o700, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=UPLOAD_DIR, prefix=".caricato-", suffix=".zip")
        try:
            with os.fdopen(fd, "wb") as f:
                f.write(data)
            report = package_check(tmp, sig)
            if report["ok"]:
                # le sonde vanno aggiornate dopo la VM? (file della sonda a confronto, senza la versione)
                changed = pkgcheck.probe_update_info(str(PROBE_DIST), tmp)["changed"]
                behind = probes_behind()
                report["probes"] = {"changed": changed, "behind": behind}
                report["checks"].append(["info" if changed is None else "warn" if changed else "ok",
                                         probes_need_text(changed, behind)])
                sig_of(UPLOADED_ZIP).write_bytes(sig)
                os.replace(tmp, UPLOADED_ZIP)
                _staged.clear()
                _staged.update(version=report["version"], sha256=hashlib.sha256(data).hexdigest(),
                               ts=time.time(), by=adm.get("name") or adm["login"], size=len(data),
                               probes_changed=changed)
            return report
        finally:
            if os.path.exists(tmp):
                os.unlink(tmp)
    report = await asyncio.to_thread(store)
    # rifiutato solo perché il server ha già quella versione (o una più recente)
    report["up_to_date"] = bool(not report["ok"] and report.get("version") and len(report["errors"]) == 1
                                and pkgcheck.version_key(report["version"]) <= pkgcheck.version_key(VERSION))
    log.warning("Pacchetto caricato da %s: %s (%s)", adm["login"], report.get("version") or "?",
                "idoneo" if report["ok"] else "rifiutato: " + "; ".join(report["errors"]))
    return {**report, "staged": staged_info()}


@app.post("/api/admin/package/schedule")
async def api_package_schedule(b: PackageSchedule, request: Request, adm: dict = Depends(admin_user)):
    """Programma l'installazione del pacchetto caricato (adesso o a una data e ora) e, se scelto,
    l'aggiornamento delle sonde subito dopo."""
    await check_admin_pw(adm, b.password, request)
    now = time.time()
    at = sched_check_at(b.at)
    info = staged_info()
    if not info:
        raise HTTPException(status_code=409, detail="Nessun pacchetto in attesa (o caricato da più di un'ora): caricalo di nuovo.")
    await sched_check_vm_free()
    if not (await asyncio.to_thread(vmops.permissions)).get("can_selfupdate"):
        raise HTTPException(status_code=409, detail="Funzione non ancora installata: aggiorna il server una volta a mano "
                                                    "con sudo bash installa-server.sh --aggiorna.")
    # sonde da aggiornare dopo la VM: se non ce ne sono (VM senza sonde collegate) la VM si
    # aggiorna lo stesso, con un avviso; non è un motivo per non installare il pacchetto
    probes, probes_mode, warning = None, b.probes_mode, None
    if probes_mode != "none":
        try:
            probes = await sched_pick_probes((b.probes or []) if probes_mode == "some" else None)
        except HTTPException as e:
            if e.status_code != 422:
                raise
            probes, probes_mode = None, "none"
            warning = "Nessuna sonda da aggiornare su questa VM: si aggiorna solo la VM."

    def keep():
        sig = read_sig(UPLOADED_ZIP)
        report = package_check(UPLOADED_ZIP, sig)      # di nuovo, prima di tenerlo per la programmazione
        if not report["ok"] or report["version"] != info["version"]:
            return None, report
        name = f"pkg-{info['sha256'][:16]}.zip"
        os.replace(sig_of(UPLOADED_ZIP), sig_of(UPLOAD_DIR / name))
        os.replace(UPLOADED_ZIP, UPLOAD_DIR / name)
        _staged.clear()
        return name, report
    name, report = await asyncio.to_thread(keep)
    if not name:
        raise HTTPException(status_code=409, detail="Il pacchetto non è più idoneo: " + "; ".join(report["errors"]))
    who = adm.get("name") or adm["login"]
    pkg = {"version": info["version"], "sha256": info["sha256"], "file": name, "size": info["size"], "by": info["by"],
           "probes_changed": info["probes_changed"], "probes_after": probes_mode}
    sid = await asyncio.to_thread(auth.add_schedule, "vm", "package", None, at, who, pkg, None, b.batch)
    s = await asyncio.to_thread(auth.get_schedule, sid)
    log.warning("Installazione di netmon %s da pacchetto programmata da %s %s", info["version"], adm["login"], sched_when(s))
    await asyncio.to_thread(sched_announce, s, "created")
    child = None
    if probes_mode != "none":
        cid = await asyncio.to_thread(auth.add_schedule, "probes", "update", probes, at, who,
                                      {"version": info["version"]}, sid, b.batch)
        child = await asyncio.to_thread(auth.get_schedule, cid)
        await asyncio.to_thread(sched_announce, child, "created")
    if at - now < 90:
        await run_schedules()                           # adesso: parte subito
    return {"ok": True, "version": info["version"], "warning": warning,
            "schedule": sched_public(await asyncio.to_thread(auth.get_schedule, sid)),
            "probes_schedule": sched_public(child) if child else None}


@app.post("/api/admin/package/discard")
async def api_package_discard(adm: dict = Depends(admin_user)):
    UPLOADED_ZIP.unlink(missing_ok=True)
    sig_of(UPLOADED_ZIP).unlink(missing_ok=True)
    _staged.clear()
    return {"ok": True}


# ------------------------------------------------------------------ scheda Server (solo amministratori)
def admin_events():
    """Registro amministrativo: eventi non legati a una sonda (VM, aggiornamenti, errori, account).
    Durano ADMIN_EVENTS_DAYS giorni (un anno se non indicato); la pagina li mostra a pagine."""
    with db() as conn:
        rows = conn.execute("SELECT ts, title, body, recovery FROM events WHERE probe IS NULL "
                            "ORDER BY ts DESC").fetchall()
    return [{"ts": r[0], "title": r[1], "body": r[2] or "", "ok": bool(r[3])} for r in rows]



@app.get("/api/admin/vm")
async def api_admin_vm(request: Request, check: int = 0, adm: dict = Depends(admin_user)):
    """Stato della VM, aggiornamenti disponibili e ultime operazioni."""
    if check:
        vmops.forget_pending_updates()
    host = (urlsplit(public_base(request)).hostname or "")
    info = await asyncio.to_thread(vmops.info, DATA_DIR, host)
    st = await asyncio.to_thread(vmops.upgrade_status)
    perms = await asyncio.to_thread(vmops.permissions)
    last = await asyncio.to_thread(auth.get_setting, "vm_last_reboot")
    owned = await asyncio.to_thread(registry.owned_keys)
    return {"vm": info, "upgrade": st, "log": vmops.upgrade_log(6000) if st.get("state") != "none" else "",
            "last_reboot": json.loads(last) if last else None, "server_version": VERSION,
            # solo le sonde collegate a un account (come la colonna "Sonde" degli utenti)
            "probes_total": sum(1 for k in monitor.state if k in owned),
            "probes_online": sum(1 for k, p in monitor.state.items() if k in owned and not p.get("offline")),
            # della VM, più gli aggiornamenti delle sonde che partono dopo la VM
            "schedules": [sched_public(s) for s in await asyncio.to_thread(auth.list_schedules)
                          if s["target"] == "vm" or s.get("after_id")],
            # sonde tra cui scegliere quelle da aggiornare dopo il pacchetto
            "probe_choices": sorted(({"key": k, "name": label_of(k, p), "version": (p.get("system") or {}).get("version"),
                                      "offline": bool(p.get("offline"))}
                                     for k, p in monitor.state.items() if k in owned), key=lambda x: x["name"].lower()),
            "selfupdate": await asyncio.to_thread(vmops.selfupdate_status),
            "self_log": await asyncio.to_thread(vmops.selfupdate_log),
            "rollback": await asyncio.to_thread(vmops.rollback_status),
            "events": await asyncio.to_thread(admin_events),
            "staged": staged_info(),
            **release_key_info(),
            **perms}


