@app.post("/api/admin/vm/reboot")
async def api_admin_vm_reboot(b: RotateBody, request: Request, adm: dict = Depends(admin_user)):
    await check_admin_pw(adm, b.password, request)
    if (await asyncio.to_thread(vmops.upgrade_status)).get("state") == "running":
        raise HTTPException(status_code=409, detail="Aggiornamento dei pacchetti in corso: attendi che finisca.")
    _state_dirty[0] = True
    await asyncio.to_thread(flush_state)                 # stato delle sonde salvato prima del riavvio
    # 15 secondi: il tempo di rispondere alla pagina
    ok, message = await asyncio.to_thread(vmops.reboot, 15)
    log.warning("Riavvio della VM richiesto da %s: %s", adm["login"], message)
    if not ok:
        raise HTTPException(status_code=409, detail=message)
    who = adm.get("name") or adm["login"]
    # riavvio immediato: nessuna notifica (né agli utenti né agli amministratori), solo il registro
    await asyncio.to_thread(add_event, f"[INFO] Riavvio della VM richiesto da {who}")
    await asyncio.to_thread(auth.set_setting, "vm_last_reboot",
                            json.dumps({"ts": time.time(), "by": adm.get("name") or adm["login"]}))
    return {"ok": True, "message": message}


@app.post("/api/admin/vm/rollback/commit")
async def api_admin_vm_rollback_commit(adm: dict = Depends(admin_user)):
    """Conferma la versione nuova dopo un'installazione da pacchetto: la finestra di rollback si
    chiude e la copia della versione precedente viene tolta."""
