@app.post("/api/admin/vm/rollback")
async def api_admin_vm_rollback(adm: dict = Depends(admin_user)):
    """Torna subito alla versione precedente all'ultima installazione (in un'unità systemd
    separata: il server si riavvia, la richiesta risponde prima)."""
    ok, message = await asyncio.to_thread(vmops.rollback_now)
    log.warning("Rollback richiesto da %s: %s", adm["login"], message)
    if not ok:
        raise HTTPException(status_code=409, detail=message)
    who = adm.get("name") or adm["login"]
    await asyncio.to_thread(admin_notice, f"[INFO] Rollback richiesto da {who}",
                            f"{who} ha ripristinato la versione precedente all'ultima installazione.")
    return {"ok": True, "message": message}


ADMIN_LANG_COOKIE = "netmon_admin_lang"


@app.get("/admin", response_class=HTMLResponse)
async def admin_page(request: Request):
    lang = i18n.pick(None, request.cookies.get(ADMIN_LANG_COOKIE), request.headers.get("accept-language"))
    page, etag = ADMIN_PAGES[lang]
    headers = {"Cache-Control": "no-cache", "ETag": etag, "Referrer-Policy": "no-referrer",
               "X-Robots-Tag": "noindex", "Vary": "Cookie, Accept-Language"}
    if request.headers.get("if-none-match") == etag:
        return Response(status_code=304, headers=headers)
    return HTMLResponse(page, headers=headers)


