# ------------------------------------------------------------------ robots.txt e sitemap.xml (pubblici)
# Solo le pagine pubbliche: il sito di presentazione, la dashboard (che senza accesso mostra il login)
# e l'informativa.
# Pannello e API esclusi.
HOST_OK = re.compile(r"[A-Za-z0-9.-]{1,253}(:[0-9]{1,5})?")


def site_base(request: Request) -> str:
    host = request.headers.get("host", "")
    if HOST_OK.fullmatch(host):
        return "https://" + host
    return os.getenv("PUBLIC_URL", "").strip().rstrip("/")


@app.api_route("/robots.txt", methods=["GET", "HEAD"])
async def robots_txt(request: Request):
    base = site_base(request)
    body = ("User-agent: *\nAllow: /$\nAllow: /en/\nAllow: /de/\nAllow: /fr/\nAllow: /dashboard\nAllow: /privacy\n"
            "Disallow: /admin\nDisallow: /api/\n"
            + (f"Sitemap: {base}/sitemap.xml\n" if base else ""))
    return Response(body, media_type="text/plain", headers={"Cache-Control": "public, max-age=3600"})


@app.api_route("/sitemap.xml", methods=["GET", "HEAD"])
async def sitemap_xml(request: Request):
    base = site_base(request)
    if not base:
        raise HTTPException(404)
    # le quattro lingue del sito, ognuna con gli indirizzi delle altre (hreflang), poi dashboard e informativa
    alt = "".join(f'<xhtml:link rel="alternate" hreflang="{lang}" href="{base}{path}"/>'
                  for path, lang in SITO_PATHS.items() if lang in SITO_PAGES)
    urls = "".join(f"  <url><loc>{base}{path}</loc>{alt}</url>\n" for path, lang in SITO_PATHS.items()
                   if lang in SITO_PAGES)
    urls += "".join(f"  <url><loc>{base}{p}</loc></url>\n" for p in ("/dashboard", "/privacy"))
    body = ('<?xml version="1.0" encoding="UTF-8"?>\n'
            '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n'
            + urls + "</urlset>\n")
    return Response(body, media_type="application/xml", headers={"Cache-Control": "public, max-age=3600"})


@app.api_route("/privacy", methods=["GET", "HEAD"])
async def privacy_page(request: Request):
    """Informativa sulla privacy (quattro lingue nello stesso file), linkata in fondo a ogni pagina."""
    body = None
    for f in PRIVACY_FILES:
        try:
            body = await asyncio.to_thread(f.read_bytes)
            break
        except OSError:
            continue
    if body is None:
        raise HTTPException(status_code=404, detail="Informativa non pubblicata.")
    user = await asyncio.to_thread(auth.session_user, request.cookies.get(COOKIE))
    # durata dello storico sempre aggiornata: quella scelta dall'utente collegato, o quella del server
    giorni = await asyncio.to_thread(user_retention_days, user["id"]) if user else retention_days()
    for lang, (sempre, uno, molti) in PRIVACY_DAYS.items():
        durata = sempre if not giorni else uno if giorni == 1 else molti.format(giorni)
        body = body.replace(f"__NETMON_CONSERVAZIONE_{lang.upper()}__".encode(), durata.encode())
    body = body.replace(b"__NETMON_LANG__", request_lang(request, user).encode())
    body = body.replace(b"__NETMON_LOGO__", _LOGO_INLINE.encode())
    return Response(body, media_type="text/html; charset=utf-8", headers={"Cache-Control": "no-cache"})


