EVENTS_SHOWN = 25          # eventi per pagina se la pagina non ne chiede altri
EVENTS_SHOWN_MAX = 200     # pagina piu' lunga: la pagina la richiede a ogni aggiornamento


@app.get("/api/status")
async def api_status(user: dict = Depends(ui_user), events: int = EVENTS_SHOWN, events_from: int = 0,
                     events_q: str = Query(default="", max_length=100), events_tags: str = Query(default="", max_length=600)):
    now = time.time()
    # Eventi a pagine: `events` per pagina a partire da `events_from`. Arrivano qui, insieme al
    # resto, invece che con una richiesta a parte: cosi' a ogni aggiornamento la pagina e' coerente.
    quanti = max(1, min(int(events), EVENTS_SHOWN_MAX))
    da = max(0, int(events_from))
    probes = []
    # Database letto in un thread, e una volta sola per tutte le sonde: questa e' la richiesta
    # piu' frequente (ogni pagina aperta la ripete di continuo) e non deve fermare il server.
    def leggi():
        mine = registry.keys_of(user["id"])
        return (set(mine), *registry.pauses_for(mine, now), limits_of_user(user["id"]), account_allowance(user["id"]),
                speed_plan(user["id"], now), registry.instance_info(mine, now))
    mine, pause_sonde, pause_disp, limits, quote, turni, doppi = await asyncio.to_thread(leggi)
    for name, p in monitor.state.items():
        if name not in mine:
            continue
        silence = now - p["last_seen"]
        pausa = pause_sonde.get(name)
        if pausa:
            # In pausa lo stato resta visibile (i dati arrivano lo stesso), ma la spia non e' rossa:
            # non sta succedendo niente di cui preoccuparsi, e' una scelta.
            pstate = "warn"
            ptext = ("in pausa fino al " + local_time(pausa["until"], "%d/%m/%Y %H:%M")
                     if pausa["until"] else "in pausa")
            if pausa["note"]:
                ptext += " · " + pausa["note"]
        elif p["offline"]:
            pstate, ptext = "bad", f"offline da {fmt_duration(now - (p.get('offline_since') or p['last_seen']))}"
        elif silence > monitor.stale_after(p):
            pstate, ptext = "warn", f"in ritardo, ultimo report {fmt_duration(silence)} fa"
        elif monitor.restart_reason(p, now) and silence > monitor.stale_after(p, now) - RESTART_GRACE:
            pstate = "ok"
            ptext = (f"in ripartenza dopo l'aggiornamento, ultimo report {fmt_duration(silence)} fa"
                     if monitor.restart_reason(p, now) == "update"
                     else f"in ripartenza, ultimo report {fmt_duration(silence)} fa")
        else:
            pstate, ptext = "ok", f"ultimo report {fmt_duration(silence)} fa"
        devices = []
        for dname in ordered_names(p):
            d = p["devices"][dname]
            if p["offline"]:
                dstate, dtext = "warn", "stato sconosciuto"
            elif d["down"]:
                dstate, dtext = "bad", f"giù da {fmt_duration(now - d['since'])}"
            elif d.get("port_ok"):
                dstate, dtext = "warn", f"non risponde al ping, porta {d['port_ok']} aperta"
            elif d["fails"]:
                dstate, dtext = "warn", f"{d['fails']} ping falliti"
            else:
                dstate, dtext = "ok", ""
            devices.append({"name": dname, "state": dstate, "text": dtext,
                            "host": d.get("host"), "rtt": d.get("rtt"),
                            "prio": monitor.priority_of(d),
                            "after": monitor.fails_needed(p, d)})
        # I dispositivi in pausa non arrivano piu' nei report, quindi non sono nello stato: si
        # rimettono qui, altrimenti sparirebbero dalla pagina e non si saprebbe piu' come riprenderli.
        fermi = pause_disp.get(name, {})
        host_di = (p.get("config") or {}).get("devices") or {}
        for dname, pausa in fermi.items():
            testo = "in pausa"
            if pausa["until"]:
                testo += " fino al " + local_time(pausa["until"], "%d/%m/%Y %H:%M")
            if pausa["note"]:
                testo += " · " + pausa["note"]
            devices.append({"name": dname, "state": "off", "text": testo,
                            "host": host_di.get(dname), "rtt": None,
                            "prio": (p.get("prio_keep") or {}).get(dname, "normale"),
                            "after": monitor.fails_needed(p, {"prio": (p.get("prio_keep") or {}).get(dname)}), "paused": True,
                            "paused_until": fmt_when(pausa["until"]) if pausa["until"] else None,
                            "paused_note": pausa["note"]})
        # Dispositivi che la configurazione si aspetta ma che la sonda non ha ancora misurato:
        # appena aggiunti (dalla pagina locale o dal pannello) oppure appena ripresi da una pausa.
        # Non è un guasto, è attesa del primo ping: grigi come quelli in pausa, con la nota.
        attesi = set((p.get("config") or {}).get("devices") or {})
        # quelli oltre il limite di dispositivi non arriveranno mai: non sono «in attesa»
        quota = quote.get(name) or {"fritz": 0, "devices": 0}
        oltre = devices_left_out(name, p.get("config"), set(fermi), quota["devices"]) - set(fermi)
        in_attesa = attesi - set(p.get("devices") or {}) - set(fermi) - oltre
        for dname in sorted(in_attesa):
            devices.append({"name": dname, "state": "off", "text": "modifiche in attesa",
                            "host": host_di.get(dname), "rtt": None,
                            "prio": (p.get("prio_keep") or {}).get(dname, "normale"),
                            "after": monitor.fails_needed(p, {"prio": (p.get("prio_keep") or {}).get(dname)}), "pending": True})
        probes.append({"name": name, "label": label_of(name, p), "state": pstate, "text": ptext,
                       "paused": bool(pausa), "seen": round(silence),
                       "devices": devices,
                       "config": p.get("config"), "config_rev": int(p.get("config_rev") or 0),
                       "applied_rev": int(p.get("applied_rev") or 0),
                       "fritz": p.get("fritz"),
                       "fritz_boxes": p.get("fritz_boxes") or [],
                       "system": p.get("system"),
                       "command": {k: v for k, v in (p.get("command") or {}).items() if k != "logged"} or None,
                       "alerts": {**ALERT_DEFAULTS, **p.get("alerts", {})},
                       "low_threshold": monitor.low_threshold_of(p), "low_factor": monitor.low_factor_of(p),
                       "speedtest": speedtest_public(p),
                       # la parte dei limiti dell'account che spetta a questa sonda
                       "devices_max": probe_caps(quota)[1], "fritz_max": probe_caps(quota)[0],
                       "speed_next": turni[name][1] if name in turni else None,
                       "scans": scans_public(name),
                       "dup": dup_public(doppi.get(name))})
    def recent_events():
        with db() as conn:
            base, bargs = events_filter(user)
            where, args = events_search(base, bargs, events_q, split_tags(events_tags))
            rows = conn.execute(f"SELECT rowid, ts, title, critical, recovery FROM events WHERE {where} "
                                "ORDER BY ts DESC LIMIT ? OFFSET ?", (*args, quanti, da)).fetchall()
            total = conn.execute(f"SELECT COUNT(*) FROM events WHERE {where}", args).fetchone()[0]
            # tag presenti fra TUTTI gli eventi (non solo i filtrati): sono le scelte del filtro
            tags = conn.execute(
                "SELECT substr(title, 2, instr(title, ']') - 2) AS tag, COUNT(*) FROM events "
                f"WHERE {base} AND title LIKE '[%]%' GROUP BY tag ORDER BY COUNT(*) DESC", bargs).fetchall()
            all_total = conn.execute(f"SELECT COUNT(*) FROM events WHERE {base}", bargs).fetchone()[0]
        tags = [{"tag": t, "count": n} for t, n in tags if t and EVENT_TAG_RE.match(t)]
        return (rows, total, tags, all_total, auth.get_layout(user["id"]), auth.get_view(user["id"]),
                auth.get_dash(user["id"]), auth.expiry_of(user["id"]))
    rows, total, tags, all_total, layout, view, dash, expiry = await asyncio.to_thread(recent_events)
    # scadenza dell'account (abbonamento), se l'amministratore ne ha scelta una: la pagina la mostra
    expires = local_time(expiry["expires"], "%d/%m/%Y") if expiry and expiry["expires"] else None
    events = [{"id": rid, "time": local_time(ts), "title": t,
               "kind": "ok" if rec else ("bad" if crit else "warn")} for rid, ts, t, crit, rec in rows]
    return {"probes": probes, "server": {"name": "server", "version": VERSION},
            "events": events, "events_total": total, "events_from": da,
            "events_all": all_total, "event_tags": tags,
            "server_version": VERSION,
            "probe_dist_version": await asyncio.to_thread(probe_dist_version),
            "probe_dist_same": await asyncio.to_thread(probe_dist_same),
            # limiti dell'account: la pagina mostra quante sonde e quante FRITZ!Box si possono collegare
            "user": {"email": user["email"], "layout": layout, "view": view, "dash": dash,
                     "limits": limits, "expires": expires}}


@app.post("/api/order")
async def api_order(o: Order, user: dict = Depends(ui_user)):
    owns(user, o.probe)
    async with lock:
        p = monitor.state.get(o.probe)
        if p is None:
            raise HTTPException(status_code=404, detail="sonda non trovata")
        p["order"] = [n for n in o.order if n in p["devices"]]
        save_state()
