def bump_config_rev(p):
    """Fa ripartire lo scambio della configurazione: la sonda la riceve al prossimo report."""
    p["config_rev"] = max(int(p.get("config_rev") or 0), int(p.get("applied_rev") or 0)) + 1


@app.post("/api/device/pause")
async def api_device_pause(b: DevicePause, user: dict = Depends(ui_user)):
    """Ferma il ping verso un dispositivo per un po'.

    Non e' «non avvisarmi»: la sonda smette proprio di mandargli pacchetti, quindi non ci sono
    nemmeno le misure. E' la differenza con la priorita' «mai», che continua a misurare in
    silenzio: qui il dispositivo e' spento o staccato apposta, e tenerlo nel grafico come
    irraggiungibile per un mese sporca lo storico senza dire niente di utile.

    L'ultimo dispositivo rimasto non si puo' mettere in pausa: una sonda senza niente da pingare
    non e' una configurazione valida. Per fermare tutto c'e' la pausa della sonda.
    """
    owns(user, b.probe)
    async with lock:
        p = monitor.state[b.probe]
        in_pausa = await asyncio.to_thread(registry.device_pauses, b.probe)
        elenco = set((p.get("config") or {}).get("devices") or {}) | set(p.get("devices") or {})
        if b.device not in elenco:
            raise HTTPException(status_code=404, detail="dispositivo non trovato")
        if b.device not in in_pausa and len(elenco - set(in_pausa)) <= 1:
            raise HTTPException(status_code=409, detail="È l'ultimo dispositivo attivo della sonda: "
                                                        "per fermare tutto metti in pausa la sonda.")
        until = time.time() + b.hours * 3600 if b.hours else None
        await asyncio.to_thread(registry.pause_device, b.probe, b.device, until, b.note)
        tolto = p.get("devices", {}).pop(b.device, None)     # sparisce subito dalla pagina, non al giro dopo
        if tolto and tolto.get("prio"):            # la priorità resta: torna con il dispositivo
            p.setdefault("prio_keep", {})[b.device] = tolto["prio"]
        bump_config_rev(p)
        save_state()
    log.info("Ping verso '%s' (%s) in pausa da %s%s", b.device, b.probe, user["email"],
             f" fino al {local_time(until, '%d/%m/%Y %H:%M')}" if until else " (senza scadenza)")
    return {"ok": True, "paused_until": fmt_when(until) if until else None}


@app.post("/api/device/resume")
async def api_device_resume(b: DeviceRef, user: dict = Depends(ui_user)):
    """Il ping riprende: la sonda riceve di nuovo il dispositivo al prossimo controllo."""
    owns(user, b.probe)
    await asyncio.to_thread(registry.resume_device, b.probe, b.device)
    async with lock:
        bump_config_rev(monitor.state[b.probe])
        save_state()
    log.info("Ping verso '%s' (%s) ripreso da %s", b.device, b.probe, user["email"])
    return {"ok": True}


@app.post("/api/priority")
async def api_priority(b: DevicePriority, user: dict = Depends(ui_user)):
    """Priorità di notifica di un dispositivo. La soglia dei "bassa" non si tocca qui: vale per
    tutta la sonda e si imposta con le altre notifiche (/api/probe-alerts)."""
    owns(user, b.probe)
    async with lock:
        p = monitor.state.get(b.probe)
        if p is None:
            raise HTTPException(status_code=404, detail="sonda non trovata")
        d = (p.get("devices") or {}).get(b.device)
        if d is None:
            # appena aggiunto (la sonda non l'ha ancora misurato) o in pausa: la priorità resta da
            # parte e vale appena la sonda torna a misurarlo (Monitor.process_report)
            in_pausa = await asyncio.to_thread(registry.device_pauses, b.probe)
            elenco = set((p.get("config") or {}).get("devices") or {}) | set(in_pausa or ())
            if b.device not in elenco:
                raise HTTPException(status_code=404, detail="dispositivo non trovato")
            keep = p.setdefault("prio_keep", {})
            for nome in [n for n in keep if n not in elenco]:
                keep.pop(nome)                   # dispositivi tolti nel frattempo
            if b.prio == "normale":
                keep.pop(b.device, None)
            else:
                keep[b.device] = b.prio
            d = {"prio": b.prio}
        elif b.prio == "normale":
            d.pop("prio", None)                  # il valore predefinito non si salva
        else:
            d["prio"] = b.prio
        save_state()
        return {"ok": True, "prio": monitor.priority_of(d), "after": monitor.fails_needed(p, d),
                "low_threshold": monitor.low_threshold_of(p), "low_factor": monitor.low_factor_of(p)}


# Le letture dello storico (grafici e Dashboard) possono durare anche più di un secondo su
# periodi lunghi. Girano in un thread, così il server intanto continua a ricevere i report; al
# massimo HEAVY_SLOTS insieme per tutto il server (i thread restano liberi per il resto) e
# HEAVY_PER_USER per account, perché un solo utente non faccia aspettare tutti gli altri. Chi ne
# accoda troppe riceve 429 invece di riempire la coda.
HEAVY_SLOTS = 4
HEAVY_PER_USER = 2
HEAVY_QUEUE_PER_USER = 8
_heavy_slots = asyncio.Semaphore(HEAVY_SLOTS)
_heavy_users = {}                     # id utente -> [semaforo, richieste in corso o in attesa]


async def heavy(user, fn):
    """Esegue fn (lettura del database) in un thread, rispettando i limiti qui sopra."""
    uid = user["id"]
    slot = _heavy_users.get(uid)
    if slot is None:
        slot = _heavy_users[uid] = [asyncio.Semaphore(HEAVY_PER_USER), 0]
    if slot[1] >= HEAVY_QUEUE_PER_USER:
        raise HTTPException(status_code=429, detail="Troppe richieste di grafici insieme: riprova tra poco.")
    slot[1] += 1
    try:
        async with slot[0], _heavy_slots:
            return await asyncio.to_thread(fn)
    finally:
        slot[1] -= 1
        if not slot[1]:
            _heavy_users.pop(uid, None)


@app.get("/api/history")
async def api_history(probe: str, device: str, range: str = "6h", start: Optional[float] = None,
                      end: Optional[float] = None, user: dict = Depends(ui_user)):
    """Storico dei ping di un dispositivo, raggruppato in punti di ampiezza fissa."""
    owns(user, probe)
    since, until, bucket = time_window(range, start, end, RANGES, 60)
    def leggi():
        with db() as conn:
            points = conn.execute(
                "SELECT CAST(ts / ? AS INTEGER) * ? AS b, AVG(rtt), MIN(rtt), MAX(rtt), "
                "       SUM(CASE WHEN ok = 0 THEN 1 ELSE 0 END), COUNT(*) "
                "FROM samples WHERE probe = ? AND device = ? AND ts >= ? AND ts <= ? GROUP BY b ORDER BY b",
                (bucket, bucket, probe, device, since, until)).fetchall()
            stats = conn.execute(
                "SELECT MIN(rtt), AVG(rtt), MAX(rtt), "
                "       SUM(CASE WHEN ok = 0 THEN 1 ELSE 0 END), COUNT(*) "
                "FROM samples WHERE probe = ? AND device = ? AND ts >= ? AND ts <= ?",
                (probe, device, since, until)).fetchone()
        return {
            "bucket": bucket, "since": since, "now": until,
            "points": [{"t": b, "avg": avg, "min": mn, "max": mx, "lost": lost, "n": n}
                       for b, avg, mn, mx, lost, n in points],
            "stats": {"min": stats[0], "avg": stats[1], "max": stats[2],
                      "lost": stats[3] or 0, "samples": stats[4] or 0},
        }

    return await heavy(user, leggi)


